/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160516-9","meetingId":"h28-cm05","date":"2016年5月16日","dateIso":"2016-05-16","committee":"文教委員会","time":"午後１時００分～午後４時２５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"やはりこの間は、中学生とか高校生、感じやすい年ごろのお子さんの自殺のところで、いじめの問題が取り上げられるのは常だと思うので、その辺の現状においての、どこまで調査が進んでいて、どう判断しているのかということを１点お伺いしたいのと、あと、今日の臨時保護者会なのですけれども、この内容は学年にかかわっているのか、全校の保護者の皆さんなのかということと、あと、ぜひ、私。","respondent":"熊谷指導課長","answer":"そこのところをお伝えしたいと思います。それから２点目の保護者会ですけれども、それにつきましては、当該学年だけではなく、保護者全員に対して保護者会を実施していく予定です。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"面談から、いじめ、特定の人間関係で悩んでいたのではないという受けとめ方なのですが、今日いただいた資料の中では、部活動の生徒一人ひとりに対する面談を実施というところにおいてはわかったのですが、この２人のお子さんが同じクラスだったかどうかも把握の上でわからないので、関係しているクラスの子どもたちの状況が、その下に書いてある健康調査、これだけだったのかどうか。","respondent":"熊谷指導課長","answer":"学校の対応のところにありますように、１１日から当該学年、すなわち所属していた学年全員と、それから部活動、同じ部活動に所属しておりましたので、その部活動に所属しているお子さん全員に面談を行っています。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では、広くケアを必要とされるお子さんを早くキャッチをして対応していただきたいということが１つお願いです。いかがでしょうか。","respondent":"村尾教育総合支援センター長、熊谷指導課長","answer":"子どもたちの心のケアということで、広範囲にということで今お話をいただきました。教育委員会のほうから、全ての学校を対象に、翌日５月１０日から、子どもの欠席状況を全て確認いたしました。教員に対するケアですが、その翌日から都のアドバイザリースタッフという緊急対応を行う心理士が入りまして、先生方のケアにつきましても行っています。産業医等もお願いして実際に対応しています。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味で、私はすごく今、職員会議が不十分であるという声を聞いているのですが、職員会議が１回どのくらいで何回ぐらい行われているのかということもお伺いしたいのですが、ぜひ学校を超えて事例を共有してほしいのと、やはりよりよい事例が必ずあると思うのです。そういうものを十分に生かした全体のものにしていただきたいと思うのが１つです。","respondent":"熊谷指導課長、品川庶務課長、村尾教育総合支援センター長","answer":"先ほどもお話ししたように、いじめの徴候が全くない、いじめで悩んでいた様子が見られなかったということ、それから保護者の方のお気持ちもありますので。この事件の翌日、５月１０日ですけれども、総合教育会議も行いまして、区長と教育委員で、この事件に関しての情報共有をしている状況です。区内の全ての学校の教職員の皆さんへという部分につきましては、先ほど、教育長が申しましたとおり、すぐに臨時の校長会を開きまして、各学校で改めて。","id":"exchange-004"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"なので、今日のこの会で構わないけれども、いろいろな方々がいろいろな意見をおっしゃって非常に混乱するし、大きな話題になる可能性のある案件なので、情報の取扱いに十分注意しながら、内容を確定した後に、正しい情報を議会に適切な場で報告をしていただきたいと思うのですが、いかがでしょうか。","respondent":"本城教育次長","answer":"先ほども少しご答弁させていただきましたが、今日まさに保護者会ということで、直接保護者の方に対して校長先生のほうからお話をするですので、それも含めて、今後のこの文教委員会におきまして、保護者会を含めた経緯の報告という形で、何らかの形で。","id":"exchange-005"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"要望だけしますけれども、こういう重篤な案件ですと、いろいろなうわさが出たり、それからいろいろな思いでお話しされることがたくさんありました。過去のことも。だから、そんなことで無用なこの、できないわけであって、プレスが教育委員会から正しい情報をつかんで、それを処理をして判断をして、しかるべき時期に議会に報告をする。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私も街頭などに立っていますと、地域の方から声をかけられるわけです。品川は今、施設一体型、また分離型とあるわけですけれども、その方は、校名も出して、そして一体型か分離型かということも出して問いかけてくるわけです。教育委員会としては、まだ今は名前を出せない状況かもしれませんけれども、今後こういった検討を進めていくという姿勢を持っていただきたいと思うのですけれども、いかがでしょうか。","respondent":"熊谷指導課長","answer":"報道なのですけれども、警視庁からも一切学校名は出さないということで、それはすり合わせをしています。なぜならば、今いるお子さんたちの正常な学校生活を守るためにも、警察は学校名を出さないということで出していませんので、それをお伝えしておこうと思います。","id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"この２人の女子中学生の方は非常に痛ましい結末を迎えて、心からお悔やみを申したいと思いますが、一般論として考えてみると、このぐらいの年齢の思春期の女性は、女性に限らず男もそうですけれども、自殺があったとか、自殺未遂とか、そういう案件は決して少なくないような気もする。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"意見","question":"今、鈴木博委員のほうからお話があったこととあれですが、痛ましい出来事ということなので、いわゆる自死の連鎖がどの年代の子どもでも必ず起きて、より大きな問題になってしまうので、今、鈴木博委員からお話があったように、負の連鎖ではありませんけれども、そういうことがないように十分、今後の指導をよろしくお願いしますということで、いわゆる命の大切さというか、そういったことを含めて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"大倉委員","kind":"質問・要望","question":"」と思ったときに対応できるような体制を今後どうやって、これをしっかりとっていかなければいけないと思うので、その辺をどうやって考えているかということを教えていただきたいのと、あと、報道等でも先ほどもありました外観が映っているとか、あとはその当該学校の前の報道陣の方とか、いろいろな方々が車をとめて校門の前とかにいるという状況があるというふうに聞いているのですが。","respondent":"熊谷指導課長、村尾教育総合支援センター長","answer":"実際になかなか見づらいところ、これまでにはなかった部分、さまざまな子どもたちの心の変化ということも時代によって変わってくるところもあろうかと思いますので、そういったことについても対応できるように。報道関係につきましては、まさに学校の周りに当初すごく多くの方がいらっしゃいました。ただ、区といたしましては、品川ニュースということで、基本的にはマスコミにプレスリリースをかけるようにということで対応してきました。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"それと、５月９日午後６時２３分から時系列で出ているのですけれども、その中でやはりちょっと気になるのが、このように情報が入ってくる中で、警察から学校へというものと、夜遅くなってから荏原警察から指導課とあるのですけれども、このような事件にしろ事故にしろ、さまざまな問題が発生する可能性がありますけれども、そういうときの危機管理体制というのでしょうか。","respondent":"村尾教育総合支援センター長、熊谷指導課長","answer":"１点目の自殺関係についての予防の取組みですけれども、昨年度以来、事あるごとに生活指導の部分で、いじめも含まれていますけれども、自殺予防ということで、各学校に通知をし、特に各学校で気になる。この中で荏原警察から指導課にということで、１０時５０分、プレスが出ますということの連絡が入ったとありますけれども、この前にこちらから荏原警察に一報を、学校の情報を踏まえて連絡を入れていますので、それを受けて。","id":"exchange-011"},{"speaker":"浅野委員","kind":"質問","question":"ありがとうございました。危機管理体制は、例えば手順とかがある程度決まっていると思うのですけれども、もしその概要を、極めて簡単で結構ですので、どこが一報が入る、そうした場合に、これは事件、事故とかいろいろあると思うのですけれども、どういう体制で教育委員会の中に入ってくるのか。区長部局のほうにもどういう形で入っていくのかということについて、簡単に教えていただけますか。","respondent":"熊谷指導課長","answer":"学校から教育委員会の指導課もしくは総合支援センター、どちらかに入ってきます。その上で区長部局には、今回は次長が横にいらっしゃったので、次長から全部連絡を入れていただき、基本的にはすぐに状況について区長部局に入れていくことになっております。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こういうものがどのように使われているのかと思ったもの。そういった意味においては、私は一番にはゲートキーパーである先生たちが、その職場でどう話をするのか、それをどうつなげていくのかというところが本当に重要である。さっき、職員会議のことも伺ったので、そこの辺も含めて、ぜひぜひそこのところを構築していただきたいと思うことを最後の質問といたします。よろしくお願いします。","respondent":"村尾教育総合支援センター長","answer":"ただ、今回の件におきましては、改めて私どもも、このような体制を検討を進めていこうというふうに考えています。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一言。だから、仕組みはあるのだと思うのですが、そこでやはり一番子どもたちに身近にいらっしゃる方々の声を忌憚なく出してもらえるような、一番には私は各学校の職員会議だと思いますし、それを拡大していくような取組みをぜひぜひお願いしたいと思いますので、これはお願いでよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"平成２８年度新入学学校別増減要因一覧","agenda":"平成２８年度新入学学校別増減要因一覧","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"１点だけお伺いしたいと思います。この生徒たちは、どの辺を選んで行っているのかということがわかったら教えてほしいのと、この辺、７年生で学校が変わるという要因が何かを捉えていらっしゃるのかどうか教えていただきたい。","respondent":"有馬学務課長","answer":"荏原平塚学園で学区外へ１４３人という非常に多くの方が抜けているですけれども、これは一貫校ではありますけれども、もともとここには平塚小学校の区域がそのまま荏原第一中学校に行くというようなことがございまして、その傾向が今でもあるということで、要するに。","id":"exchange-015"}]},{"id":"topic-03","title":"平成２７年度品川区立学校における体罰等の実態把握","agenda":"平成２７年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"２ページ目の(2)の体罰以外と判断した事案例を見ても、ひどいなとちょっと感じるのです。体罰ではない、不適切な行為ということなのですけれども、やはりこれを受けた生徒としては、体罰と感じるのではないかと思うのですけれども、これが不適切な行為になるのはなぜなのかということを伺いたいと思います。","respondent":"熊谷指導課長","answer":"ご質問がありましたこの不適切な指導につきましては、これは都の教育委員会の人事部が、これは不適切な行為であるということで判断しておりますので、これにつきましては、私どものほうから不適切な指導ということで上げているものではなく。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、親も子どもたちも教員の多忙化を知っているという状況のもとで、教職員の皆さんの意識を高めていくというのはわかるのですけれども、どうしてこういうふうになったのかということを、根絶のためということで３ページにあると思うのですけれども、研修、研修、研修ということで、教員の皆さんは本当に大変だなというふうに、ここでもまた改めて思うのですけれども。","respondent":"熊谷指導課長","answer":"多忙ということがありますが、教員は忙しいからといって体罰を引き起こすわけではない。どんなに忙しくても、体罰につながるということは絶対に認めてはいけないというふうに思っていますので、これにつきましては、今後とも引き続き厳しく指導をしていきたいと考えています。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問・要望","question":"ふだんから多分この件につきましても、教育委員会としては発生をしないように取り組んでおられると思いますけれども、例えばそれが発見されるとか、そういうようなことは過去にあったかと思いますけれども、もし事例があれば教えていただきたいのと、これが発生した場合に、どのような対処をしていくのか、今回の報告の中にも含まれないということになっているので、少し気になって質問しますが。","respondent":"熊谷指導課長","answer":"どちらにしても、暴言であったり、不適切な指導であったり、こういったことは絶対に認められないのだということを学校全体でしっかり理解した上で、教員一人ひとりが自覚してそういったことを行わないようにしていくことが重要だと思いますので、引き続き。","id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"質問","question":"チビ。バカ」と大きな声で叫ぶ。東京都教育委員会ということで、直接品川区ではないかもしれないのですけれども、このシチュエーションが不適切な例として挙がっているということは、当然これは間違ったことをやったということだから、では、正しいことは対で当然あるはずなので、では、先生はどういう正しい態度をとったらよかったのか、僕はいくら考えてもわからないので教えてほしいのです。","respondent":"熊谷指導課長","answer":"〔「では、故意に足をヒットした、４回やったというのが不適切な指導に当たる」と呼ぶ者あり〕 〔「ただおろした。","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"わかりました。別のことをお聞きします。これ、分類例の不適切な指導に、「おでこを弾く（デコピン）」とあるのですけれども、これは要するに、額をピッとたたくことですね。それは不適切な指導になるのですか。","respondent":"熊谷指導課長","answer":"どこまでがという具体的な部分はなかなか難しい部分もあるのですけれども、ただ、やはりこれは体罰ではないにしても、たたいたりですとか、それからおでこを弾いたり、いわゆるデコピンというのは不適切な指導であるというふうに分類上は記されております。","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最後なのでもう１つお聞きしたいのですけれども、この指導の範囲内で、「寝ている生徒の肩を叩いて起こす」と書いてあるのですけれども、これは、行き過ぎた指導かどうかの分類の指導の範囲内に入ることなのでしょうか。","respondent":"熊谷指導課長","answer":"これは授業中に寝ている生徒の肩を起きなさいということでたたいていますので、これは指導の範囲ということで。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１つ１つの事例で必ず原因とか結果があるので、先生方もみんな別に生徒をいじめようと思ったり、体罰をしようと思ったりして対応する人などいないと思うのです。ただ、やはりある程度、この子のためにこういうことをやりたいと先生が考えて行動する行動は、多少の強制力を伴うこともあるのではないかと思うのですけれども、そういうことも全て否定されるのでしょうか。","respondent":"熊谷指導課長","answer":"そういった中で、こういった事例に当てはまるかどうかということを確認していくと同時に、また、実際にどういう状況であったかも全て含めて報告をしていますので、例として分類は出されてはいますけれども。","id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最後に１つお聞きしたいのですけれども、例えば今、言うことをきかないような行動をとる小学生が随分いますけれども、例えば教師が指導したときに生徒がそれに従わなかったらどうしたらいい。納得するまでお話し合いをしたらいいのですか。","respondent":"熊谷指導課長","answer":"どちらにしても、やはり体罰という形でやることは絶対に認められないことですので、やはり子どもにはきちんと言葉で説明し指導していくということが重要であるというふうに考えております。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"僕はやはりそうだと思うのです。だから、いじめにしろ、教育にしろ、あるいは教師の体罰だと言われている事件にしろ、やはり子どものことを考えているか、生徒のために考えているかどうかということが一番大事だから、その辺の過去をしっかり踏まえた上でいろいろな対策を考えていただきたいと思うのですが、これは僕の要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なぜかというと、その辺で理解の違いで不信感というか、やはり子どもも職員も保護者も信頼関係にのっとった教育を高めるという意味で、その辺がどうなっているのかということを伺いたいのが２点目です。共有できているのか。ただ数的に報告をして取りまとめているのか、自分の学校の状況が現場で把握できているのか、そういうことをやっているのかどうかを教えてください。","respondent":"熊谷指導課長","answer":"それから３点目が、中で情報共有ができているかということですけれども、もちろんこういった事案につきましては、校内で二度とそういったことが起こらないようにということで、情報共有していると同時に。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"意見","question":"すり合わせがされているということなのですが、そういった面で、例えば不具合が生じているというか、うまく信頼関係ができていなくて問題になったようなことはないのかどうか、その１点だけ。","respondent":"熊谷指導課長","answer":"現段階では、そういった事案については発生してございません。","id":"exchange-026"},{"speaker":"大倉委員","kind":"確認","question":"今の申告者別報告数で、すり合わせもお互いに認識しているということは確認したのですが、教員本人の方が５１件あって、学校別、これが児童・生徒本人と同じ認識がある件数はあるのですか。","respondent":"熊谷指導課長","answer":"ただ、これからも引き続き丁寧に指導していきたいと思っています。","id":"exchange-027"},{"speaker":"大倉委員","kind":"質問","question":"申告者別報告数ではある程度合っているということで、あと若干気になっているのは、例えば大体同じ件数であるとするならば、１９件と２８件のこの辺の差はどういうところなのかと思っているのですが、その辺を教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"伊藤副委員長","kind":"意見","question":"気になったことが、指導課の配付資料の中で、久々に「施設一体型一貫校」という表現になっているのです。「義務教育学校」に統一されているのではないかと思ったのですけれども、あえてそういう書き方なのかが１点と、それから、まとめて聞きますけれども、今のアンガーマネジメントは非常にすばらしいことだと聞いているのです。お願いします。","respondent":"熊谷指導課長、村尾教育総合支援センター長","answer":"こちらの調査なのですが、平成２７年度、昨年度の調査ですので、「施設一体型」という書き方をしております。研修につきましては、センター長からお伝えします。このアンガーマネジメントの研修については、昨年度も実施をしており、今年度も校長連絡会を通し、また、特に各学校の主幹教諭、また生活指導主任等も広く情報を流しながら、各学校で必ず先生方。","id":"exchange-029"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"要は要望なのですけれども、繰り返し、各委員からもお話があったように、いろいろなケースがあって、教員もやはり人間ですから、時と場合によっては、それはいろいろな感情をお持ちになります。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-04","title":"平成２９年度品川区立学校教育職員採用候補者選考日程","agenda":"平成２９年度品川区立学校教育職員採用候補者選考日程","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"選考の日程のところで、昨年の応募状況と採用人数を教えてください。今回の採用予定人数６名程度というところの根拠も聞かせていただきたいのが２点目です。資格要件のところなのですが、小学校免許と中学校の免許の両方を所持する者、なかなか大変だと思うのですが、現状において何％、この両方を持たれている先生がいらっしゃるのか教えてください。","respondent":"熊谷指導課長","answer":"中学校教諭の普通免許状所持者は７名、両方持っている者は１１名です。６名の根拠でありますけれども、まだ全ての学校に、そもそも予定している固有教員を満たしておりませんので、６名ということで、今年度は、昨年度採用できなかった人数も含めて６名程度を考えてあります。","id":"exchange-031"},{"speaker":"伊藤副委員長","kind":"確認","question":"まさか全ての教職員を区固有にしようと思わないので、中長期的な中で、採用人数が何名で、こういう形で将来はこういうふうにして区固有職員と都費の職員のバランスをとっていくなり、大きな構想がまずあってほしいと思うのですけれども、それはあるのでしょうかという確認と、それから、目指す目標をもう一度教えてください。お願いします。","respondent":"熊谷指導課長","answer":"中長期的な目標につきましては、今の段階でお答えできないのですけれども、ただ、やはり品川区立学校の固有の教員ということで、まずは品川区のことを一番知っている、そして子どもたちが卒業してもずっと相談できる先生ということで。","id":"exchange-032"},{"speaker":"伊藤副委員長","kind":"意見","question":"だけれども、それをどういうふうに活用していくことの説明もいい、だけれども、今後その３０名をどうこれから育てていくか、より具体的な品川区の教育を受けて展開して、どういうふうに使っていくかということについての次のステップについて、そろそろ教育委員会で具体的に検討して、例えば５年後、１０年後のプランをつくって具体的な計画を考えるべきだと思うのですが、お考えだけお聞かせください。","respondent":"熊谷指導課長","answer":"平成２１年度から区の固有教員を採用してまいりましたけれども、やはりそこから８年目ということになりますので、将来的な部分についても検討していく必要があるかと思います。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"意見","question":"(2)を加えた理由と、具体的に３年以内にというふうな手立ては、どのようなことを、先生がどう取るかという意味でのことと、それを教育委員会としてどうバックアップするか、持ち時間とか、いろいろなところが出てくると思うのです。その辺について、仮定の話になってしまうのですが、具体的にお考えというか、予定があればお話しください。","respondent":"熊谷指導課長","answer":"ですので、今回、中学校教員免許状ということで、上級学校の免許を持っているということで、小学校の前期課程でも専門の科目を指導することができますので、そういったことで中学校の教員免許を持っていて。","id":"exchange-034"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-05","title":"適応指導教室マイスクール五反田の開設","agenda":"適応指導教室マイスクール五反田の開設","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"違いはわかりました。３年生から６年生の子どもたちの居場所は、マイスクール八潮で足りているのでしょうか。その辺の需要について１点お伺いをしたいと思ったところと、体験を含め６カ月以内というこの辺のめどは、どの辺から来ているのかということを１点お聞かせいただきたいのと、あと、指導員のところなのですが、教育相談員と学校経営監という、この方たちの身分というか、資格を教えてください。","respondent":"村尾教育総合支援センター長","answer":"八潮との比較になります。ご案内のとおり、マイスクール八潮は、ここに書いてあるように、学習室もあり、音楽室、校庭、体育館ということで、集団的な活動ができるのに対して、どうしてもスペース的に五反田のほうはできないというような施設の問題点があります。","id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"中学生、７年生以上のところが多くなっているというところにおいては、新しい試みのマイスクール五反田であるというところにおいては期待をしたいと考えています。が、ぜひ小学校の不登校のところ、数が実際増えているかどうかもわからないのですが、結構小学校のところでも悩んでいるお子さんの話も聞くので、その辺の対応もぜひ力を入れていただきたいと思っています。","respondent":"村尾教育総合支援センター長","answer":"２点目につきましては、今、国のほうでフリースクールを含めてさまざまな検討がされていて、すぐにはまだ法案は通っていないのですが、その辺の国の動きも十分見ながら、やはり今後、子どもたちの学習の場面であったり。","id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"後段のところ、ぜひ区内でいろいろ不登校問題、子どもたちのことを取り上げて頑張っているところもあるので、ぜひお話を聞く機会を持ちながら検討を拡大していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"意見","question":"体制のことなのですけれども、マイスクール五反田室長ではないですけれども、そこの責任というか、まとめ役みたいな方は、五反田のほうにいらっしゃる指導主事の方なのか、それとも指導員、学校経営監の方なのかということなのですが、なぜかというと、延べにすると結構な生徒が来ることになるので、何とか君は何とか中学校と連絡をとれているとかという、そういう把握。","respondent":"村尾教育総合支援センター長","answer":"この指導員がさまざま打ち合わせの中で、個別にメンタルフレンドとの連携を図ったり、個々の状況把握、また学校との連携等、ある意味、ここが中心に仕切っていく、そういうような体制で進めていこうと考えています。","id":"exchange-039"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうなると、教員免許所持者という形であるのですが、ただ、もちろん教員経験の方、１０人以上の中学生を全体を把握していくというところに関しての運営のところがちょっと不安な点があるのですけれども、その点はどういうふうに進めていかれるのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"ただ、当然、個人情報等の確保もありますし、学校との連携の仕方が複雑になってきますので、十分検討させていただければと考えています。","id":"exchange-040"},{"speaker":"高橋（し）委員","kind":"意見","question":"在籍校と連携をしていくという点も、今お話があったように、かなり細かいところまでやらなければいけないと思うので、この開設は非常にいい試みだと思って大変期待をしているので、ぜひうまく回るように、子どもたちがまた学校に戻れるような形で進めていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今の高橋しんじ委員の続きなのですけれども、メンタルフレンドというのは、これはどういう資格で、どのような方を想定されているのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"最初は、大学生、希望して、または募集をしてとは思ったのですが、急に休んだりすると、その都度、対応ができないので、きちんとした対応ができるような形で外部委託というふうに考えています。","id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ちょっと僕のイメージと違っていたのですけれども、教員志望や心理学専攻の大学生が来るのかと思ったのですけれども、何が心配かと思ったのは、教員だとか心理学だとか勉強中の学生が、不登校の子どもを変にいじくって、こういう子どもは、結構、いじくると悪くなってしまって、かえって悪化したりすることもあると思うので、そういう面で、例えばこういうメンタルフレンドというような方は。","respondent":"村尾教育総合支援センター長","answer":"そのときに、不登校の子どもたちの現状であったり、またはかかわり方については、きちんとした研修を設けてもらう、そのうえで改めてセンターのほうに来ていただいて、子どもたちの扱いについては、学校経営監の先生方はもともと教員の経験者ですので。","id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"スタッフが監督するというふうに理解してよろしいわけですか。学校経営監だとか、指導員みたいな、そこにいらっしゃる方がメンタルフレンドを統括しているというふうに考えてよろしいのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"はい、そのとおりです。指導員または学校経営監が育成をしていくということと、指導していくということになります。","id":"exchange-044"}]},{"id":"topic-06","title":"すまいるスクール利用料の減免処理の遅れ","agenda":"すまいるスクール利用料の減免処理の遅れ","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"システム開発が終了したことで解消済みであるということで、５月下旬には関係のお知らせと、口座に返納を行うということなのですけれども、数字の関係なのですが、一番下の登録数８,７１６人のうち、この利用料、(1)、(2)、(3)、利用時間別、これの人数の内訳がわかれば教えていただきたいのと、次の減額と免除の方が全体で２,５１３件ということですけれども、これも減額。","respondent":"高山子ども育成課長","answer":"今持ち合わせている数字としまして、１９７件の今回のご迷惑をおかけいたしました方々のうちの１７時までの利用の方が１４４人、１８時までの利用の方が４２人、１９時までの時間帯が１１人ということで、これらの合計が１４４人、４２人、１１人と足しましたところ１９７人の方。","id":"exchange-045"},{"speaker":"浅野委員","kind":"質問","question":"たしか去年の９月の委員会だったと思いますけれども、スタート時にエラーが発生しないようによろしくお願いしますと質問をさせていただいたことを思い出したのですけれども、やはりこういうシステムの開発は非常に、後からわかることとか、追加になることとかあると思うので、二度とないとは思いますけれども、最後に迷惑を受けるのが区民の方ということになりますので。","respondent":"高山子ども育成課長","answer":"減免の申請の件数につきましては、やはりおおむね３割程度の方の申込みがあろうかという見込みを当初しておりましたので、今回、２８％ということですので、大体統計的な誤差の範囲というふうな幅と考えておるところです。","id":"exchange-046"},{"speaker":"浅野委員","kind":"質問","question":"ありがとうございました。登録数、それと減免の数という形で伺いました。この数字については、多い少ないとか、いろいろ論議はあるかと思いますけれども、子どもたちがすまいるスクールを楽しみにされているということもありますので、これからも発展するように努めていただければと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"伊藤副委員長","kind":"質問","question":"減免処理が遅れた理由の中で契約の関係でお伺いしたいのですけれども、原因が「想定よりシステム構築が複雑化し、開発に多くの時間を要した」こととすれば、原因は品川区側にあるということでいいのですね。そうすると、プログラム作成会社への追加の品川区の負担が生じたということがありますでしょうか。お聞かせください。","respondent":"高山子ども育成課長","answer":"仕様に基づく開発ですので、当初見込んでいた作業日よりも若干時間がかかったでありますとか、あるいは複雑化したということで、受託者側であります業者等にこの責任はないということが１つあります。","id":"exchange-048"},{"speaker":"伊藤副委員長","kind":"確認","question":"確認しますけれども、システム自体は３月に完成しました。だけれども、その中でこれが遅れたのですよね。ということは、当初、品川区の仕様からすれば、これも入ったものが３月にできる予定だった。その辺のもう少しわかる説明をお願いいたします。","respondent":"高山子ども育成課長","answer":"ご説明が不親切で大変申しわけございませんでした。","id":"exchange-049"},{"speaker":"伊藤副委員長","kind":"質問","question":"それがたまたま年度末にあって、その後の事務処理部分で遅れたということなのですか。だからこそ余計に関連しているのは、では、なぜ遅れてしまったのか。わかっていることでしょう。それに対して事務的な体制もとっているべきだと私たちは思っていたのだけれども、できなかったということでは、議会としてはちょっと厳しくやらなければいけないと思うのですが、いかがですか。","respondent":"高山子ども育成課長","answer":"委員ご指摘のとおり、当然システム開発と並行して事務処理手続が早期に始められる、これを前提とした４月の引き落としの処理に間に合わせる、そのような当初の全体スケジュールで考えていたところです。","id":"exchange-050"},{"speaker":"伊藤副委員長","kind":"確認","question":"まとめますけれども、私は、皆さんの仕事はすばらしいものだと思っていますし、このことで批判するつもりもないのです。それはぜひご理解ください。ただ、そういう目標年度があって、この話についてはシステム自体は完成していたとするならば、やはりその後の事業展開の中で起こった原因についてはぜひ確認をしていただいて、これからはこういうことがないように対応をよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]},{"id":"topic-07","title":"平成２８年４月の入園状況","agenda":"平成２８年４月の入園状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"配っていただいた資料の裏面の一番下の表です。これの不承諾数と待機児童数のゼロ歳から５歳の内訳がわかれば伺いたいのですが。","respondent":"大澤待機児童対策担当課長","answer":"不承諾の内訳です。不承諾のほうですが、ゼロ歳が２３１人、１歳が４０１人、２歳が２５２人、３歳が６５人、４歳が１４人、５歳が８人ということで、計９７１人となります。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２７０人定員よりも多いのですが、この中身が、定員拡大が行われているところもあると思うのですが、あと、弾力化もあるのかどうか。あるのだったら、それぞれどういう具合でここの定員以上、プラス２７０人になっているのか、ここを教えていただきたいのが１点です。","respondent":"竹田保育課長","answer":"それから裏面の私立のほうの経営のことですが、何社かにお話を聞いたところですが、年齢の高い児童が当初は埋まらないというのは、どこの園でも開園時に起こることですので、これは想定しているところですということでお話を聞いております。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認可保育園なので、基準があるのでなかなか難しいとは思うのですが、埋まらない部分の年齢を置きかえて工夫をするということができないのかどうかが１点と、もう１つは、教えていただきたいけれども大変かと思っているのが、認可保育園に入園できた方の指数、点数と、階層別にどこの階層の方が入っているのかという一覧表をいただけたら、個々で伺うとわかるのですが。","respondent":"竹田保育課長","answer":"入園できた方の指数ですが、個別にお答えしていますので、一覧表というのも難しいかと考えております。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"後段のところなのですが、個別にお答えということは、個別とはどういうことなのか、議員としては求められないということなのか、そこの個別にお答えという中身を教えてください。","respondent":"竹田保育課長","answer":"園によっては、年齢で１人しか入れないような園もありますので、そこで最低点を、指数を公表すると、その園のその方の指数がわかってしまうということもありますので、全ての公表は難しいです。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"順番、順番はわからないと思う。何か工夫をして出していただける方法はないでしょうか。お願いですがいかがでしょうか。","respondent":"竹田保育課長","answer":"委員のご質問ですが、お求めになられている内容等が今はっきり把握できませんので、別途ご相談させていただきたいと思います。","id":"exchange-056"},{"speaker":"伊藤副委員長","kind":"意見","question":"今年１年お疲れさまでございました。最後の最後に来て、とても大きなものございましたけれども、文教委員会としては、子どもたちの教育に、また命の問題に直接かかわったものがありますから、メンバーからも品川区議会の責任として、しっかり対処していきたいと考えています。今年１年、皆さんのご理解に心から感謝申し上げます。ありがとうございました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/702264?Template=document&Id=4882#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":45635,"voices":169}},{"id":"h28-20160516-5","meetingId":"h28-cm05","date":"2016年5月16日","dateIso":"2016-05-16","committee":"総務委員会","time":"午後１時００分～午後３時２７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","topics":[{"id":"topic-01","title":"平成２８年度区政モニターの委嘱","agenda":"平成２８年度区政モニターの委嘱","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"今ご説明のあった職業別のところ、その他の方が結局、全体の半数以上を占めていらっしゃるということで、もう少し詳しくその他の方の属性を教えていただければと思います。","respondent":"中元広報広聴課長","answer":"実は正直申し上げて、町会推薦の方に職業をお伺いしていないところがございまして、そこでその他のところが多くなってあります。ただ、実際に回答してくださっている方の中では、パートであるとか非常勤の方、あと株式会社の役員の方というのが、ここに入ってあります。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"町会推薦の方というのは、どのぐらいの人数なのですか。","respondent":"中元広報広聴課長","answer":"町会推薦が、実は前期からそのまま引き続きやりたいという方もいらっしゃいまして、委嘱数としては、町会推薦で更新された方が１０人、そして新規で町会推薦で入られた方が１４人となって、合わせて２４人です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"定員５０名公募ということですけれども、私の不勉強で、今の町会推薦２４名や、地区推薦１８名というのも先ほどあったでしょうか、その辺の、５０名公募の内訳になるのでしょうか、仕組みがよくわからなかったので、そこを一点お伺いしたいのと、もう一点、随分長くこの事業をやっておりますけれども、今後の発展、充実へ、今の課題や問題意識などはどういうところを思っていらっしゃるのか。","respondent":"中元広報広聴課長","answer":"内訳ですが、委嘱の中で更新された方というのがまず１８人いらっしゃいます。前期の２年間から引き続きやりたいという方は、町会推薦の方で１０人、それ以外で一般の公募で入ってこられた方が８人です。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"そういう意味でいろいろ課題をよく整理して、どうすれば参加がしやすい仕組みになっていくのか、また先ほどの方々は、情報そのものがなかなか届かない、要するに忙しいと区の取組みもなかなか目や耳に入ってこないということはあるでしょうから、参加のしやすい仕組みや届け方というのも、思い切った取組みも大事になっていくのかと思うのですけれど、いかがでしょうか。","respondent":"中元広報広聴課長","answer":"広聴の手段というのは、これに限らず様々なチャンネルを持ってありますので、こちらはじっくりと、講師の話を聞いて討議をしたりという、時間的に余裕がある世代の方であったり、そういう状況の方に出ていただいて、じっくりお勉強していただき。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"様々なところ、分野で、モニターをつくっていらっしゃいます。その中で、この区政モニターという形で区政に対する理解を深める、それから区政についての意見や要望を寄せていただくというときに、人口割としてこの数でいいのかという疑問を思うのですが、その辺はどのようにお考えなのでしょうか。","respondent":"中元広報広聴課長","answer":"こちら、５０人という人数ですが、やはり一堂に会しまして、またグループ分けをしながら討議をするというところで、集中してお話ができる、大体１０人ごとぐらいで５グループであるとか、やはりそういう枠の中で、この人数が目安かと考えているところです。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"わかるのですが、この数で区政全体に対する、理解はそれぞれ皆さんされていると思うのですが、区政に対する意見や要望を集めるに当たって、これだけの人口がいる中で、５０人の方々がいろいろ議論、討論はされるにしても、一般的に我々から見ると少な過ぎるのではないかと感じるのですが、その辺は、いや、もうこれでいいのだという考え方なのでしょうか。","respondent":"中元広報広聴課長","answer":"区政モニター集会で全てをやるというのは、やはり運営上も限界がありますので、それ以外の形でも日々、職員一人ひとりが区民の声を聞くというところは大事にして、またそれで施策につなげられるものはつなげていくということで、工夫をしてまいりたいと考えるところです。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"要望ですが、それぞれ、介護も含めて、保育、学校関係、町会等もそれぞれアンケートをとっているのですが、そのとき一緒に、区政モニターと同じような質問をそこに添えれば、ちょっとの時間で回答いただけるではないですか。そうすると、多くの人数のモニターがそこで集められるのかなと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"吉田委員","kind":"提案","question":"どこか調べればわかるのかもしれないですけれど、モニターの皆さんからいろいろなご意見とかご提案を寄せていただいて、それが具体的に、例えばこういう場所で活かされた事例があるということがあれば、教えていただきたいと思います。","respondent":"中元広報広聴課長","answer":"私が担当した昨年度は、特に活かされたとまではいかないで、やはり皆さん、まず知らなかった、区がこのようなことをやっているのだというところから始まりまして、皆さんで逆にこういうふうにしてほしいとか、区に対するご要望をいただいた場合には。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問","question":"そのことについてはわかりました。２０代男性の応募者がたった１人であるにもかかわらず、選から漏れているというのは何かもったいない気がするものですから、その辺、先ほど選び方でお話しいただいたのかもしれませんけれど、もう一回教えてください。","respondent":"中元広報広聴課長","answer":"後段のご質問の２０代男性の方ですけれども、実はフルタイムのお仕事をされる予定を３月のうちから情報をいただいておりまして、今回についてはやはり、どうしても集会が平日の午後、年に２回か３回はありますので、今回は差し控えさせていただきました。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問","question":"公募の手段というのは、まだおっしゃっていないですよね。どのような形で公募をされているかということが一つと、それから町会推薦というのは、特に枠が何かあるのかどうか。それと、区政モニターの要件の中で２０歳以上の方とあるのですけれども、選挙権も１８歳ということになりますし、これを例えば１８歳以上という形で見直しをする考えがあるかどうか。とりあえずそこまで教えてください。","respondent":"中元広報広聴課長","answer":"年代としては、やはり６０代の方が多くなっているところです。１８歳以上にするかどうかというところは、ちょっとまだ今年度のところは考えてございませんが、今後の課題として検討してまいりたいと思います。","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"５０人のうち、地域センター各２人、２６人の推薦が、基本的に６０歳以上となると、それはもうこのような年齢構成になってしまいますよね、そもそも。募集の段階から若い人たちに情報が届くようなことを、さらに考えていただきたいと思うのですが、それが１点です。それについても教えてください。ちょっと話が広がってしまいましたけれども、その３点についてお考えを伺いたいと思います。","respondent":"中元広報広聴課長","answer":"時間的制約がある方々のご意見の収集につきましては、今後も研究、検討を重ねていきたいと思っているところです。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"詳しくは知らないですが、例えば選挙の投票でも、土日ができなくて、平日もできなくて、投票するために会社を休みたいと、半休かもしれませんけれども、それはそれで会社が保障する仕組みがあったと私は思っているのですけれど、そのような形で、区のほうから何らかの、これに限らず審議会などいろいろなところで出てくると思うのですけれど、今どういう問題意識や検討がされているのか。","respondent":"中元広報広聴課長","answer":"ご本人の判断で、平日でも、夜間の開催もしておりますので、出られますということでお申し込みをされていると考えていますので、そういうことは一切考えてございません。今、委員からご提案のあった区が保障する仕組みという部分は、ちょっと今後の研究課題です。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的にその方が、そもそも要綱の要件であれだったというのは承知しました。フルタイムの方々が、区政モニターや審議会や何らかに参加をするとき、出席を保障するサポートというのでしょうか、本人が会社に言うのはすごくハードルが高いと思いますし、会社によってもどうなのか。今、企業も、自治体や地域へのいろいろなかかわりや貢献の中で、求められてくる姿、かかわりの仕方もあると思うのです。","respondent":"中元広報広聴課長","answer":"私の知識、経験の中ではそういう、こういうものに出席するに当たっての国の法律等ではないかと思うのです。は会社ごとの社内規定で、そういうものがあればというところではないかと思います。","id":"exchange-013"}]},{"id":"topic-02","title":"熊本地震に対する被災地支援","agenda":"熊本地震に対する被災地支援","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"今回の物資につきましては、本当に大変な中で迅速に送って、素晴らしい対応だったと考えていますし、関連した職員の皆様方のご苦労には敬意を表したいと思います。今回も熊本に行った後で大変だったというお話を伺っております。その点に関して、品川区としては今どのような形でお考えを持っていらっしゃるか、今後の話としてお伺いしたいと思います。","respondent":"久保田危機管理室長","answer":"それとあわせまして特別区といたしましては、今日の新聞等にも出ていましたけれども、２３区が一体となって支援を行っていこうという横の連携をしながら、窓口を統一して必要なものを迅速に送るといったやり方も、新聞に今日出ていたところがありますので、私どもとしましては。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"やはり大都市部の自治体ならではの連携や、職員派遣、役割というところも、これを機に何らかあらかじめの申し合わせや調整機関の役割を果たせると、とても有効なのかなという思いがあるのですけれども、その点だけお伺いしたいと思います。","respondent":"久保田危機管理室長","answer":"地震発生の直後から、２３区の中でいろいろな対応や問い合わせが横の連携、連絡等であった中で、幹事区になっております北区が窓口として一本化し、そして熊本市のほうといろいろ連絡をとって、それを２３区各区に回して、必要な物資、またこういうものが足りない。","id":"exchange-015"}]},{"id":"topic-03","title":"「品川区における障害を理由とする差別の解消の推進に関する職員対応要領」の策定","agenda":"「品川区における障害を理由とする差別の解消の推進に関する職員対応要領」の策定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それと、具体的には例えば障害者サービスが削減した、取り上げられた、こういった問題にどう対応していくのか、選挙での投票であったり、移動、就学、就労、生活で、行政の様々な説明会であったり、私も再開発や道路などいろいろな説明会に行きますけれども、説明する側はすごく丁寧なつもりでも、もともと用語が難しいですから、どういう工夫の余地があるのかなと私も考えたりするのですけれども。","respondent":"米田人事課長","answer":"その中では、説明の工夫の余地ですけれども、区のほうで説明をするときに、わかりにくい言葉はできるだけ避けてということでやっておりますけれども、今回の趣旨でいいますと、例えばある程度一般的な言葉でも理解するのが難しい障害者の方に向けては、図や絵等を示しながら。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"それについてどういうお考えなのか、伺いたいと思います。１点だけ具体的に、相談体制の整備ということで第５条ですけれども、障害者福祉課に相談窓口を置く、相談員は以下の者とするということですけれども、この相談窓口というのは、まず常設なのかという点と、なぜこの３人なのかという点、同和対策担当主査を置くわけですけれども、なぜそこを指名したのか、そこを伺いたいと思います。","respondent":"米田人事課長","answer":"それと職員対応要領ということに関しては、人事を所管するという者、それから同和対策担当主査は人権啓発課になりますので、人権を所管して普段から取組みを進めている者ということで、それぞれの係長を選任しているものです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"人権問題はさまざまありますけれども、実態からすると、暴力であったり、また保健師の専門性が生かされる分野もあるでしょうし、もちろん、自治体のいろいろなところからの相談の窓口になるでしょうから、幅広い業務に携わった方もいらっしゃるでしょうし、どうもこの人選というのが適切ではないというふうに思うのですけれど、これについてもう少し補足していただきたいと思います。","respondent":"米田人事課長","answer":"先ほどお話のありましたドメスティックバイオレンスに関しても所管している課ということで、そちらの課の庶務担当の係長、深く人権問題全般に対応している係長ということで、こちらの配置は適切なものであると考えています。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"それで、職員の方ですから、そういったものを使って庁舎の中を動いてみるとか、説明を自分が受ける側に回ってみるというような、そういったこと一つ一つを通して、また体験型の研修をぜひ進めていただきたいと思うのですが、今後の研修の中でそういったものをぜひ積極的に入れていくというお考えはあるのか。まだそこまで決まっていないというのであれば、ぜひやっていただきたいと考えています。","respondent":"米田人事課長","answer":"そちらのほうをより浸透させながら、事業を進めていく中においては、区民の方にも同じような形で職員に接していけるようにということで、この辺のところは全く別々にということでは考えてございませんので、そのような形でこれからも進めてまいります。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"体験型のものを含めて研修を進めていただけるということですが、この研修は悉皆になるのでしょうか。","respondent":"米田人事課長","answer":"それから体験型については、それこそ物理的な環境というか機会の提供ということでは、悉皆というのはなかなか難しいと思いますけれども、必要な人間、特に新規採用職員等の経験の浅い職員だったり、新たに職場に配属される職員、そういうような者を中心に。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問・要望","question":"最後にいたしますけれども、これまでもいろいろやってきたと思いますけれど、まだまだこの委員会でも以前報告されたように、いろいろな職員等の接遇の中であったということを考えますと、やはりより広範に、厚くやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問","question":"質問としては、今後のスケジュールの中に啓発パンフレット作成となっておりますが、啓発パンフレットというのは、どういう人に向けた啓発なのかという単純な質問が１つです。なので、いろいろ考えられているとは思いますけれども、その辺の意識改革というあたりを目指したような研修を考えていらっしゃるかどうか、その点について伺いたいと思います。","respondent":"米田人事課長","answer":"職員対応要領については、一応努力的義務ということで、必ずということではなかったのですけれども、新聞報道では全国のうち２１％の自治体しかまだ策定していないというようなことで、今後パーセンテージは上がってくるだろうと思ってあります。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ意識啓発に向けて、進んでいっていただきたいと思います。それで一つ、推薦といいますか、私、決算特別委員会の総括質疑の中で取り上げさせていただいたのですけれども、Disability Equality Training、ＤＥＴ研修という、障害を持った当事者の方が講師になって意識啓発を図るという研修が、今、特に大田区のほうで進んでおります。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"要領はできたということで、それはいいことだと思うのですけれども、幾つか字面というか、文言のところで教えていただきたいのですけれども。私はもちろんこれは絶対に必要だと考えているのですけれども、一応「望ましい」とあるのですけれども、まずこの２つについて、お考えを伺いたいと思います。","respondent":"米田人事課長","answer":"要領のほうで、意思の表明があった場合というところですけれども、これは当然準備段階で想定されることというのは、先ほど気づきというようなお話もありましたけれども、可能な範囲で準備をする、当日そういうお申し出のないような形での準備をしておく。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"先に２つ目の「望ましい」ということについて、今のご説明でわかりました。品川区の施設においては、委託の条件の中には基本的にというか必ず、要領と同じような扱いをするということを入れるということでいいのか、もう一回確認させていただきたいのと。その２点について伺います。","respondent":"米田人事課長","answer":"それから相談の窓口ですけれども、どこからが法の趣旨に反していて、どこからが反していないというふうに具体的に全てが線引きできるわけではなく、むしろそのようなことについて困っているという日常相談を、実際に所管課のほうでは受けているわけですけれども。","id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"質問","question":"先ほども研修の中で体験という話がありましたけれども、課長のご答弁の中で物理的になかなか難しい部分もあるということは一定の理解はできるのですが、私も障害者の方とお話をして、どういうふうにすれば理解ができるのでしょうかと伺った場合、それはやはり１日でも２日でもかけて、一緒に障害者の方と過ごすということが必要で、例を挙げれば、ＪＲの職員が障害者の方たちと一緒に１泊旅行をして。","respondent":"米田人事課長","answer":"これで足りなければ、より深い研修をということでやっていくものですけれど、まずのところは新規採用職員向けに、早い段階で障害者差別解消法の理念というものの理解が進むように、取組みを進めてまいりたいと考えています。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"参議院選挙がいつになるのかと、思うところではあるのですけれども、執行要領を選挙管理委員会が決めたということで、この範囲で伺いたいのですけれども、実は、なかなか投票所まで遠くて、足が痛くてなかなか投票できないという話を私の近所でよく聞くものですから、その点についてなのですけれども。何らかの理由でできないという話を私も聞いたことがあるのですけれども、なぜできないのか。","respondent":"工藤選挙管理委員会事務局長","answer":"ご質問を何点かいただきました。順番にお答えします。投票日当日です。私ども４３投票所を設けてございまして、基本的にはどの投票所も、私どもが歩いて１５分以内で投票できるところですが、いろいろと足の不自由な方もいらっしゃるということは、当然認識しています。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"具体的によく聞くのは、私の家の近所で、品川区と大田区の区境の西大井４丁目です。もっと言うと、商店街に近いところなのです。期日前投票は大井第三地域センターになるので、坂の上なのですね。みんなから、なぜすぐ横の伊藤小学校の体育館で投票ができないのかと、本当によく伺うのです。生活事情はそういうことなので、何かこうできないかということなのですけれども、一言いかがでしょうか。","respondent":"工藤選挙管理委員会事務局長","answer":"先ほど共通投票所というお話はしましたけれども、これはどこでもですけれども、今の隣の投票所にという話になりますと、今の法律上の考え方が、先ほど申し上げましたように投票区ごとに名簿を持つという形で、これは二重投票防止の基本の部分であります。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"その投票区そのものの変更というのができないのでしょうかという点なのです。はちょっと改めて状況をよく把握していただいて、そういう検討も進めていただきたいと思うのですけれど、この投票区の変更は区の判断でできるのかどうか、仕組みも含めそれだけ最後に伺いたいと思います。","respondent":"工藤選挙管理委員会事務局長","answer":"いずれにしても、そういった状況ですので、ケースによっていろいろと検討はしていきたいと考えています。","id":"exchange-029"},{"speaker":"大沢委員","kind":"質問・要望","question":"一つ教えていただきたいのですが、選挙デビューするわけですけれど、このデビューする子どもたちから、選挙運動が可能な期間以外に選挙運動をすることと、昨日あたり町中では名前の連呼、政策ということで言っている、全くこれと逆なことが現実行われているのですけれども、どのような検討の仕方をしたらいいのか、教えてください。","respondent":"工藤選挙管理委員会事務局長","answer":"そういった場合には、当然警察のほうにご相談していただくか、もしくは私どものほうに、いついつ、こういうことで、こういうような形で、こういった状況だったということを情報提供していただければ、私どものほうでできる範囲で対応はしたいと考えています。","id":"exchange-030"},{"speaker":"大沢委員","kind":"確認","question":"毎回のことですので、やはりこれから１８歳、初めての方は皆、期待している子どもたちも多いと思いますので、毎回のことですけれども、ここのところはしっかりと徹底して、いい、悪いは周知をしていったほうがいいと思いますので、確認のために聞かせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういった、非常に基本的で昔からのルールではあるのですけれども、どんな票が無効票になるのかということは、何かわかりやすい形でＰＲしていただくことによって、無効票を減らしていただきたいというのが一点。これもぜひＰＲしていただきたいなと。この３点、お願いなのですけれども、今後、当面の参議院議員選挙に向けてぜひやっていただきたいと思いますが、いかがでしょうか。","respondent":"工藤選挙管理委員会事務局長","answer":"委員からお話がありましたのは他事記載と言われているもので、プラスアルファで何か書いていますと有効にしにくいというお話ですが、いずれにしましても、効力判定というのはいろいろなケースがありますので、どういった形で周知というところはなかなか。","id":"exchange-032"},{"speaker":"あべ委員","kind":"意見","question":"それぞれ努力していただけることと思います。それと、最後の住民票のところ、ちょっと話がずれてしまうのですけれども、地方からの学生になぜ住民票を移さないのかと聞いたところ、非常に多くの方が、住民票を移してしまうと地元の成人式に呼ばれなくなるからという声を聞くのですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"私からは３点です。３点目は要望で、先ほどの共通投票所ですけれども、いろいろご意見があって私もこれはずっと毎回言っていて、東品川のイオンにつくってほしいというご意見が地域の方からたくさんあるのですが、確かにコストのことであるとか、タイミングがあるので、もしそういうタイミングがあれば前向きにご検討いただきたい、これは要望です。","respondent":"工藤選挙管理委員会事務局長","answer":"いろいろと表現等難しい部分ではありますけれど、なるべく易しくコンパクトに伝わるようにということで考えたところですので、ご理解のほどよろしくお願いします。","id":"exchange-034"},{"speaker":"あくつ副委員長","kind":"意見","question":"易しいとか難しいとかという問題ではなくて、それは重々、局長もわかっていただいていると思うのですけれど、議会が若い人たちの言うことを聞いていないというふうな、恐れがあるというようなことですので、そのところはご理解いただけるかと思いますが、わかりました。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"区民への周知というのは、どの段階で、今もうあるのか、全く把握していないのですけれども、その辺の考え方と、どうしていくのかということをご説明いただけますでしょうか。","respondent":"久保田危機管理室長","answer":"区民への周知についてですが、特にまだ、この内容が品川区に対してとか、どこどこにということで特定しているものではございませんので、まずは私どもの庁内の中で、きちんとそういったものがないかどうか、把握していきたいと考えているところです。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問","question":"参考までに、対象者はどのぐらいいらっしゃるのですか。","respondent":"黒田税務課長","answer":"普通徴収の把握につきましては、６月上旬を予定しておりまして、現在税確定作業中で、把握していないところですが、そんなに多くの方がいらっしゃるということではないと認識しています。","id":"exchange-037"},{"speaker":"あくつ副委員長","kind":"質問","question":"１つは行政視察で、北九州市に伺って、会派を越えてスーパー公務員という、本当に公務員の力によって自治体はこうも変わるのだというところで、各委員間で非常に議論が盛り上がったこと、そして第１回定例会で４８本の委員会付託になったうち１９本という、４０％をこの総務委員会で、２日間にわたってかなり汗をかいて議論したこと、私にとっての思い出です。本当に１年間ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/227390?Template=document&Id=2044#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":46066,"voices":95}},{"id":"h28-20160517-14","meetingId":"h28-cm05","date":"2016年5月17日","dateIso":"2016-05-17","committee":"行財政改革特別委員会","time":"午後１時００分～午後２時１３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/700324?Template=document&Id=6006#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":2720,"voices":12}},{"id":"h28-20160518-18","meetingId":"h28-cm05","date":"2016年5月18日","dateIso":"2016-05-18","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後３時２６分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/969591?Template=document&Id=6492#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":3256,"voices":10}},{"id":"h28-20160519-10","meetingId":"h28-cm05","date":"2016年5月19日","dateIso":"2016-05-19","committee":"議会運営委員会","time":"午後１時００分～午後１時１９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"その他","agenda":"その他","exchanges":[{"speaker":"たけうち副委員長","kind":"確認","question":"最後のところなのですけれども、常任委員会、特別委員会等は、今日、氏名確認されましたけれども、新しいのを事務局のほうで入れていただくのか、こちらで直したほうがいいのか。","respondent":"原区議会事務局長","answer":"新しいので各自訂正、追加なりをいただいて、ご提出をいただければと思います。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/457598?Template=document&Id=5180#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":6963,"voices":32}},{"id":"h28-20160525-10","meetingId":"h28-cm05","date":"2016年5月25日","dateIso":"2016-05-25","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時００分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","topics":[{"id":"topic-01","title":"議事日程(1)、追加議事日程および追加議事日程(2)(3)(4)","agenda":"議事日程(1)、追加議事日程および追加議事日程(2)(3)(4)","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"資料Ｎｏ.６の議員派遣の件の議場即決についてなのですけれども、この議員派遣の要請は、４月６日のこの要請書で議長宛てに要請されたということになると思うのですけれども、それで議運で１８日と２８日に、この場で質疑をしてきたわけですけれども、その両日とも議会事務局長からのいろいろ質疑に対して答弁をいただくという、そういう形で質疑されたのですけれども、私は、今回の議場即決ではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、改めてこの議員派遣の中身について、予算から視察の中身から、そういうふうなところを、あのとき、２８日のときにもちょっと私、申し上げたのですけれども、改めてここに正式な形で議運で理事者に来ていただいて、そこのところをきちんと答弁をしていただいて、そしてそこの中身がもうちょっと明確になるような形での質疑ができるように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"の６、その他","agenda":"の６、その他","exchanges":[{"speaker":"渡辺委員長","kind":"確認","question":"最後に私から。改選後の議会運営委員会が立ち上がり、大変な情報量を、委員会の事前の準備、調整、そしてその後の確認と、それぞれ委員の皆様、各会派で大変ご苦労されたかと思います。ただし、その大変多くの情報量、大変有効に活用されたり、今、実際に物事が動いている、そんな気がしますので、本当に実り多き１年だったと思います。以上で本日の予定は全て終了いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/457598?Template=document&Id=5182#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":11300,"voices":62}},{"id":"h28-20160606-6","meetingId":"h28-cm06","date":"2016年6月6日","dateIso":"2016-06-06","committee":"区民委員会","time":"午後１時００分～午後４時２０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"いろいろ多岐にわたる事業なので、まずは幾つか絞って伺いたいのですけれども、地域振興部の総括説明というのがありましたけれども、今年度の重点事業といいますか、特徴となる事業というのは何なのか、継続しているものも当然あるかと思いますけれども、今年度の重点事業や特徴的なものが何か、ご説明を受けたいと思います。","respondent":"堀越地域振興部長","answer":"協働推進経費ですが、これは主にＮＰＯ関係の方ですとか、任意団体の方が活動されている経費ですが、こちらも先ほど課長から説明がありましたけれども、区民活動助成制度の募集回数を年１回から年２回という形にいたしまして、やっていくものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"幾つかあわせて伺います。中小企業センターの１階の喫茶コーナーと言えばいいのでしょうか、長らく閉鎖されたままなのですけれども、この先どうなっていくのかということを伺いたいです。仕事づくりとか福祉分野との連携とか、新たな支援策というのを考える必要があると思うのですけれども、今後の検討の方向を、支援策の方向を伺いたいと思います。","respondent":"河内協働・国際担当課長、山崎商業・ものづくり課長","answer":"私からはふれあいサポート活動の、福祉サービスからの置きかえの件につきまして、ご説明します。ふれあいサポート活動ですが、最も重要な理念と申しますのが、住み慣れた地域で安心した生活を、です。近々、中小企業センターのすぐ近くにプチレーブのパンの関係で、連携しながらというあたりをメーンに今交渉しています。早ければこの夏前には、プチレーブと連携した喫茶コーナーの開店というようなことも含めて、今検討しています。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"委員長、運営について。最初、きょう委員長が事務事業概要ですから、というお話をいただきましたので、きょうこれで施策を全部、今、事業部でやってくれているのですから、全ての施策について聞こうと思ったら聞けるわけですよね、これは何ですか、それは何ですかと。聞こうと思ったら全部聞けますよ。この事業何ですか、この事業何ですかと。それはちょっと違うと思うのですけれど。改めてお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"では委員長の言う概要説明と概要についての質問って、何ですか。概要説明はいいです、それに対する質問というのは一体何ですか。個々の事業が一つ一つの事業でやっているわけですから、質問が個々の事業になるのは当然ではないですか。なので、委員長に伺いたいのは、事務事業概要に対する質問って、一体何ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"きょう説明を聞くだけの場なのですか。ただ、事業について質問してはいけないと仕切ったら、きょうは説明を聞くだけの日ですか。ヒアリングだったら聞き置くというのもあるかもしれないけれど、予算特別委員会も終えて、新しく委員会になって、今年こういう事業をやりますよの概要説明があって、事業について概要的に質問をするということが、委員会としては活性化していいのではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"先ほど委員長に伺ったのは、この委員会ででは委員長の言う質問は何なのですかということなのです。先ほどから個別の事業を聞いてはいけない、事業は個別に行われているのに、では何を質問して、という仕切りなのですか。だから委員長の言う個別の案件はだめで、個別の事業もだめで、逆にきょうは聞きおくだけなのですか。そこを聞いたのです。それが一つ。なので聞きたいのは、何を質問していいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"はじめ、私が部長に聞いたのは、これは私のスタンスですから、質問者のスタンスや問題意識で、自由闊達にやっていただける、それは私は何かを拘束するわけではないですけれど、私はいつもこの事務事業概要、初日ですよね、まず部としての重点事業、特徴は何かと。区としてはこれを重点的にやりたい、その問題意識を聞こうと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"それぞれの当選された委員が、私はこういう問題意識があるのだと、この事業についてはこういう問題意識があるのだと質問して、区としてはこう考えているのですと、１年間の方向性を、先ほどプチレーブが夏には始まると言ったのでよかったなと思いましたけれど、そういうやりとりがまさに、この事務事業概要全体の議論なのではないですか。私はそう思います。しかも十何年間か、私は大体そうやってきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"それぞれの事業について、私なりの意見と問題意識と、もちろん議会だから質問という形でそれをするという形で、という質疑を続けたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"置きかえではないという話がありましたけれども、私が聞いたのは実はもう一つあって、訪問ボランティアに変更した人はいるのかという点を伺って、それについての答弁がなかったので、そこを改めてご説明いただきたいと思います。どうぞよろしくお願い申し上げます。産業振興の就業支援事業、今年も取り組んでおりますけれども、今後の充実や強化の方向について、区の考えを伺いたいと思います。","respondent":"河内協働・国際担当課長、立木産業活性化担当課長、伊崎地域活動課長","answer":"先ほどご説明させていただきましたとおり、こちらのサービスの原点は、平成１６年度から始まった配食サービスです。それぞれ就業体系に関しましては、伴走型できちっと支援していくような形を今整えておりますので、そういった形で充実。今、ご説明しましたように、ここで定めておりますのは、区の責務として区がやるべきことは定めておりますが、区民の方。","id":"exchange-010"},{"speaker":"本多委員","kind":"質問・要望","question":"一つだけ、商業・ものづくり課の２２ページで、今年度から始める事業承継支援事業がありますけれども、社会的に課題があって、品川区も社会問題の同じ背景があって、この事業を立ち上げたと思うのですけれども、まだ立ち上げて２カ月ですから、そんなに時間もたっていないわけですけれども、こういう社会的現象、問題をもとに立ち上げた事業の、まだ２カ月ですけれども。","respondent":"山崎商業・ものづくり課長","answer":"今困っていなくても、１０年、２０年、３０年たったらどうですかということを働きかけて、準備をしてもらおうということも一つポイントとして思っておりますので、しっかり周知をして、頑張って取り組みたい事業の領域だと考えています。","id":"exchange-011"},{"speaker":"いながわ委員","kind":"質問","question":"町会・自治会会館の整備についてなのですけれど、３１ページの(2)町会・自治会会館耐震診断助成とか書いてあるのですけれど、基本的に建築課が所管していると思うのです、普通の一般住宅であれば。それが今回、平成２４年になったのですけれど、地域振興部として、何をするのですか。ずっと疑問に思っていたので教えていただければと思います。","respondent":"伊崎地域活動課長","answer":"耐震診断の経費は、木造であればこちらで出すわけですけれども、していただいた結果、改修が必要であれば、ここに載っています(1)の補助金の申請の該当になりますので、こちらに沿った形でいろいろご相談しながら。","id":"exchange-012","title":"町会・自治会支援"},{"speaker":"いながわ委員","kind":"質問","question":"それでしたら、最初は耐震診断で来たら、次は耐震補強設計に行くのですか。そうなってくると、要するに１００％補助しますと書いてあると、上限がないわけではないですか。それはちゃんと理解した上で、これはちょっと高いのではないかという指摘ができるぐらいの平均はとってもらいたいのですが、どうでしょうか。","respondent":"伊崎地域活動課長","answer":"１００％補助とありますが、限度額は設けておりまして、その限度額の中で１００％補助ということで、適正な限度額を設けてあります。きちっと町会・自治会の方にはご説明しております。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問・要望","question":"警視庁が防犯カメラを利用するというか、活用するわけですから、その辺をどういうふうに考えて、どういうふうにしていくのか。すごい客引きです。私も歩いたのですけれど、真っすぐ歩けない。条例をつくったのに全然効果がないのではないかという思いがあるのですけれども、残り１０カ月の任期の中でこの２点、私は進めていっていただきたいと思うのですけれども、大きな意味でいかがでしょうか。","respondent":"濱田生活安全担当課長","answer":"前回説明いたしましたが、警視庁は東京都のほうに予算請求しておりますので、私が当時、本部庁舎に勤務していた際に、防犯カメラをもっと東京都に設置してほしいということを要求しておりました。ですので、請求はしておりますが、東京都は、特に犯罪が、早急に改善しなければならない、今つけているのは新宿、渋谷、歌舞伎町、六本木、上野、錦糸町。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問","question":"２６ページの書店、コンビニエンスストア等における有害図書についてなのですけれど、去年も聞かせていただいたのですけれど、有害図書の陳列などを調査して、どう改善につなげているのかということをお伺いしたいのですけれど。","respondent":"伊崎地域活動課長","answer":"東京都の有害図書ですと、もうちょっと厳しい仕組みがありますけれども、品川区のほうではもっと幅広い意味で有害図書として規定して、お願いしていますので、それは改善の努力を店舗にお願いしています。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"せめて小学校の周りの、近いコンビニとかだと、何かあったときに逃げ込むような場所になっていたりもするので、そういうところを特に気をつけて、注意してもらいたいと思うのですけれど、これは要望としてお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"伊藤副委員長","kind":"確認","question":"簡単に確認だけ。２つ。平成２８年度の当初予算自体の、地域振興部の歳入の考え方を教えてください。それからもう一つ、新製品・新技術開発促進事業の中で、助成をされていますけれど、例えばこういう「ロッド・パイプ型エンジニアリングプラスチック用加熱式ベンダーの開発」など、私にはわからないけれど、これは誰が評価をして、対象とするかということを確認したいのですが。","respondent":"堀越地域振興部長、立木産業活性化担当課長","answer":"商業・ものづくり課に関しましては、国のほうの助成金、東京都の助成金等、いろいろ補助制度もあります。先ほどご質問があったプレミアム商品券等もございました。国の交付金等も活用していくというのが、全体的な考え方です。新製品・新技術開発促進事業の助成の審査にあたりましては、外部の学識経験の方ですとか、大学の先生、あと研究機関の技術者の方を依頼しまして、そちらの審査員の中で審査をしていただくという形になっております。","id":"exchange-017"},{"speaker":"伊藤副委員長","kind":"質問","question":"そういうご理解をしてほしいのですけれども、限られた時間の中で活発な質疑と、効率的な運営をするためにはどうしたらいいかということで理解していただければ、少しでもご理解いただけると思うのです。決して委員長は質問を制限したわけでもないし、発言を嫌がったわけでもない、だけれど限られた時間の中で効果的な委員会をしていきたいとの思いだけですから、そういうことでご理解いただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"大きく伺いますが、オリンピック・パラリンピック準備課長に伺いますけれども、きょうの説明の中で、ある意味後退しているのかなと私は思ったのですけれども、予算は５.２倍になって、でも３名なのです。前年度も課長を抜いて３名ですよね。予算は上がっているのに、人数は増えていないという意味において、これはいかがなものかと思うのですけれど、まず率直な課長の思いをお伺いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今年度につきましては、同じ体制ということで限られた人員の中で、当該課長といたしましては限られた人員の中で精一杯やっていくというふうに考えているところです。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"オリンピック・パラリンピック準備課は本当に３人だから小さい課で、これで本当にいいのかなという思いがいつもあったのですけれども、課長からその辺はどういうふうに、例えば人数をもうちょっと増やしてほしいとか、そういう思いはやはりあると思うのです。それで、課長からも言いづらいかもしれないですけれど、この辺、部長、これどう考えて、部としてのバランスというのは考えているのでしょうか。","respondent":"安藤文化スポーツ振興部長","answer":"事業と人数を考えていって、あくまでも最小の経費で最大の効果を生むように、努力をしていきたいと思っています。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"担当課長、今の部長の答弁を伺って、そうじゃないのになとか、そうだとか、いろいろあると思うのですけれど、最後にちょっとその辺、答えていただければと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした部分では、区全体で見たときにはやはり占める割合をきちっと区としても確保しているという部分もありますので、担当課としましてはそういった面も鑑みつつ、限られた中で精一杯努力してまいりたいと考えています。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問・要望","question":"観光の件ですけれど、今までアクションプランでずっとやってきて、１０年がたって、都市型観光と名前を変えてまた１０年ぐらいやっていくと思うのですけれど、アクションプランの半ばぐらいから、オリンピックが招致されて、人がいっぱい来るという部分で、ある意味目標といいますか、こうしていかなければいけないというふうに具体的に多分出てきて、いろいろやってきたと思うのですけれど。","respondent":"鈴木文化観光課長","answer":"そこで区としましては、ベースである都市型観光、区内のいろいろな観光資源を生かしつつ、品川の特性に応じた観光というのを促進する、振興するということでは、目標はぶれずにそこに向いておりますが、その途中に来る５年後のオリンピック、大きなピークといいますか。","id":"exchange-022"},{"speaker":"いながわ委員","kind":"質問・要望","question":"それも点でようやく集めて、鎌倉とかああいう大きな観光スポットの面になるみたいな、相当苦労、努力しないといけない、ぜひ想像力というのですか、こじつけというと言い方はおかしいですけれど、品川はこうなんだという、新たな観光を見出すということも大切だと思うので、ぜひ頑張っていただきたいと思います。それとも、それは掌握し切れていないのかどうかというのを、ちょっと聞かせていただきたいです。","respondent":"池田スポーツ推進課長","answer":"こちらのほうの部分では、スポーツ協会に加盟されている団体だけでなく、いろいろな方、サークルも入ってまいります、そのサークルが入ってきたことによりまして、スポレクの中でまた交流会とかいうものも開いていくような形になってまいりますので。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そういう人たちが個々で地域の人たちと、もちろん地域スポーツと全く違うところで、全く行政とは関係ないところで、スポーツをやって頑張っている人もいるので、そういう人たちにも多少光を当てつつ、スポーツ振興をしていっていただきたいなと。でもやはりお金を払っている人が優先になってしまうのかなというのが、僕の頭にあるので、そこを何とか、垣根を除いてうまくやっていただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"文化、観光、スポーツ、オリンピック・パラリンピックとそれぞれありますけれども、先ほどからオリンピックを契機に、５年後だったり、５年前だったり、都市型観光だったり、いろいろ大きい方向性は質疑の中で感じてはいるのですけれど、改めて文化スポーツ振興部の今年の重点的な考え方は、どのような方向性を持ってそれぞれの課を束ねているのか、そういう趣旨で伺いたいと思って。","respondent":"安藤文化スポーツ振興部長","answer":"最後に、オリンピック・パラリンピック準備課ですけれども、もう目の前にリオデジャネイロがあって、その先にもう４年後東京があるというところで、今回予算も大幅に増大していますけれども、機運醸成はじめ、東京オリンピックに向けて。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"「こんにちは」と言われてもそれが聞こえなかったりすると、ちょっと恥ずかしい思いもしたりして、なかなか聞きにくいというのは、社会参加やいろいろなことを体験する、享受するのにハードルになっているのだなと日々感じるだけに、磁気ループも周知徹底を、例えばポスターなのか、大きなイベントで非常口の案内とかはするけれども、そういうときに本施設にはこういうものがありますと。","respondent":"鈴木文化観光課長","answer":"１点目のメイプルセンターのテナントについてですが、実はメイプルセンターの入っている建物自体が、コアスターレの商業エリアの一角でございまして、４階、５階を文化振興事業団が借り受けて運営をやっておりますので、それ以外は管理組合のほうでのテナントになりますので。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"案内看板が、七福神めぐりのときになかなか、私は十分ではないなと思っていまして。やはりスポーツ一般についても伺いたいのですけれども、お金と時間のある人だけが享受できるって、そういう狭い考えではなくて、誰もが気軽にいつでも、どこでも、障害があっても楽しむことができるという、そこを目指していくことが大事だと思うのですけれど、そこについてもどうお考えなのか、あわせて伺いたいと思います。","respondent":"鈴木文化観光課長、池田スポーツ推進課長","answer":"区全体として、オリンピックも含めましたいろいろな施設とか、区内の案内表示、こちらについても検討が始まっておりますので、区としての統一感と、観光の案内としてのわかりやすさ、この辺をしっかりと考えながら。もう一つ、昨年はしながわ区民公園が工事で休場しておりましたけれども、今年はプールが新しくできますので、なおかつ子どもがとても遊べるような形になって、開放する予定になってありますので。","id":"exchange-027"},{"speaker":"こんの委員","kind":"質問・要望","question":"事務事業概要の表記の仕方をちょっと確認させていただきたいのですけれども。一方で、１４ページのほうの学校温水プール一般開放と、実績が載っているのですけれど、参加人数と延べ人数が書いてあるのですけれども、こちらは一般開放で２つの学校しか書いていないのですが、これは何か意味があるのですか。実績の載せ方というところでお聞きしたいのですけれど。","respondent":"池田スポーツ推進課長","answer":"警備業法改正がございまして、ここまでは水泳連盟にお願いしたのですけれども、そこができないということになりまして、平成２４年度で戸越台中学校の開放を中止しています。","id":"exchange-028"},{"speaker":"こんの委員","kind":"質問","question":"わかりました。豊葉の杜学園がもしそうだとしたら、１４ページのほうにも実績が載ってきてもいいのかなと思いました。これは事務事業概要なので、その年、前年度にどういう実績があって、今年度どういうふうにしたいかという事業を載せていくものだと思うので、延べ人数というよりはもう少し細かく、やはり実績等載せたらどうかなというのを感じたのですけれど、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"もう一つの実績についての内訳をもう少し細かくしたほうがです。それは検討しますので、よろしくお願いいたします。","id":"exchange-029"},{"speaker":"こんの委員","kind":"意見","question":"ぜひ、細かく載せるというのは、プール管理も委託をされている部分もあるでしょうし、そうしたものの動き、参加人数、その施設がどういうふうに使われているかというところもしっかり見る、私たちも見ていきたいと思いますので、ぜひご検討をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"伊藤副委員長","kind":"確認","question":"観光アクションプランの推進事業の中で、確認だけなのですけれど、(8)鉄道会社との連携事業で、東急電鉄と東京モノレールが出ているのですけれど、単純にＪＲやりんかい線、京急との関係はどうなのでしょうか。地下鉄も走っていると思うのですけれど、それはいかがですか。","respondent":"鈴木文化観光課長","answer":"今年度事業で具体的に事業の協力をお願いしたり、また今年度にないところに関しましても、先ほど申し上げました品川区の観光振興協議会、そちらのほうに委員としてご参加いただくご相談をしていますので、今後しっかりと連携して進めたいと考えております。","id":"exchange-031"},{"speaker":"伊藤副委員長","kind":"確認","question":"確認だけです。つまりＪＲ、りんかい線、京浜急行、地下鉄もありますよね、そういう鉄道事業者の方々と連携する会議をつくりますということで、よろしいのでしょうか。","respondent":"鈴木文化観光課長","answer":"はい、すみません、ご指摘のとおりです。さまざまな交通機関の事業者と連携をして進めていくという趣旨です。","id":"exchange-032"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この電力節減方針について、例年行っているわけですけれども、これはいつまで続けるのか、伺いたいと思うのです。もちろん電力の節減や、エコと環境対策、これはとても大事な事業だと思いますけれども、年々同じこの目的で動いていることについては、どういうご見解なのか、今後の見通しについて何かお考えがあれば、伺いたいと。所管はここでないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"いながわ委員","kind":"質問・要望","question":"全部で多分節減していって、総務委員会のときでも言いましたが、特に荏原文化センターが避暑シェルターになっていると思うのですけれど、旗があったのですけれど、その旗をどうか目立つところに出していただきたいと。中でひらひらしていても、通った人は全然わからないので、何度言ってもずっと中に、自動ドアと自動ドアの間にポンと置いてあるだけで、全然見えないのですよね。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（し）委員長","kind":"提案","question":"ないようですので、今後の委員会運営について、私のほうから提案があります。本年の区民委員会におきましても、当委員会に係る所管事務の中から、年間を通して協議していきたい課題、また常に意識しておくべき事項等について、委員の皆様よりご意見、ご要望を聴取し、そうした課題、事項を本年の区民委員会のテーマに掲げ、所管事務調査および行政視察を通して具体性を深めていきたいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/371005?Template=document&Id=2752#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":62181,"voices":138}},{"id":"h28-20160606-7","meetingId":"h28-cm06","date":"2016年6月6日","dateIso":"2016-06-06","committee":"厚生委員会","time":"午後１時００分～午後４時２６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","topics":[{"id":"topic-01","title":"幹部職員の紹介","agenda":"幹部職員の紹介","exchanges":[{"speaker":"安藤副委員長","kind":"意見","question":"副委員長を務めします、日本共産党品川区議団の安藤たい作です。どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２７年度に制度が変わったことで、区民にどんな影響になっているかということをお聞きしたいのですが、まず、その中で、１つは総合事業です。総合事業は、この概要の中でも、１２ページに、全国に先駆けて、平成２７年の４月から総合事業に移行したということで書かれてありますけれども、１年が経過して、総合事業で何がどう変わったのかということをお聞かせいただきたいと思います。","respondent":"松山高齢者地域支援課長、永尾高齢者福祉課長","answer":"事業者側から見たときに、いきいき活動支援プログラムというのを４３ページのところでご紹介しましたけれども、こちらは事業者の自主的な特性を活かした提案型の事業ということで、改めて事業者が自立支援を見直して、自分たちで。負担割合が２割になった人の人数ですけれども、本日、手元に数字を持っていませんが、国は、一応、大体２０％を見込みということで、この制度をつくられておりますけれども、品川区はそこまではいっていないです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一括でと言っても、これだけ説明の中身が膨大で、２時間以上にわたっての説明でした。でも、わかっている部分もあると思いますので、答えていただけるところは答えていただきたいと思います。それで、常日ごろ、疑問に感じていること、ここを明らかにしたいことというのがありますので、そこは、この事務事業概要のところで聞かせていただきたいと思いますので、ぜひ、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、機能強化というところで検討委員会もつくられて、議会の機能を強化していこうというところでやっているわけですから、しかも、２時間数十分かけて、理事者の方がこれだけ丁寧に説明していただいたわけですから、それに関して何もありませんというのは、私は、逆に理事者に失礼だと思いますし、この機会に自分自身も理解を深めたいというところで、ぜひ、質問もしていきたいと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"渡辺委員","kind":"確認","question":"運営の確認だと思って、質問させてもらいます。今日、冒頭に委員長から進行の確認がありまして、概要説明があり、そして、概要全体に対して簡潔な質疑ということは、多分、共通認識でいると思いました。今日はそういう場ではないという認識でいますので、それを各委員の皆様も共通認識で、質疑も簡潔に、総論に準ずることでされたらいいと思いますので、その確認をと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが１点です。もう一つ、９３ページの民生委員なのですけれども、民生委員が３２５人という定員になっているということなのですが、なり手がいなくて困っているということも民生委員の方から伺っているのですけれども、現在の数は、３２５人の定員に対して何人かというのが、ここの中に見当たらなかったので、教えていただきたいと思います。それとも、途中で切ったほうがいいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に、生活福祉関係の問題です。生活保護の人員を見ると、ケースワーカーの数は、第１から第５係までで、４７人ということで考えていいのでしょうか。平成２５年は１６５人だったのが、今は１４９人で、パーセンテージも下がっているという状況です。制度の周知については、子どもの貧困ですとか、ひとり親家庭のところについて、どうされているのかということについても、お聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"生活保護を受けている方は、様々な支援が求められる方も多くて、いろいろ対応していただいていると思うのですけれども、そういう点では、１２０人から１３０人となると、本当に大変な状況で、そのために厚生労働省も８０人という目安を出しているのだと思いますので、ぜひ、これは増員をしていただきたいということで、要望をさせていただいて終わります。","respondent":"渡部委員長","answer":"ほかによろしいですね。副委員長、委員会運営上、事務事業概要の説明に対して簡潔によろしくお願いします。","id":"exchange-008"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"伺いたいのは、外出と高齢者の健康づくり、シルバーパス事業と健康づくりとの関係を区はどう考えていらっしゃるのかというのと、何らかの形で負担を下げる必要があると思うのですけれども、いかがでしょうかというのが１つ目です。２つ目は、保健師についてです。わかれば、各保健センターでの保健師の数を教えていただきたい。","respondent":"松山高齢者地域支援課長、渡部委員長、太田品川保健センター所長、永尾高齢者福祉課長","answer":"シルバーパスと介護予防との関係を区はどのように考えているのかについてのご質問と、この金額はどうかという２点ございました。保健師の数は、事務事業概要に出ていますので、そこではない部分で何かあれば、お答えください。数が多いか、少ないかにつきましては、これ以外にも高齢福祉等に保健師が要るということも考えると、今のところは、数を増やすということよりも。ほかになければ、事務事業概要につきましては以上で終了をいたします。","id":"exchange-009"}]},{"id":"topic-03","title":"の３、報告事業 認知症に関するアンケートの実施","agenda":"の３、報告事業 認知症に関するアンケートの実施","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"内容は見たのですけれども、趣旨はわかったのですが、結果が来年の３月ということなので、結構、回答期間から期間があるような感じます。なるべくなら、もうちょっと早く。それを活かすのは、もうちょっと早くできないのかというのと、公表ももっと早くできないかというところなのですけれども、その辺のスケジュール的なものとあわせて考え方を教えてください。","respondent":"永尾高齢者福祉課長","answer":"区のホームページ等での公表となりますのは、最終的な結果が出たときの、平成２９年３月を予定しておりますけれども、ケアパスの検討につきましては、現在も行っているところで、１２月に完成を目指しておりますので、そこにできるだけ反映できるようにしようと、今。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問・要望","question":"わかりました。計画が早くできて、次のステージに進めるのはやはり大事だと思いますので、なるべく早くしていただきたいのと、あと、この中から、どういったところを参考にしていくようなものがあるのかというのが幾つかわかれば、教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それがわかれば、では、関係機関はどういう対応をしていくと、その敷居が低くなるのかということも重要だと考えています。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そこら辺のところで、何で３月になるのか理解ができないのと、それから、そういうふうにまとまったところで、この厚生委員会に、ケアパスについても、こういうふうな形でみたいなところでの報告というのは、いつぐらいにいただけるのかということについてもお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"正式な確定の公表というのは平成２９年３月を予定しているのですけれども、実際、そこまで待っていたら、ケアパスがなかなかでき上がりませんので、中間報告というのは考えているところです。","id":"exchange-012"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"ケアパスなのですけれども、この時点で、品川区としても目的があってアンケートをとると思いますので、品川区としてのケアパスというものの特徴、どこを重視していくのかという考え方があれば、改めてお聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"ケアパスをつくる理由としては、まずご本人、ご家族の方が、これからどういうふうに自分たちがなっていくのか、それに従って、どういうサービスを受けるのが適切なのかということをわかっていただくというのも１つはあるのですけれども、もう一つとしては、介護の事業者。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/349721?Template=document&Id=3446#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":60966,"voices":97}},{"id":"h28-20160606-8","meetingId":"h28-cm06","date":"2016年6月6日","dateIso":"2016-06-06","committee":"建設委員会","time":"午後１時００分～午後２時３４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"西本委員","kind":"確認","question":"１点だけ確認をしたいと思いますが、両部とも他課との連携事業一覧というので示していただきました。","respondent":"松代防災まちづくり部長","answer":"そのほかにもいろいろと連携をする事業はありますけれども、この連携一覧というのはもう随分経ちますが、議会から横串をしっかりと、それぞれの縦割りでやるのではなくて、横串を刺してしっかりと無駄なく効率よく我々の目的とする事業を推進する。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"そういった場合に、財政課のところでの調整役というのは、どちらかというとやはりこの事業のほうを、表現が難しいのですが、力関係が出てくると、財政はもちろんお金がないと何もできないのはわかっているのですが、ただ、主導権としてはやはりこの事業の中で大切だということを踏まえて、経理のほうと調整を図っていただけるような形になっているのかどうかというところについて、例えば何でもかんでも入札。","respondent":"松代防災まちづくり部長","answer":"そういう中で、何をすべきか、何が課題かというところで、全庁的な中での課の役割が出てきます。そういう中で、まず課長級がしっかりそれを捉え、具体的な部分は係長級におろし、組織としてそれを検討し、また積み上げていくといったことで進めているものです。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"事業名ではあるのですけれども、概要を説明するところで両部とも住宅の耐震化というのがちょっと見当たらなくて、この間、熊本の地震などでもやはり多くの家屋が倒壊したというところでは、住宅の耐震化というのがこういった１枚にまとまった部分に書いてあるのがいいのではないかなと思うのですけれども、ここにその文字がない理由をちょっと伺いたいと思います。","respondent":"松代防災まちづくり部長","answer":"そういった形で考えておるところでございまして、記載の中にそういったものがちょっとないということであれば、その辺も今後少しわかりやすいもので整理するということも必要かと思いますので、これは持ち帰らせていただければと考えています。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、同じ防災まちづくり部の概要のところで、河川と下水道のところで、下のほうに時間５０ミリを超えるような局地的集中豪雨の際のということで、総合的な治水対策というふうに書かれていて、本当にこれ、進んでいるなと私も感じているのですが、この間ちょっとテレビで１時間に５０ミリを超える豪雨でいろいろな地域の想定をやっていまして、立会川があふれますという報道というのでしょうか。","respondent":"和田河川下水道課長","answer":"ですから、現時点では、５０ミリを超える雨が降ると立会川に一部の雨水が出て、それが大きな雨だとあふれることも考えられますけれども、今下水道局がやっている工事が完了すれば、そういうリスクは軽減されるということになりますので、ご安心いただけるかと思います。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"確認","question":"それと、ちょっと確認が続いてしまうのですけれども、感震ブレーカーのところで、平成２８年度は分電盤タイプで進めますと書いていたのですけれども、そうするとまた年度が進んでいくに当たっては分電盤ではない簡易型のほうなどの助成も始まっていくという見方でいいのかを伺いたいと思います。そこをちょっと伺いたいと思います。","respondent":"古巻防災課長、中村都市計画課長","answer":"今後につきましては、今年度の動向を見極めた上で、どういったタイプ、ほかのタイプについて助成を進めていくのか、そういったことについては今後ちょっと研究を進めてまいりまして。これは、この都市計画道路として必要な面積というものがあらかじめ計算されておりますので、その面積比です。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"意見","question":"これ以上は踏み込まないようにしますけれども、放射２号線の用地取得率１％というのが、ずっとこの程度で進んでいる感じなのですが、この用地取得率が進んでいない原因というのは、区としてはどう考えているのか、１つだけちょっとうかがいたいと思います。","respondent":"中村都市計画課長","answer":"この数字は東京都に確認したありのままの数字ということで、ただ、進んでいない原因というのはいろいろ個々に事情がそれぞれの路線でありますけれども、この放射２号線につきましては、今この沿道の皆様方に対して交渉中ということで、これは今１％ですけれども。","id":"exchange-006"},{"speaker":"塚本委員","kind":"質問・要望","question":"ちょっと１つ確認ですけれども、品川区のまちづくり行政の概要のところ、ちょっと石田委員からもご質問のあったところで、河川と下水道のところで「近年区内では、時間５０ミリを超えるような局地的集中合意により、浸水被害が頻発」とあるのですが、本当に１０分間に５０ミリを超えるような雨が降ったようなことは何か私も記憶にあるのですけれども。","respondent":"和田河川下水道課長","answer":"下水道は１時間に５０ミリの強度の雨水が排水できる用意ができていますけれども、５０ミリを超えるものは当然あふれてしまうわけで、そうしますと時間５０ミリを１０分間降雨に直した数字、今ちょっと計算できないですけれども。","id":"exchange-007"},{"speaker":"塚本委員","kind":"確認","question":"同じようなことなのですけれども、新しくまちづくり立体化担当というのができたわけですが、こういうものをあえて今年設置をした理由というか狙いというかを確認したいのと、あと説明の中で、天王洲ともう一つリニア新幹線のところも担当の中に入っているということで、こちらと立体化と何かぴんとつながらないところが、イメージできないところがあるのですけれども。","respondent":"今井住宅課長、東野まちづくり立体化担当課長","answer":"今、ご質問のとおり、こちら建築紛争の予防と調整につきましては、中高層建築物ですので、第一種低層住居専用地域とそれとで違いますけれども、一定の高さ以上の建物に関しましては、私どもで対応しているという形になります。同じように戸越公園につきましても、地元のほうでいろいろこれまでも要望活動を続けてきました鉄道の立体化、こちらにつきまして本年３月、東京都議会のほうで調査・検討に踏み切ったというようなことになりましたので。","id":"exchange-008"},{"speaker":"塚本委員","kind":"確認","question":"今の立体化のところでいくと、そうすると天王洲とかに何か立体化があってどうこうしようという話よりも、北品川とかが立体化していく中で、そことの関連性というか、中で一緒に考えていくべきところがあるのではないかと、こういう理解でよろしいのでしょうか。そこだけ最後、確認します。","respondent":"藤田都市環境部長","answer":"リニアもそういうような形でエリアどりの中に入ってきているということで、まちづくり立体化担当のほうで担当するということで、これから進めてまいりたいと考えています。","id":"exchange-009"}]},{"id":"topic-02","title":"平成２８年度品川区電力節減方針","agenda":"平成２８年度品川区電力節減方針","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今年の節電ということなのですけれども、２．のところの(1)から(4)の中で、いろいろな状況に合わせて対応していきましょうという話だったと思うのですね。ただ、結果的にやはりどうしても節電が難しかったということも出てくる可能性もあると思うのですね、夏の、今回どういう暑さが出てくるかわからないので。そこら辺の調整はどこがどういう責任を持って進めていこうとしているのか教えてください。","respondent":"三ツ橋環境課長","answer":"節電がなかなかできない施設も、やはり避暑シェルターなどの場合もありますので、そのあたりは臨機応変といいますか、必要最小限、業務に支障がない程度に節減していきましょうというふうに環境課が取りまとめてあります。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"調査というのは、これは去年度、例えば７月だったら去年の７月のトータルの使った電力に対してで、まだ７月に入っていないですよね。そうすると、この使い方によって去年と同じような使い方でやっていくのかとかという形での調査という意味なのですかね。使ってしまってから調査してもそれは結果でしかないので、その調査というのはどういう意味の調査なのかと思うのですが。","respondent":"三ツ橋環境課長、藤田都市環境部長","answer":"昨年度の７月、８月、９月に関しましては、各事業所に対してパーセンテージをとっておりまして、例えば庁舎全体が何％削減しているのか、違う施設についてもそれぞれ大規模な施設や小規模な施設で。ちょっと補足をしますけれども、ご案内のとおりこの夏場の電力節減については、平成２３年の東日本大震災のときに電力について切迫しているということで、当初はこの１５％を上回るような形での電力節減に取り組んでまいりました。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"経験値で１５％行くだろうということなのですが、非常に暑いところがあるのですね。そこで可能な限り対応していく。今、本当に皆さん我慢して、職員の方も区民の皆さんも我慢している。それは大切なことではあるのですが、ただ、そこでのやりくりをもう少し工夫できないのかなと、今までやっていたからいいでしょうということにはならないのではないかなと思うのですが、その点の分析とかはいかがでしょうか。","respondent":"三ツ橋環境課長","answer":"今回、今年に限らず毎回各施設や各課に調査はかけておりまして、実際に暑いというご要望というかご意見等々もございまして、こちらにも掲載しておりますように、２の(2)ですね、総合庁舎、高齢者施設、小・中学校など区民生活に大きな影響を及ぼすところにつきましては。","id":"exchange-012"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"確認","question":"確認です。見舞金と義援金と書いてありますが、この見舞金と義援金の違いとは何ですかというのと、どういう使い方になるのでしょうかということと、それからもう一つは、今後の対応の中で、要請があったらということなのですが、この要請とかというのは、例えば直接品川区になるのか、それとも２３区の中での要請でそれぞれの区が対応するという形になるのか、その辺の体制はどうなっているのでしょうか。","respondent":"古巻防災課長","answer":"それから今後の対応ですけれども、派遣の要請については、品川区に直接というよりは、例えば国を通しての派遣の要請でありましたり、東京都を通しての派遣の要請であるということで、そちらの要請が主になると考えております。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"そうすると、見舞金というのは、区のほうから出すお金は見舞金というような呼び方をして、広く区民の皆様からいただくものを義援金という形の名前を使って、行くところは、使い方は自治体等々に任せることなので、そこまで、使途についてはこちらから何も言うことではありませんよということでよろしいのでしょうか。なければ仕方ないと思うのですけれども、いかがでしょうか。","respondent":"古巻防災課長","answer":"今後の派遣の要請ですけれども、これにつきましては、現地の状況等に関しましては現地自治体の判断、それから派遣要請の必要度ですね。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/232335?Template=document&Id=4170#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":30601,"voices":111}},{"id":"h28-20160606-9","meetingId":"h28-cm06","date":"2016年6月6日","dateIso":"2016-06-06","committee":"文教委員会","time":"午後１時００分～午後４時５３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"今日はあまり中身に踏み込まないということで、事務分掌について確認をさせていただきたいのですけれども、７ページの保育課のところで、開設・指導、そこで私立保育所云々の運営にかかわる指導および検査に関することとありますが、ここでやるのが私立だけとなると、公立については、どこかに書いてある、見落としているだけでしょうか。","respondent":"竹田保育課長、高山子ども育成課長","answer":"公立の指導・検査というご質問ですが、開設・指導係で、公私立を含めまして指導・検査を担っているところです。私からは、子ども育成課で所管します在宅子育て支援事業ということでご説明しますと、地域の子育て支援ということで、基本的には児童センターを活用して。保育課の在宅支援ですが、保育園、幼稚園の施設を利用するもの、あるいは、それに類するような施設を利用するものを中心に保育課で所管しているものです。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問・要望","question":"１つ目の質問のほうは、この７ページでの分掌事務の中では、開設・指導係は、私立保育所、私立認定こども園の指導および検査に関することと書いてありますが、ここに公立も含まれるということなのでしょうか。その他の保育施設の中に公立保育所は入っているのか、そういう読み方でいいのか教えてください。前半部分の確認をもう１回お願いします。","respondent":"竹田保育課長","answer":"保育園、幼稚園等の指導・検査につきましては、一定の技術といいますか、ノウハウが必要ですので、対象施設にかかわらず、開設・指導係で一括して指導・検査しているものです。","id":"exchange-002"},{"speaker":"あべ委員","kind":"確認","question":"確認できてよかったのですけれども、そうすると、なぜこういう書き方になるのかということだけがちょっと気持ちとして残る。ここであえて私立保育所、私立、私立と書かなくても、今のご回答だったらいいのかと思いますけれども、何かねらいというか背景はあるのでしょうか。","respondent":"竹田保育課長","answer":"実質面としましては、やはりどうしても私立の施設、特に開設間もない施設等が重点的に指導・検査の対象になっていくというところもありますので、よりわかりやすく列記をしまして、その他の施設部分につきましては、その他保育施設ということで一括して表現しています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"子育て交流支援事業のところで、２３ページ以降ですが、大崎にこにこるーむと、荏原すきっぷひろば、交流サロンで行われておりますけれども、大崎のほうは順調にといいますか、今、家族化が進んで、子育ての保育化が進んでくる等で相談件数が年々増えているのですけれども、荏原のほうで利用者数は増えているけれども、相談件数が一定落ち着いてきているというところで、今、区の見解として。","respondent":"高山子ども育成課長","answer":"お尋ねの相談件数の推移につきましては、確かに地区で単純に比較しますと、増えている、それから平行線といいますか、件数的に伸び悩んでいるというような評価もできるのですが、事業の展開の中で結果として集まった件数がこのような増加件数だということで、これ自体が特に問題。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"奨学金貸付事業のところなのですけれども、推移を見ますと、だんだん増えていっているというところで、６５ページのところの、やはり学校に上げるに当たって、親の経済状況が影響してくることは、なるべくないようにしていったほうがいいと思っておりまして、この貸付金も、ぜひこの奨学金、給付型をつくっていただきたいと、再三、我が会派としては求めておりますが。","respondent":"廣田子ども家庭支援課長","answer":"今後のことにつきましては、奨学金の制度だけではなくて、経済的な面で厳しい状況にある家庭に対しての支援についての検討を横断的にこれから行っていこうと思っておりまして、その中で、奨学金単体ではなくて、区の事業についての見直しであるとか。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ給付型奨学金、学びたい人が学べるようにしていっていただきたいと思います。次に、９１ページの保育園入園申込者の2)の表になりますけれども、今年度、新規申込者が３,２８１人というところで、入園できたのが２,３１０人。横を見ますと、待機児数が１７８人と、これ、単純計算すると合わないのですけれども、この数字はどういう計算で出しているのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"申込者数と待機児数の差ということで、不承諾者という数になるかと思うのですが、計算すると９７１ということになります。不承諾の中から国の待機児童調査において、待機児童数から除外するとされている要件に沿って差し引いております。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、特定の園、１園だけという方、数字から差し引いて１７８人ということになっているということですが、その特定の１つの園しか希望していない人を除外するというのは、国の指針で示されている、改めて確認なのですけれども、それをなぜ除外していいのかということ、国から理由説明があれば、あるいは、区の考えもお聞きしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"２点目の隠れ待機児童というのは、多分この不承諾の数と捉えておりますけれども、今のように転園を希望されている方も、例えば隠れ待機児としてカウントするということであれば、その数は不承諾の待機児童数との差が７９３人ということでご報告をしています。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"１つの園しか希望していない方が私的理由ということで待機児童数から除外されるということですけれども、その考え方はどうなのでしょうか。実際、通いたいけれども、どういった事情があるかはちょっとわかりませんけれども、やはり実際入りたくて申請をしているわけですから、待機児童数から抜くということは、国の指針でやっているということですけれども、やめるべきだと思います。","respondent":"大澤待機児童対策担当課長、齋藤子ども未来部長","answer":"待機児童ですが、子ども・子育て支援事業計画に基づきまして、計画的に保育園を開設していきましても、計画上、平成２９年度中には解消できる計画にはなってございません。平成３０年度には計画どおり解消したいと考えています。１点目の１園しか応募しないですけれども、厚生労働省に呼ばれまして議論がありました。それは他区の自治体の区長がおっしゃっていたのですけれども、ハローワークで育児給付金をもらうためには、不承諾通知書が必要だと。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"今、ハローワークで受けるために、認可園を落ちるために申請しているという人もいるというお話ですが、品川区としては、特定の園を希望されている方に対して、そういった調査とかはしているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（博）委員","kind":"確認","question":"１つは、２６ページのすくすく赤ちゃん訪問事業と親育ち支援事業なのですが、この事業と今年から鳴り物入りで始まったしながわネウボラネットワークの関係と、しながわネウボラネットワークというのは、鳴り物入りで始まったわりには認知度が非常に低いと、実際、診療しているとひしひし感じるのですけれども、その辺の知名度を上げることに関しては、どのようにお考えなのでしょうか。それがまず１つ。","respondent":"高山子ども育成課長、廣田子ども家庭支援課長","answer":"幼児２人乗りの自転車につきましては、これは確かに利用としましてはもうほぼ事業の目的は終盤を迎えておりまして、現在のところ、２台、お貸ししているのですが、ちょうどお貸ししているお二人の方が、使用の期限は終わるということで。障害手当につきましては、もう少し細かい基準があるのですが、申しわけございません、今日は手元に持ってきてございませんで、経過については後日回答させていただこうかと思います。申しわけございません。","id":"exchange-010"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今の子ども育成課長の答弁に引き続いて質問なのですけれども、要するに、「ネウボラ」という名前が浸透しないのは、ネウボラとは何だかわからないのではないかと思うのです。今の課長のご説明を聞いていても、やはりよくわからないです。お答えをお願いしたいのですけれども。","respondent":"高山子ども育成課長","answer":"妊産婦ネウボラ相談員と、子育てネウボラ相談員といった相談体制の確立、育児家事支援事業、あと産後ケア、それからショートステイだとか、生活支援型の滞在支援事業であるとか、あるいは、子育てアプリを使用しました子育てに関する有益な情報の発信といった。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どの課もそうなのですけれども、どういう状況で仕事が行われているのか。全体的なところをお聞かせいただきたいのが１つです。そういった面で、保育課のところで、仕事量に合わせて職員の配置がされているのかどうか、最近、結構、病休をとって具合を悪くしている人が増えているという話もちらほら伺っているので、その辺の仕事量にふさわしく職員の配置がされているのかどうか、体制について教えてください。","respondent":"竹田保育課長","answer":"正規、非正規の正確な細かい数字は今は手元にございませんので、お答えできかねます。それから、仕事量については、保育課、申し込み数等の増に伴いまして、一定の職員増をしています。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"提案","question":"８５ページに新しい仕事の分野ということで、区立の保育園の建て替えの大規模改修のところと、民営化の項目が入って新しい課長のお仕事が明確になってきているわけなのですけれども、１つは、民営化の新しい方針を出したところは、新しく改修して民営化という道筋が提案されていますけれども、今まで４０数年たっていますけれども、大規模改修はあったけれども、大もとのところの建て替えとかはなかった中で。","respondent":"廣田子ども家庭支援課長、高山子ども育成課長、佐藤保育施設調整担当課長","answer":"子どもの貧困といいますか、経済状況の厳しい家庭に対する支援につきましては、子ども家庭支援課が事務局になりまして、今後、検討するところで、現在。私からは、４１ページのすまいるスクールの利用料につきましてご説明します。民営化と建て替えの関係ですが、基本的な方針は、昨年度、２月の文教委員会でご説明したとおりなのですが、詳細については。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"毎年この時期に伺っているのでぜひ教えていただきたいのですが、９１ページの待機児数の１７８名のところの保護者の方というか、主にお母さんですけれども、親の状況の内訳、あと、この１７８人の年齢別の内訳を教えてください。","respondent":"高山子ども育成課長、大澤待機児童対策担当課長","answer":"月のうち教室に関しては何回も開催されていまして、お便りなどを拝見する限りは、有料のもののほうがむしろ少ないということで、また、有料のものだから参加率が高いということでもないので、そういった意味での阻害であるとか。３歳児の枠についてですが、地域型保育事業や認証保育所の卒園後の受け皿の３歳児の区分につきましては、現在、検討を始めておりまして、具体的な内容につきましては、今後、文教委員会でご報告申し上げたいと思います。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"自治体の状況によって違いは当然あると思うのですが、１点、品川独自と言われているところで、カウントの仕方で、以前、４月の待機児の状況を出すに当たって、５月の申し込みをしている人の中でカウントすると聞いたことがあって、厚生労働省の中ではそういうものは推奨していないという発言も聞いているのですが、この１７８人という人数は、５月の申し込みをした人のことなのか。","respondent":"大澤待機児童対策担当課長","answer":"４月１０日の時点で、その先の入園の申し込みをされないということは、希望がないというふうに捉えることが合理的な判断だというふうに考えております。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは、１７８人の保護者の方の状況を、去年は自営とか内定とかも区別して数字を出していただいたので、毎年違うカウントの仕方をすると、比較できなくなってしまうので、できたら同じ状況で数字は追いかけていただきたいと思います。これは希望です。そういった意味で、一体化していると正確な比較にはならないのではないかと思うのですが、その辺はどうなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"委員長、今のところだけ。ということは、求めれば、その数字は出るということですね。でも、本来から言って、統計からずっといくと、認可保育園の統計をとっていて、途中から地域型も含めての数字に変わってきているのですが、厚生労働省に届けるのが別々だったら、求めればきちんと出るという認識でいいのかどうか、最後に。","respondent":"大澤待機児童対策担当課長","answer":"事務事業の中でも、認可保育園と小規模保育園と、７２ページと８６ページで入園者数をお示ししていますので、これは出ます。","id":"exchange-017"},{"speaker":"新妻委員","kind":"質問・要望","question":"１点だけ確認します。８５ページに、セカンドチャレンジ保育士支援事業があります。保育園の拡大とともに保育士の確保が非常に大きな課題かと思うのですが、品川区の中での保育士の確保において、この支援事業だけが保育士の確保の事業なのか確認をさせていただきたいと思います。","respondent":"竹田保育課長","answer":"保育士確保については、さまざまな方策をとっておりまして、セカンドチャレンジ保育士支援事業も１つです。それ以外にも保育士の資格を取る試験の助成や、あるいは、通信講座を受ける者の助成等、さまざまな方法で支援しています。","id":"exchange-018"},{"speaker":"高橋（し）委員","kind":"質問","question":"保育園の、幼稚園もそうですが、区立の幼稚園、保育園の園長のお仕事は、大変煩雑です。そのような中で、学校だと何らかの事情があって校長先生や管理職の方が体調を崩したりした場合は、かわりの方がすぐやるのですけれども、現状、区立の幼稚園、保育園で、園長先生などが何らかの事情で不在で、どなたかがかわりをやっているということはないでしょうか。園長先生の仕事は大変なので。","respondent":"竹田保育課長、中島教育長、あくつ委員長、本城教育次長、品川庶務課長、篠田学校計画担当課長、有馬学務課長、熊谷指導課長、村尾教育総合支援センター長、木村品川図書館長","answer":"保育園においては、かわりにやっているということはございません。通常、２３区の公立幼稚園の園長の任用につきましては、それぞれの区の需要を聞き取って、一括してそのように充てる形になっておりますけれども。ほかになければ、子ども未来部の事務事業概要につきましては、これで終了いたします。内容としては、そのすぐ下のところにありますように、義務教育９年間の教育体制の構築、品川コミュニティ・スクールの実施、そして。そのほかにつきましては、学校計画担当課長よりご説明します。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"１６ページの学校の施設整備なのですけれども、今年度、戸越台中学校が学校改修の基本設計に着工するということで、どういった改修をするのでしょうか。","respondent":"品川庶務課長、有馬学務課長","answer":"平成７年に建築しまして、大分年数もたっております。いろいろな機器等、排水管、給水管等も大分老朽化しているということで、現在、基本設計の段階で、その辺の老朽度等も見ながら、工事のほうに今後進めていくというような考え方です。それにつきましては、やはりこの区内の状況を見ますと、ファミリー向けのマンションが増えてきまして、その関係で児童・生徒が増えているという傾向が１点見えるということと、それから。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"入学学用品費など、入学前にお金が必要になってくるものもあるということで、再三求めてはおりますけれども、入学前にこの就学援助を何とか支給できるようにしていっていただきたいと思いますが、今年度から八王子市も早めに、４月より前に支給できるようにしたということで、私、予算委員会でも質問しましたけれども、前年度の収入が決定するのが６月ということで。","respondent":"有馬学務課長","answer":"入学支度金を入学前にということで、それは昨年もお話を受けているところですけれども、基本的には、前にもお答えしているとおり、まず４月に区立の小・中学校に入っている児童であるということと、所得制限があるので、所得認定を６月に行うという関係で。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"５２ページの図書館の蔵書のところなのですけれども、障害者用資料が品川だけにしかないのですけれども、障害者の方はいろいろな障害がある方がいらっしゃると思いますが、やはり地域の図書館で借りられるということが必要だと思うのですが、この品川だけにあるという理由を教えてください。","respondent":"木村品川図書館長","answer":"主に障害者向けの資料を作成する拠点といいますか、そういうところが品川に置いてあるというところでございまして、蔵書が品川だけという形は、そういう形で表現をしていますが、実際にそれを借りたい、あるいは聞いてみたいというような方がいらっしゃいましたら。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"ほかのところでも借りられるということで、予約とかをして借りられるのですか。何度も行かなければいけないということはないということでいいのかということと、あと、購入実績のところで、実績が１年分しかないので、ぜひもう二、三年増やしていただけると動向がわかりやすいと思うので、この資料について見やすくしていただきたいと思います。","respondent":"木村品川図書館長","answer":"前段については、ご認識のとおりです。それから、この表現につきましては、検討します。","id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"３点ぐらい質問させていただきたいのですけれども、まず最初に、１３ページの教職員の健康管理のところに、子宮がん、乳がんの次にＶＤＴと書いてあるのですが、これは昨年も質問したのですけれども、これはわかる人はわかるけれども、わからない人はわからないと思うので、私も恥ずかしながらわからないのですが、これは文章の改善とかは今年もご検討されなかったのでしょうか。それはいかがでしょうか。","respondent":"有馬学務課長","answer":"１３ページ、ＶＤＴ検診なのですが、表現ということですが、一般的にＶＤＴ検診といいますと、パソコン業務等をやっている方の疲労度だとか、目の疲れだとか、そういったものをチェックする検診となっておりまして、どこの事業所でもやっている検診ですので。","id":"exchange-024"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ぜひ回答をお願いします。毎年同じ質問をしているのです。ぜひお願いします。毎年同じ質問をしている。","respondent":"有馬学務課長、熊谷指導課長","answer":"それから３点目の「光林荘」につきましては、昔から「光林」という字を使っていたというふうな認識でおりますので、これで合っていると思います。校区教育協働委員会なのですが、非常に言いづらいということで、去年もご指摘を受けたところなのですけれども、説明会等でも、各学校でぜひ愛称をつけてほしいということで、それぞれ今、検討しているというふうに聞いております。","id":"exchange-025"},{"speaker":"鈴木（博）委員","kind":"意見","question":"学務課長のほうですけれども、ケンシンのときに「健」と使うのは、一般的に異常があるかどうかわからないけれども、健康状態をチェックするときに使うのです。「検」というのは、明らかに病気をターゲットにして、こういう病気があるかどうかというときに使うのです。だから、これは誤植です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"あべ委員","kind":"確認","question":"障害者向け資料のほうは、借りられるのは借りられる、どの館でも借りられるのですけれども、要は、地域館に行ってもそういう資料が区の図書館にはあるのだということがわからないと誰も借りられないので、各地域館で、きちんと障害者向けの資料がありますということが、リストではなくて、きちんとありますということが明記をして。","respondent":"品川庶務課長、木村品川図書館長","answer":"子ども地域活動支援事業ですが、周知を徹底するというのはどこの層かですが、これは非常に難しい点もありまして、基本的には周知をしていくのは、参加する子どもたちになるかというふうには考えております。障害者サービスに関するパンフレットを独自に置いてご案内をしていますので、今年度は障害者サービスの担当者会というものを地区館も含めまして、スタッフも含めまして立ち上げまして、そういう意味では。","id":"exchange-027"},{"speaker":"あべ委員","kind":"質問・要望","question":"図書のほうは、ぜひその方向でやっていただければと思います。地域活動支援なのですけれども、これ、町会は結構知らないところが多いのです。そんなカード知らない。そこは多分おわかりいただけると思うので、所管課ときちんと連絡をとって、子どもに周知するのであれば、きちんと町会でもそれが実施できるところまで、ぜひ責任をもって持っていっていただきたいと思います。何かありましたら。","respondent":"品川庶務課長","answer":"まさに委員のおっしゃるようなケースであれば、我々も積極的に周知、説明等はしていきたいというふうに考えております。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"６ページの最初のところで、先ほどの子ども未来部のところと一緒なのですが、正規の職員と非正規の割合を、今後でいいのでどこかで示していただきたいと思うのと、正規でない仕事とは一体どのような仕事があるのかということを教えていただきたいと思います。それが１点です。２０ページの学事制度審議会設置とあります、これのメンバーとか、スケジュールも、どういうふうに進んでいくのかも教えてください。","respondent":"品川庶務課長、有馬学務課長、熊谷指導課長、村尾教育総合支援センター長、木村品川図書館長、本城教育次長、篠田学校計画担当課長","answer":"６ページをご覧ください。６ページですが、庶務課ですと、学校経営指導員、それから教育訟務員、この２名が非常勤の職員となっております。それ以外には、説明の中でも申し上げましたけれども、給食調理につきましては全て代行業者、それから栄養士につきましては。学校地域コーディネーターですけれども、コミュニティ・スクール、各学校にコーディネーターがおりますけれども。教育総合支援センターでは、この大きな分掌で言うと、教育事務係の５名中４名が正規、それからちょっと下がって指導主事６名が正規。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２９ページのスポーツ振興センターのところなのですが、数字が平成２７年度しかないのですが、これ、事故とかけがの問題は、数字が８０７件と載っているのですが、この推移、けがとか事故の関係の推移がどうなっているのか、ひとつ教えていただきたいのと、あと、２５ページに就学援助が載っているのですが、先ほど質問があったのですけれども、この就学援助の関係は、地域的な違いは何かありますか。","respondent":"有馬学務課長、村尾教育総合支援センター長","answer":"それから２点目の就学援助の支給についてということですけれども、学校別に資料はありますけれども、今は手元にないのと、選択制を敷いている関係で、細かな地域特性は出すのは難しいものというふうに思っております。主に昨年度は、ネットによるいじめ防止ということをテーマに、それぞれ関係の方々に来ていただいてご議論していただきました。回数は、昨年度は年間３回、７月、１１月、２月、今年も同じような予定で考えております。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"スクールカウンセラーが、昨年伺ったら１３人いらっしゃるということだったのですが、都費と区費のスクールカウンセラーの人数と身分をもう１回聞きたいのと、この概要からすると、特別支援教育のところにスクールカウンセラーという表記が２カ所あるだけなのですけれども、学校をどのように、小学校、中学校を回っていらっしゃると思うのですが、そこの中身がわかるように説明してください。","respondent":"村尾教育総合支援センター長","answer":"都のスクールカウンセラーは、一般的に生徒の悩み相談等を相談室で受けるというような取り組みが基本的なものではあるのですけれども、それ以外に、当然、本区ではいじめ対策に力を入れていましたので。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"文部科学省がいろいろ出しているものを見ると、かなり深刻な状況である。特に連携強化を強めて、子どもの心の闇にも接していきながら近づいて、何としてでも、人数がどうのこうのというよりも、１人でも命を失わせてはならないという対策が必要であるというような、てびきとかもいろいろ出ているのですが、今の状況で十分であると考えていらっしゃるのかどうか教えてください。","respondent":"村尾教育総合支援センター長","answer":"ただ、この自殺防止につきまして、先ほどお話ししたとおり、各学校も、いじめ防止等含めて、今、やはり日本の中、また東京都の中でも自殺対策は大変力を入れていかなければいけないという教育課題の１つでありますので。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"確認","question":"それからもう１つは、３７ページで、先ほど鈴木博委員のほうから質問があったのですが、イングリッシュレッスンで、これ、浜川中学校、大崎中学校はタブレットでやっているわけですが、４校にということで、あとプラス２校ということで、これはタブレットなのか、それともタブレットではなくパソコン室でネットでつないでやっていく、そうすることによって費用も、今は電力ぐらいで進めていけるし。","respondent":"熊谷指導課長、村尾教育総合支援センター長","answer":"新規採用の教員については、センター長から説明いたします。新規採用教員については、初任研という形で研修を、法定研修ではありますけれども、区のプラン２１を含めて、市民科等の研修もそうなのですが、初任者研修で主に入れていかなければならないのは、やはり保護者との対応の仕方であったり。","id":"exchange-033"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"さっき子どものほうだったのでお話しせずに終わったのですが、先ほどの幼稚園の小学校の先生をもし兼ねているという状況が続くようでしたら、できるだけ現場の状況というか、幼稚園のほうは管理職の方がそこをしっかりやられている状況ですので、園長先生が早く戻ることで、保護者の方が安心できるように、それは要望でお願いします。手を挙げてどこの中学校やりますかみたいなことだったのでしょうか。","respondent":"熊谷指導課長","answer":"校内無線ＬＡＮの整備校の中から、学校の希望も聞きながら決定してきました。","id":"exchange-034"}]},{"id":"topic-02","title":"品川区立学校生徒の事故","agenda":"品川区立学校生徒の事故","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"ただし、それが防げるかどうか、あるいは、何か手があったかどうか、それは当然、冷静に客観的に、やはりそういう不幸な子どもを減らすためには必要なことだから、その辺は冷静に本人たちの感情、周りの人の感情も考えながら、１つ１つゆっくりと慎重に、いろいろな状況を考えながら手を打つべきだと思うのですけれども、実際こういう研修をやりました。","respondent":"熊谷指導課長","answer":"非常に難しい部分ではありますけれども、予兆があったかというと、これについては非常に難しい、読みとれたかどうかということについては難しかったと思います。","id":"exchange-035"},{"speaker":"鈴木（博）委員","kind":"意見","question":"自殺があると、自殺だ、自殺だ、いじめがあると、自殺だというふうに何かあるたびに大騒ぎして、その辺のことをやると、結局、お祭りの後であとが何も残らないということもあると思うので、今回のことに関しても冷静にお願いしたいのと、とにかく実際に周りで、今、心が非常に落ち込んでいる人たちを、どうやって守るかという観点も、いろいろな原因の究明とともにお願いしたいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"ですけれども、やはり再発防止に向けては、原因究明をしていかなければ対策をとることはできないと思いますけれども、この間、事故後の対応ということで、ここの生徒一人ひとりに教員との面談を行ったり、あるいはまた生徒一人ひとりにカウンセラーの面談を行っているということですけれども、この内容と、どういった感じだったのか、そこで得た情報といいますか、結果を教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"もしかしたら同じことになってしまうかもしれませんが、在校生全員に対してもストレスチェックを行ったということで、それの必要に応じてカウンセラーによる面談を行っていったということで、答えられる範囲でいいですが、ストレスチェックはどういった内容だったのか、この必要に応じてというのは、誰が判断して、何人ぐらい面談を行ったのでしょうか。","respondent":"熊谷指導課長","answer":"何人ぐらいとあるのですけれども、その状況によってですので、最終的には一人ひとりの子どもたちのケアということで行っていますので、人数についてはここでは申し上げられないのですが、誰がというのは。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"カウンセラー等の方の見立てでやったということですけれども、学生からの希望というのはあったのでしょうか。児童・生徒から。","respondent":"熊谷指導課長","answer":"これについては、保護者の方や子どもたちから要望があったときにはお受けしています。ただ、全員話をしていく中で、子どもたちから、また次にということで、引き続きカウンセリングを行っているケースもあります。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"当該学年の教員の方にもケアが必要な状態だったということで、面談を行っているということですけれども、どういう内容で、どういう結果が得られたかということもお聞きしたいと思います。アドバイザリースタッフによる保護者面談を行ったということですけれども、これは全保護者に対して行ったのか、それとも希望者が行ったのか伺いたいと思います。","respondent":"熊谷指導課長","answer":"産業医による面談を行っておりますので、あくまでも面談内容なので、私も直接その内容についてはわかりませんし、お答えできないです。それから、アドバイザリースタッフの保護者面談ですが、これも保護者からご希望があった方のみ行っております。","id":"exchange-040"},{"speaker":"のだて委員","kind":"確認","question":"資料の裏面のところに、中・長期対応ということで、心のケアを継続していくということですけれども、先ほど報告があったかもしれませんが、改めて確認なのですけれども、これは生徒と教員両方ともということかということと、学校教育相談体制を充実していくということで、済みません、私、聞き漏らしてしまったかもしれません。もうちょっと具体的にどういったものになるのかお聞きしたいと思います。","respondent":"村尾教育総合支援センター長","answer":"１つ目の部分ですけれども、当然、保護者、それから児童・生徒について、カウンセリングの要請があればカウンセラーが対応して心のケアをしていくという、これについては継続して当該校では実施してまいります。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問","question":"保護者会の内容のところで、質疑応答されておられますけれども、学校に起因する情報は入っていないとされていますけれども、そうであれば原因が何なのかということになってくると思うのですが、この再発防止に向けて、中・長期的な対策が示されておりますけれども、原因究明については、どのようにやっていかれるのでしょうか。調査委員会を設置してやっているということなどはあるのでしょうか。","respondent":"村尾教育総合支援センター長","answer":"前回ここの会には、臨床心理士の大学の先生に来ていただきまして、今の子どもたちということで、例えば大きな一般的な話になりますけれども、社会的な特徴として、例えばＬＩＮＥというような子どもたちのツールがあるとか、最近の子どもたち。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問","question":"前回の５月１６日の文教委員会の資料では、原因が調査中ということだったのですけれども、警察のほうの原因究明というのは、何か情報は入っているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今後、どうしてこういったことが起きたのか、あるいは、これからの対策について、今後、保護者の方に説明を行っていく機会は設けられるのでしょうか。","respondent":"熊谷指導課長","answer":"その件につきましては、臨時保護者会で説明をし、その中で今後の対応について説明しておりますので、今のところ、それ以上のことを行っていく予定はございません。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問・要望","question":"こうしたことが起こったときに、学校や教育委員会で行っていくべきことが幾つかあると考えています。あわせて、こういう時代ですから、例えばネットですとか、ＬＩＮＥですとか、そういったものの上でのトラブルがあったかなかったかということを調べたかどうかということを一応確認します。調べたと言ったらどうなのでしょう、把握をしようとしたかどうかというのは確認させていただきたいのですが。","respondent":"熊谷指導課長","answer":"子どもたちとヒアリング、面談をする中で、ネットについてのことも出てきております。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"やはり直接講習を受けるのと、伝達というのでは、大分理解の度合いも違いますし、ゲートキーパーとして自覚を持って動いていくということであると、もう少し濃い研修があってもいいのではないかと思うのですが、それも含めて、今後、教職員の方たち一人ひとりに、しっかりゲートキーパーとしての視点を持っていただくために、今後考えていらっしゃることがあったら教えてください。","respondent":"村尾教育総合支援センター長","answer":"今後、５月から３月までにかけて、それぞれ、例えば生活指導主任会であったり、特別支援のコーディネーター研修であったり、さまざまな研修の中で、ゲートキーパーという研修のプログラム自体を入れるのか、いろいろな方面からの自殺防止ということで。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問・要望","question":"子どもに関してなのですけれども、１０代の自殺というのは、確かに思ったより多い数字ではありますが、ただ、厚生労働省の数字などを見ていますと、１０歳から１５歳というのは、さすがにそんなには多くない。特に直接亡くなったお子さんが、先生がこういうふうに言っていると聞いたときに、どう捉えるかといったことも含めて、やはり細心の注意を払って今後の指導をしていただきたいと思います。","respondent":"村尾教育総合支援センター長","answer":"今回、この校長会のほうで命を大切にするという部分については、当該校のほうにはまた違う形で、先生方、そして子どもたちへの指導ということで、ここの校長会が出したものについては、あくまでも当該校外の学校、それから特に近くの学校であったり。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問・要望","question":"臨時保護者会に参加された方何人かにもご意見を伺ったのですけれども、やはりなぜ、どうしてというところの深い闇がある一定、「ああ、そうなのか」と思えるような材料と言ったら失礼ですが、いろいろ調べた中身が何も示されないで、こういうふうに判断しました、結論もこうですというだけでは、なかなかおさまらないし、結構地域の方はいろいろな部分で関心を示していらっしゃるので。","respondent":"熊谷指導課長、村尾教育総合支援センター長","answer":"監督責任ですが、校長先生ですので、やはり自校の子どもが自殺をして亡くなったということについて、非常に責任を感じている、非常につらく重く悲しい気持ちを持っているということで、それについては。次につきましては、当然、各学校で子どもたちについて、児童・生徒理解、さまざまな取り組みを現在進めているというふうに考えております。","id":"exchange-048"},{"speaker":"沢田副委員長","kind":"質問","question":"その原因を究明して、細かく細かく知っても、それで、だったら何ができたのですか、何ができるのですかという、できることはみんなやってきていると思うのです、周りにいた人も。だから、それはもう、そういうのではなくて、やはり今のこういう世の中の中でどうしていくかということをしっかり考えていくということが大切だと思うので、それをしっかりと品川区でもこれからやっていってもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"これ、受給家庭には毎年送っていらっしゃるというご説明だったと思いますけれども、送るときに、今回これが変わっていますというものを、ぜひ何かヘッドレターのようなわかる形で送っていただきたいのです。１回読んでしまうと、なかなか新しいものを毎年手に入れようとしないかとも思ったのですけれども、その辺はどうなのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"配布につきましては、児童育成手当の受給者に送りまして、今後拡充したものについては補強するという形でサポートする、既に送ってしまいましたので、またこの次、８月に児童扶養手当の現況届を送りますので、その際に、またチラシ等を入れさせていただこうと考えています。","id":"exchange-050"},{"speaker":"あべ委員","kind":"質問","question":"大震災以降、電力削減、平成２２年度比でマイナス１５％ということですけれども、実績としてどんな感じで達成しているのか、数字がお手元にありますでしょうか。","respondent":"品川庶務課長","answer":"昨年の実績はあるのですけれども、昨年は目標１５％というところなのですが、実際のところは１３.６％という形で、限りなく近い形でやっていますが、先ほども説明しましたとおり、節電することによって非常に大きな影響等が出る場合。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問","question":"目標を持ってやることはいいと思うのですけれども、毎年１５％を掲げて、毎年届かなくて、毎年１５％という、その目標の立て方はどうなのだろうと思うのが１つと、いわゆる運用の努力で減らす部分と、やはりＬＥＤ等々を使っていくことで減らす部分があると思いますし、また、そういう設備的に電力削減を行っていけば、目標値もまた変わっていってもおかしくないのかと思うので。","respondent":"品川庶務課長","answer":"今ちょうど電力の供給が、最大でも大体５,２００万キロワットということで、６,０００万キロワットに１５％削減すると、大体５,１００万キロワットとなって、大体そのぐらいの数値ということで１５％という目標を設定しているです。","id":"exchange-052"},{"speaker":"あくつ委員長","kind":"提案","question":"本年の文教委員会におきましても、当委員会に係る所管事務の中から、年間を通して協議していきたい課題、また、常に意識しておくべき事項等について、委員の皆様より、ご意見・ご要望を聴取し、そした課題、事項を本年の文教委員会のテーマに掲げ、所管事務調査および行政視察を通して、具体性を深めていきたいと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/702264?Template=document&Id=4884#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":73352,"voices":191}},{"id":"h28-20160606-5","meetingId":"h28-cm06","date":"2016年6月6日","dateIso":"2016-06-06","committee":"総務委員会","time":"午後１時００分～午後２時３１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を5件抜き出しています。","topics":[{"id":"topic-01","title":"事務事業概要","agenda":"事務事業概要","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"確認なのですけれども。平成２７年度実績ということで。これは、件数で書いてありますので、重なっているのも、のべの件数というふうに理解してよろしいのでしょうかというのが１点と。その点については連携するというふうに出ておりますので、その数が、この区民相談室の中に入っているのか、それともそれは別の数としてカウントされているのか、その辺の関係について、お聞きしたいと思います。","respondent":"中元広報広聴課長","answer":"こちら、１８ページの区民相談室の件数は、こちらの第三庁舎にあります区民相談室でお受けしている件数をのべで合計させていただいたものです。今、おっしゃった男女共同参画センターでは、また別の場所で相談業務を行っておりますので、そちらと重なるものではございません。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"全ての発行に、個別に配送しているのかの確認と、そういうことが、やっていますよというお知らせの仕方がどうなっているのか、それを伺いたいと思います。そうですよね。参加者数が、のべで２７人ということなのですが、区長が直接、区民の方から、いろいろなテーマに基づいてお話を伺ったり、また区長のいろいろなお考えを直接お届けするすごくいい機会で、区民の方は結構、興味。とりあえず、以上です。","respondent":"中元広報広聴課長、仁平情報推進課長、久保田総務課長","answer":"こちらは、総合的にどういう形でやっていくかというのは、今後も検討しながら進めていきたいと思っています。こちらのほう、一応、４月末に解消されたという発表が出ておりますが、その点では、カードが遅れているということで。今年度の議論の方向性につきましては、現在、教育委員会のほうと調整をしておりまして、第２回目については夏頃に開催をしたいと考えておりまして。","id":"exchange-002"},{"speaker":"南委員","kind":"提案","question":"本来、開催をするためのテーマがあったのに、そういう悲しい事件が発生したために、それについてのことを取り上げたという、そういう理解、今、伺って聞いたのですけれども。そことの関係はどういうふうにされるのかというのをちょっと確認したかったので、後でちょっとお願いします。その辺について、もう１回、ちょっと見解を伺いたいと思います。では、ちょっと２点だけ、よろしくお願いします。","respondent":"久保田総務課長、中元広報広聴課長","answer":"もともとのテーマを変えてということではございません。平成２８年度につきましては、２回ないし３回を予定しているです。募集ものとかがありますので。そうしたところで、やはり複数日に渡らないと届かない、実際問題そういうところも出てまいりましたので、今後もさまざま研究しながら、他区の状況等も研究しながら、いい方法があればと思っています。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"さっきの南委員のご質問に続いてなのですけれども、マイナンバーに関するトラブルというのは、今のところないというふうなご報告でしたけれども、もし何かあったときには、この総務委員会にも、ご報告が速やかになされるのかという確認が１点と。それから、基本的な質問になってしまうのですけれども、会計管理室の、３ページの。基本的な知識が足りなくて。","respondent":"仁平情報推進課長、福島会計管理者","answer":"ただ、例えば、１件、２件という件につきましては、報告の必要はないのですが、当然、区としては、どういう事故が起きたかということで、重要な情報ですので、委員会のほうに報告するものです。こちらにつきましては、放棄するものですとか、そういった審議事項が固まった段階で召集していますので、この債権管理審議会がかなり続いております、大分標準化して、落ち着いていますので、大体、年３回ぐらいで十分かと考えています。","id":"exchange-004"},{"speaker":"吉田委員","kind":"確認","question":"確認です。開催回数、３回というのは、もうこれで決まっているということではなくて、必要があれば、その都度開催することもあると考えてよろしいですか。","respondent":"福島会計管理者","answer":"そのとおりです。","id":"exchange-005"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/227390?Template=document&Id=2046#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":31565,"voices":90}},{"id":"h28-20160607-14","meetingId":"h28-cm06","date":"2016年6月7日","dateIso":"2016-06-07","committee":"行財政改革特別委員会","time":"午後１時００分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"特区について一つお伺いしたいのですが、都の清掃施設の跡地の利用で、杉並区が保育園利用で都と協議をしているという話を聞いたのですけれども、品川区では、そのようなお話というのはあるのかどうかというのを確認させてください。","respondent":"柏原企画調整課長","answer":"それ以外の部分につきましては、そういった形での動きはしておりませんけれども、個別に例えば従来からちょっと課題となっています清掃作業所の跡地であるとか、そういったところは個別の交渉といいますか、やり方でお話を進めさせていただいているといった状況です。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"羽田についてなのですが、説明会がこの間何度か開かれて、この資料の中では計２,４００人ほどが参加されたということなのですが、区内３８万区民で、この数字ではまだ区民の０.５％ちょっとくらいしか実際に足を運ばれていないという数字になっていると思うのですが、この先の説明会の計画などについて、もし聞かれていたら教えてください。","respondent":"中村都市計画課長","answer":"現在特に国のほうから、この後説明会についての予定はまだ聞いておりません。しかし、品川区といたしましては、説明会を何度開いていただいても十分ということはございませんので、教室型の説明会も含めて、ずっと今までも、またこれからも要望を続けてまいります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"国家戦略特区なのですけれども、昨年の行財政改革特別委員会の中で民泊についての質疑もあったのですけれども、政府がこの間民泊の全面解禁に向けた原案をまとめたということで、報道では特区とは別の議論になる全国的な民泊解禁についてのルールが６月には求められ、閣議決定を経て施行される運びとのことですが、区長は既に、「民泊をやります」という旨を表明しているのですけれども、民泊については。","respondent":"柏原企画調整課長、中村都市計画課長","answer":"いずれにしても、民泊を行うということについては一定程度のルールが必要だという認識はありますので、どういった制度でやっていくかというのも含めて今検討を深めているといった状況です。区としましても、この経済成長とか経済効果、こういったものに貢献するということになっておりますけれども、ただこの経済効果につきましては、まず機能強化によって外国からの来訪者。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"今回の国の新ルートの提案ですけれども、区との約束をほごにする方針転換というだけではなくて、当時よりもさらに内陸ですよね、大井町の上、大崎の上ですからね。質問します。これまでどんな約束を国と交わしてきたのかというのを１点お伺いします。当時よりもさらに被害が深刻になる今回の計画なのに、なぜ区としては反対しないのか教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"区民に対する理解を深めていただくための説明会も求めてまいりましたけれども、こういった地域に対する理解と、それから今後出される対応策、こういったものをまずは注視して判断をしていく、最初から何も考えない、検討しないということではなくて。","id":"exchange-004"},{"speaker":"安藤委員","kind":"確認","question":"それと、文書の件ですけれども確認できていないというところなのですけれども、モノレールの内側は飛ばさないルールをということも本会議の中でも答弁がありましたけれども、そういったルールに関しても文書が全くないのか、それとあと、羽田空港の沖合移転に関しても、大田区と一緒にたくさん働きかけをしているのですけれども、最終的に国と取り交わした約束というのはないのかどうなのか。","respondent":"中村都市計画課長","answer":"区として反対をすべきですけれども、現在この案がまだ決定というところではなくて、そしてこれからこの環境方策における方針が出されるというところで、まずはそれを国からそういった提示を受けた上で区として判断するべきだということで。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"防音工事については、法律上は防音工事の助成対象地域に住宅が１軒もないという説明があったのですけれども、そういう法律の枠組みとは別に、防音工事については現在都や自治体と相談中という説明があったのですけれども、質問したいのですが、品川区は防音工事の対応について、国と現在話し合いをしているのでしょうか、それともしていないのでしょうか、お伺いします。","respondent":"中村都市計画課長","answer":"今現在は、区としても通過する経路のみならず、品川区全域について何らかの対応を検討していただきたいということで、この夏の環境に対する方策を注視しています。","id":"exchange-006"},{"speaker":"筒井委員","kind":"確認","question":"去年の１月に区議会として当時の石田秀男議長の名のもとに意見書を国土交通省に出したと思うのですけれども、それに対しての返事というのは区としては確認しているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"筒井委員","kind":"意見","question":"それを区が認識しているかどうか、返事があったかどうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"筒井委員","kind":"質問・要望","question":"わかりました。とにかく積極的に区としても国に対して意見を述べていただきたいということを要望として申し上げたい。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"確認","question":"環境対策のところで、騒音測定の充実というのがありますけれども、これは国のほうで測定して１４カ所ぐらいあるという話なのですが、品川区にあるのかという確認と、今後増やしていく中で品川区が検討されているのか伺いたいと思います。","respondent":"中村都市計画課長、三ツ橋環境課長","answer":"この増便数の考え方ですけれども、これは国のほうで一昨年に出されました取りまとめをホームページからダウンロードすると、資料の中にこういった記載があるということで。環境対策の中での騒音測定局についてのご質問にお答えいたします。国が騒音測定をするこの案に当たっては、現在品川区の中では国の測定局はございません。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"新ルートにすることで、１日当たり６３回から７２回増えるということですけれども、今新ルートでは８０回から９０回になるということで、１０便増えるのかと思っていたのですが、この辺をもうちょっと詳しく、どういうことなのか、ほかのところも増やして、５０回から６０回増やしていくということなのか伺いたいと思います。","respondent":"三ツ橋環境課長、中村都市計画課長","answer":"測定局の考え方ですけれども、品川区内にもしもこの飛行ルート案が案でなくなった場合、飛行ルート下には品川区としても騒音影響の部分がありますので、検討はすることになると思われます。この増便数の考え方ですけれども、新飛行経路案を採用する前も、既存の離着陸数というのがありますので、その差、掛ける年間日数ということになるかと思います。ただ、その中には南風時以外に北風時もあります。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"その他、１日当たりで３０便増えるということで、８０便から９０便に増えて１０便で、３時間と考えると、３０便ということですけれども、先ほどのご説明だと、１日当たり６３便から７２便増えるという話だったのですが、その誤差はどういうことなのか伺いたいと思います。","respondent":"中村都市計画課長","answer":"それからあと、区としてまずは夏に示されます環境方策、こういったものを確認して、それでまずは判断をするというところで、今そういった説明も十分に聞かないところで賛成、反対という意見を述べるような時期ではないという判断から。","id":"exchange-012"},{"speaker":"渡部委員","kind":"確認","question":"この辺をいろいろやっていたと思うのですが、先ほどご説明いただきました公共施設等総合計画の策定についてというのは、あくまでも総務委員会のほうでかかわってくるべき内容だと認識をするのですが、これはこちらでもある程度話し合いは進めても、その辺の仕切りというのはどうなっているのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"渡部委員","kind":"確認","question":"すみません、その確認だけでした。では、これはあくまでもこちらで審議等も図っていった上で総務委員会は報告という形で間違いないということでよろしいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"あべ委員","kind":"確認","question":"本日は審査項目の概要説明ということで、あまり個別の案件に入り込み過ぎないように質問したいと思います。公有地の関係なのですけれども、すみません、私ちょっと行財政改革特別委員会を離れて少し時間がたってしまったものですから、この国有地なのですけれども、小山台の広大な土地は今どういう状況にあるかというのを確認させていただければと思います。","respondent":"柏原企画調整課長","answer":"総合戦略との比較の部分はしていただいたところですけれども、有効活用プランの部分につきましては、品川区も認識といたしましては、有効活用プランをつくったときも、建物、品川区が持っている施設ですね、建物の施設が、６０％は３０年以上を超えるといったところで。","id":"exchange-015"},{"speaker":"あべ委員","kind":"質問","question":"それで、確かに団体にというのと事業単位でというのと両方あると思うのですけれども、団体にも助成金を出し、そしてまた別の事業に対しても、その団体に補助金を出したりというようなことというのは結構実際にあると思うので、いずれかの機会に事業名とそれから支出先と言ったらいいのですか、団体名を分けて書いていただけると。","respondent":"秋山財政課長","answer":"補助金の性格としましては、個別の団体に補助金をお渡ししているものとか、それからあと、事業として、個々の、個々のというのですか、たくさんの方にお渡ししているのとか、あとはイベントに対して出しているものとか、いろいろと性格は分かれておりますので。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"前向きに答えていただいて、ありがとうあります。もちろん常識の範囲で、あまり煩雑にならない程度でという前提でお伺いしておりますので、ぜひよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"筒井委員","kind":"質問","question":"公共施設等総合計画の策定についてのところなのですけれども、４番目、スケジュールのところで、６月上旬の世論調査実施とありますけれども、この世論調査の内容と方法を教えてください。","respondent":"柏原企画調整課長","answer":"公共施設にかかわる部分についての質問項目を設けさせていただいて、それについてお答えいただくというような形で進めたいということで、広報のほうとはそういった事務的な手続を進めているところです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"公共施設等総合計画のほうですが、こちらは何年の計画なのかということと、それとあと、２０１４年４月に総務省から公共施設等総合管理計画の策定に当たっての指針というのが出されているのですけれども、品川区はこの内容に基づいて作成するとの考えなのか伺います。","respondent":"柏原企画調整課長","answer":"まだ確定の部分でございませんけれども、この計画、公共施設の計画の期間ですけれども、一定程度の建物ですから、長いスパンということで、５０年という考え方というのが一つ基準にはなるのですけれども、それがよろしいかどうかも含めて。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"それで、やはり、人口推計に基づいた計画にあるべきなのですが、総合戦略のほうの中身をお伺いしたいのですが、基本目標のほうに待機児解消というのがない理由、あと基本目標４のところに、住み続ける品川区をつくるということなのですが、特養ホームの増設というのは、住みなれた地域で住み続けるためには必要だと思うのですが、そういった増設がないのです。","respondent":"柏原企画調整課長","answer":"今委員からご指摘があった部分につきましては、この総合戦略だけではなく、品川区は長期基本計画、総合実施計画ということで計画的に事業を行っているものでありまして、その中でしっかりと計画を立てて出していくですので。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"人口の推計に見合った保育園や特養ホームの計画的な増設計画というのをあらゆる場面で考えていく必要があると思いますので、それは意見を述べします。大分状況も変わってきたと思いますので、ぜひこの状況をご報告していただきたいと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"（仮称）公共施設等総合計画、これは総合管理計画のことですか、それとも新たに仮称と頭につけて、品川区は総合計画なのだというのか、ちょっと言葉が、管理を入れている人と管理を入れないで、このまま読んでいる人がいるので、ちょっと仕切り方を教えてください。","respondent":"柏原企画調整課長","answer":"これまで内部でもいろいろ内容をどうやって進めていくかと検討していく中で、管理という言葉が入った中で、いわゆる施設の管理だけみたいなところに着眼をすることではない、そういうふうに区民の皆さまに見て取られるのはどうだろうかということで。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"公有地のところなのですけれども、旧荏原第四中学校のところで、高校への貸出しが平成２９年８月末までということで、まだ活用が確定していないということでしたけれども、あと１年ちょっとというところになってきておりますが、私のほうでも、特養ホームと避難所になる集会所などを入れた複合施設ということで検討してほしいということで、案としては受け取るということでしたけれども。","respondent":"柏原企画調整課長","answer":"旧荏原第四中学校ですけれども、区内の私立学校に貸していますが、その後の活用につきましては、現在いろいろな面から、いろいろな角度から検討を進めているといったところです。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"いろいろな角度から進めているということなのですけれども、そうすると、この計画はいつごろ決めていくようなスケジュール感、どういう感じになっていくのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"こちらのほうは表にもありますように、貸付けの期間が来年の夏までです。そういったところのスケジュール感に合わせながら、その後についての考え方、仮に何かするとすれば、例えば設計のお金であるとか、工事のお金であるとか、いろいろなところが想定されます。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"来年の８月の貸出し終了のスケジュール感に合わせてということですから、もうそろそろ予算の検討等を行っていくのかなという気もするのですが、そうすると、それまでに大体計画は決まってくるということでよろしいのでしょうか。","respondent":"柏原企画調整課長","answer":"いろいろな事情等が起こるかもしれませんけれども、そういった期間が決まっているものでありますので、その後につきましてはこの期間に向けて我々も検討を進めたいです。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"この旧荏原第四中学校跡地は２回ここに貸し出しているということで、ぜひ地元でも３度目はやめてほしいという声もありますので、区民の要望に合わせて、施設建設も含めてやっていっていただきたいと思います。ほかにもいるのか教えていただきたいと思いますとともに、このファシリティマネジメントの専門家というのは大学教授とか、そういった方になるのでしょうか。","respondent":"柏原企画調整課長","answer":"これも先ほどちょっと議論があったところですけれども、どういったものを対象にするかというのは今後議論を進めながら決めていきたいというふうに思ってありますが、国の言い方からしますと、公共団体、区が持っている施設全部ということになりますので、建物から道路、橋、公園。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、プロジェクトチームのメンバーは何人ぐらいになるのでしょうか。この総合計画の中で、長期的な視点を持って最適な配置を実現するため要請がなされたということですけれども、最適な配置というのはどういうことか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"プロジェクトチームそのもの、こういう形で決定ということではまだ内部でも決定はとってございませんけれども、アドバイザーとして今３名程度というところで想定してございまして、あとは庁内の関連する部長、課長級の会議体というところで検討していますので。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区として最適な配置を考えていくということですけれども、統廃合して区民のサービスが低下していかないようにしていっていただきたいと思いますので、区民の福祉が充実するようにやっていっていただきたいと思います。後ろについている表のところで、障害者団体への補助金があると思うのですけれども、各団体で補助額がいろいろ違うのですけれども、違いがある理由を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"羽田の問題もその国有地の問題もそうだと思いますし、場合によっては国家戦略特区もまだ続いているということですので、この先の展開等がこの１年あると思いますので、そういった場合は正副のほうで諮っていただいて、速やかにまた議題に入れていただけるような運営をしていただければといいますのが、この自民党・子ども未来の要望としますので、よろしくお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"あべ委員","kind":"意見","question":"国家戦略特区に関しても、現在のところはそういう性格があるかなというふうに感じております。それぞれの項目の発生の仕方ですとか、タイミングに合わせて、ぜひできるだけ早い段階でこの１年間どういう形でやっていくのだというのがある程度分かる形で見せていただけるとありがたいなと、これは正副にぜひお願いできればと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"安藤委員","kind":"提案","question":"ごめんなさい、最後、補助金の中で、区立保育園の民営化の話がありますけれども、国から補助金が来ないので、区は財政負担になるという理由で民営化を進めるとしておりますが、むしろ国には保育園運営費補助金の復活を求めることこそ区民利益にかなうのではないかと思いますので、区議会として、この委員会として国や都に必要な提言ですとか、こういった補助制度をつくるべきだとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問・要望","question":"羽田に関してなのですけれども、今わりと騒音にシフトしたお話が出てきたのですけれども、委員会の中では安全性に関することについてもぜひ加えていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/700324?Template=document&Id=6008#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":39680,"voices":127}},{"id":"h28-20160608-18","meetingId":"h28-cm06","date":"2016年6月8日","dateIso":"2016-06-08","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後３時５７分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件抜き出しています。","topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"先ほどブラインドサッカー等々は会場がまだ未定だということは確認したのですけれども、ちょっとそれは後にして、右側の大会ビジョンのところの（１）で下から２行目のところに「３つのコンセプトとし、史上最もイノベーティブで、世界にポジティブな改革をもたらす大会とする」となっているのですが、イノベーティブってちょっとよくわからなかったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"ブラインドサッカーについては、先ほどのような説明で確認がおくれているという状況はわかったのですが、同時に会場もはっきりしてきたところである中で、早く決まっていくことが望ましいかなと思って見ているのですけれども、都議会の中でオリンピック・パラリンピック等推進対策特別委員会という委員会が設置されているようで、そこの質疑をちょっと見てみたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"そういうことをやっぱりどういうふうに考えているのかという、品川区が会場なので、この会場がある区として、どういうふうにそのことを考えているかというところを改めて聞きたいし、それからこの委員会としてもそういう問題についてはやっぱり必要な状況だから、委員会として一定の意見を関係機関に上げていくという必要があるのではないかなと思うので、この問題について。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"１点目の英語表記につきましては、確かに組織委員会のこの間のいろいろな表示物を見ますと大変英語表記が多くなってございまして、判読するのに私もいろいろありますが、ただ、やはり大会組織委員会がきちんとオーソライズをして決定していき。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"大きくまずお伺いいたしますが、そのオリンピック・パラリンピックについては担当の課長が説明等をしてくださっているのですけれども、まずこれは私も期待、楽しみにしておりますが、やはり全庁挙げて取り組んでいくという思いが私はあるのですが、その辺企画調整課長としてこのオリンピック・パラリンピックに対して区として、具体的という話はいいです、大きくでいいですけれども、どういうふうに捉えて。","respondent":"柏原企画調整課長","answer":"これは予算立てしたとき、区長の施政方針とかでもお話申し上げている部分もありますけれども、このオリンピック・パラリンピックが来ると、品川の町に会場があるといったところは、これは町のにぎわいであったり活性化、スポーツ振興。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"思いは伝わると考えていますので、しっかり行政と議会、あと区民の方々たちで組んでこれからもまたやっていきたいと思うのですけれども、今日委員長に言われて大きい質問ということで、大きくないかもしれないですが、大きい質問を心がけてしたいと思うのですけれども、初めての委員会なので、オリンピック・パラリンピック準備課長にちょっとお伺いしたいのですが。","respondent":"小川オリンピック・パラリンピック準備課長、柏原企画調整課長","answer":"したがいまして、今は私のところで庁内に関することそれから庁外に関する関係団体との仕切りについても、準備課のほうで進めているです。そこが動く中で、だんだんオリンピックの全容といいますか動きも見えてきたところで、２年前と昨年課としてつくったのですけれども、これはもう先を見たという、この年数の間で何ができるのかというのをこれは本格的に課として。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"それで、準備課長。組織という意味では一本化したと。いわゆる仕事も大きくなった、予算もそういう形で大きく、倍増ではなくて５.２倍ですよね、予算があるわけですから、その辺について改めてどういうふうに進めていくかという思い、具体的に何をやりますということはもうわかりますので、その辺の課長の準備課長としての思いをちょっとお伺いしたいのですけれども。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"準備課といたしましては、何よりも区の責務であります機運醸成という部分で、しっかり区民の方を巻き込んで確実に２０２０年に向けて盛り上がるためにいろいろ仕掛けをさせていただき、成功に向けて邁進してまいりたいと思っているところです。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"ノウハウをしっかりつかんで２０２０年のオリンピックまで続けていただきたいという思いがあってあえて質問するのですけれども、人事、組織のことはわかりませんという答弁になってしまうのはわかるのですけれども、今日は第１回目ですから、その辺の思いだけは伺っておきたいと思いますので、部長でも課長でも、思いを教えていただけますか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そのときを目指して、成功するように常に仕事には取り組んです。ただ、委員ご指摘のとおり、人事関係につきましては確約は当然できないものですので、そうした部分では、組織の継続性はきちんとしていくつもりです。","id":"exchange-007"},{"speaker":"いながわ委員","kind":"提案","question":"東海地区が入っていますので、大田区も一部食い込んでいるから東京都の公園でなければいけないのかもしれないですけれども、ただやっぱり地元の行政としてしっかりそこは意見を言うとか、提案をするとかというのがあってもいいのではないかと思うのですけれども、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"その先の段取りですが、当然地元自治体としていろいろ意見を言う場面はありますし、また東京都のほうも地元自治体の意見はお聞きしたいということで、そういうお話もいただいてありますので、機会を捉えましてさまざま要望については申していきたいと考えています。","id":"exchange-008"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これ、具体的に、ちなみに今はオリンピック・パラリンピック準備課長がやられていますけれども、そういう場合というのはどうなのですか、所管としては公園課が直接やりとりをするのか、それとも企画調整でそういったやりとりをするのかというのは今後どうなるのですか。今後です。このオリンピックが終わった後のいろいろな調整とかいろいろあると思うのですけれども、どこがやるのでしょうか。","respondent":"柏原企画調整課長","answer":"ただし、区の大きな施策であったり考え方とか、恐らく区トータルの中での調整といったところが大きく出てきたようなところの場合ですと、企画が全面に立ったりもしくは公園の部隊と一緒になって交渉したりとかというところで、場面場面に応じた形での交渉となりますが。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"広告代理店が入っているというのも聞いていますけれども、そこのところをもう少し今後４年間、ここをやはり大きく打ち出していくチャンスかなと私自身は思っているのですが、こういったものが今度どんどん出てくるのか、礎をしっかり築きながら品川区を発信していくというところについてのお考えをお聞かせいただきたいと思います。","respondent":"中山企画部長","answer":"それは総合推進本部の中で議論しながらやっていく。こういう取り組みでやっていきたいと考えております。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"平均点以上のものをたくさん並べて、それによって成功するということももちろんあると思うのですけれども、やはり品川区らしい企画を、先ほど場面場面というご答弁もありましたけれども、ぜひ意識をしていただいて、世界中の方がオリンピックに行くのだったら品川区に行ってみようというようなところで、我々もそこはこの委員会で検討していかなければいけないでしょうし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そういうスケジュール感といったらいいですか、いつぐらいまでに品川区の独自の計画をまとめて公表して、具体的に区内の方々に協力を求めていく。だけれども、それまでの間のスケジュール感のようなものを教えていただければと思うのですが、いかがですか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今まさに準備を進めておりまして、これから公募をかけていくかと考えている事業ですが、こちらの事業の内容といたしましては、区内の企業や団体等を応援団というか、品川の応援団ということで編成をして。","id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もちろんそういうことも先ですけれども、私が思っているのは、全庁的なことをやっていかなければいけないわけです。だから、そういうことを一つにまとめて、できれば議会なりに報告をしていただきたいということをお願いするわけでありますので、決して課長の答弁は間違っていないのだけれども、私たちの思いとしても、全庁的なことで考えていけばいいと思うのですが、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした中長期的なスケジュールにつきましては、まさに先ほど出ました推進本部の中で今検討していますが、なにぶんにもまだ大会組織委員会から個別具体的なものが何も示されていないので、なかなか区としても苦慮していますので、そういった部分で機会をとらえて。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"自治体としての意見も求められつつ、なかなか具体的なものが示されないという中で大変苦慮していらっしゃることもあるかなと思いますが、例えば一つ気になるのが、前年度の最終の委員会のときに伺ったのですが、キャラクターですね、マスコットキャラクターで、これは品川区独自のキャラクターということで、これが例えば大会全体のキャラクターになるのですかというご質問をさせていただいたら。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"位置づけといたしましては、まず３競技のキャラクターですとか２０２０年東京オリンピック・パラリンピックを契機とした事業をやるに当たっては、必ず東京都経由で中身の確認をしていただく必要があります。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"そうしますと、今度東京の組織委員会との関係なのですが東京の組織委員会には大会に言うためにも自治体としてのいろいろな発言をする場があるということで理解していいのでしょうか。ですので、１個東京の組織委員会との関係が質問で、要望というか意見としては、最終的には区民やそれ以外から見に来た方たちにとって一番いい形のキャラクター設定とかになるようにしていただきたいというのが要望です。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"それから実際に運営等全ての大会の責任を持っているのが大会組織委員会という組織です。先ほど申し上げましたのは、区は必ず東京都を通じて大会組織委員会と今接触をしているという関係になっているものです。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"確認","question":"「後利用については、ホッケー競技場に加え、フットサルなどにも使える多目的グラウンドとして活用を検討していく」とあるので、もうずっとこのままドッグランとゲートボール場はなくなっていくということなのか、そういった事が利用されている方への周知というのはどういうふうにされているのかというのを伺いたいのと、あと、一番下の整備費（予定）のところで約４８億円という。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"整備費の４８億円については、当然のことながら品川区としての負担は全くございません。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"このドッグランとゲートボール場については、やはり八潮の方も利用されているということもありますし、こういった場所も区内になかなかないというところでは多くの方が使われているのかなと思いますので、どのようになっていくかは区民のほうへの説明もぜひしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"つる委員","kind":"質問","question":"マスコットキャラクターなのですが、表彰等のところですけれども、どういうレベルのルールかわからないのですが、最優秀作品については各競技について１点、３万円分の区内共通商品券なのですが、応募者が１８歳未満の場合は相当額の図書カードというふうに分けているのですけれども、これはどういうルールでそういうふうに分けられているのか、教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"年齢が１８歳未満の方については、やはりいろいろ図書に触れていただきたいという思いから商品券というよりかむしろ図書カードのほうがいいのではないかという判断で、年齢の低い方については図書カードとさせていただいたところです。","id":"exchange-018"},{"speaker":"つる委員","kind":"確認","question":"大きいルールとか決まりとかではなくて、品川区としての、もっと言うと準備課としての思いとしてそういうふうに分けたというところですね。そういうふうに理解をしました。確認させてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおりです。","id":"exchange-019"},{"speaker":"つる委員","kind":"確認","question":"前半のところの確認です。さっきの準備課の思いかどうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"準備課のほうの思いです。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"改選前もオリ・パラの委員で発言をさせていただいたのですが、障害者スポーツの中に、この表面の２番ですか、フォークダンスで肢体不自由者・視覚障害者・聴覚障害者等をローテーションで実施で、ここには聴覚障害という障害の種類が出ているのですけれども、これは実際に水泳をやりたいとかそういう場合というのは。","respondent":"池田スポーツ推進課長","answer":"ただ、障害者のスポーツフリー利用、この３番、４番と、それから２番の障害者スポーツ教室につきましては、人数がまだまだ少ないと考えていますので、これからも多くの方に参加をしていただきたいと考えています。","id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問・要望","question":"これは３年ぐらい前なので、これは平成元年からやっているので、実際にその辺がどうなのかという、これは障害者福祉課長もおっしゃっていたように、やはり聴覚障害はデフリンピックというのですか、それに該当するので、どちらかというと障害を持ちながらも健常者寄りだという話も聞いているので。何か一言、障害者福祉課長のほうからあればお願いします。","respondent":"中山障害者福祉課長","answer":"そのときは合図をやはり音だけではなく手でやるみたいな形のことを水泳連盟さんの方でも工夫をしてくださっているので、やはりこういうことを重ねる中で対応が可能な範囲というのが徐々に広がってくるのではないかと考えているところです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"課長にお伺いしますが、障害者福祉課長として今日お見えになってくれていると思うのですけれども、具体的にこのスポーツ推進課とどういう連携をとっているか、またすみ分けとかそういうのがあれば、具体的にどういう形で２課が施策といいますか、連携しているのか教えていただけますか。","respondent":"中山障害者福祉課長","answer":"この間、オリンピック・パラリンピックのこともございまして、障害者福祉課とそれからスポーツのほうの推進の部署も一緒になって相談をいただきながら水泳大会の実施であったり、事業の中身、どういった中身を行い。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"先ほどの質疑の中で、やはり全庁的ということもありますし、オリンピック・パラリンピックという形において、障害者福祉という課の課長としてどういうふうに考え、どういうふうにこれを結びつけていくかというのを障害者福祉の課長とオリンピック・パラリンピック準備課長２人に答弁をいただきたいのですけれども、お願いします。","respondent":"小川オリンピック・パラリンピック準備課長、中山障害者福祉課長","answer":"東京五輪でもパラリンピックのほうを１人でも多くの方に見ていただき感動していただき、また障害者スポーツ、障害者の方への理解が深まることを着実に目指したいという思いで。所管課でありますので、私は本当にパラリンピックを、アスリートを育てるというところはスポーツのほうの部署の仕事になるかと思いますが、生き生きとスポーツをして障害のある方が楽しめること。","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"大前提としてキャパが決まっているところで全ての区民対象のスポーツ事業だから、障害者だけを広げるというふうにはなかなか困難かもしれないけれども、そういう方向でぜひ取り組んでいただきたいと思っているのですが、今実施している、これはこれとして伺ったけれども、これからそういう要望も含めてどういうふうな考えがあるのかをちょっと教えていただきたいと思います。","respondent":"池田スポーツ推進課長","answer":"私どもとしましても、できれば皆さんがプールをご利用できるのが一番よろしいところではありますけれども、障害をお持ちの方のプールということで日野学園を第２・第４のこの部分だけで現在のところは実施していきたいと考えてございまして。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"障害者の方々への施策が日本の国自体もそんなに進んでいるほうではありませんし、したがってやはりこういうオリンピック・パラリンピックを機会に今までやっているのをもう少し見直していい方向でのそういう改善というのを探っていただくべきではないかなと思いますので、希望調査も含めていろいろな機会を通してやはりやっていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もし状況、例えば発達障害をお持ちの方が団体でのサッカーが難しいから個別にサッカー教室に通えるような、マンツーマンで教えてくれるようなサッカー教室を探しているのだけれどもというようなご相談があったときに、それは私どもではわかりませんということではなくて、ちょっと調べますとかそういう体制に今なっているのかどうかということを、一つ確認としてお伺いをしたいと思います。","respondent":"池田スポーツ推進課長、中山障害者福祉課長、小川オリンピック・パラリンピック準備課長","answer":"障害をお持ちの方の地域スポーツについての参加についてのご相談につきましては、これは昨年私が説明したとおり。できるだけ障害のない方にもお越しいただき、障害のある方の理解というところで焦点を絞ってやっていくつもりですので。特に、品川区内でブラインドサッカーというものが開催される予定であるということで。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問","question":"あと区の施設を利用した障害者スポーツに取り組んでいる団体はたくさんあると思うのですけれども、今、この資料で示されたのはスポーツ協会が開催しているのが主だと思うのですが、そうしたほかの団体、民間だったり区の施設を利用した、そして区民が参加した障害者スポーツという団体を把握されているのかどうか、ちょっと伺いたいと思います。","respondent":"中山障害者福祉課長、池田スポーツ推進課長","answer":"今後ですけれども、スポーツを行っている体育館とかあるいは文化センターみたいなところにも合理的配慮というのは文科省の指針の対応に沿って実施していくような形になってまいりますので。先ほど、区の施設を利用する、区以外の障害者スポーツについての利用の団体の状況ですけれども、私どものほうでは、特に団体の利用の内容については細かく把握していないところでございまして。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういったところをしっかりと把握して、先ほどもほかの委員から要望を聞くようにという要望もありましたけれども、そういうことを聞いて広がる支援ができる、また障害者スポーツをさらに広げていけるというところにつながると思うので、ぜひそこを握っていただきたいなと、パラリンピックに向けてというところで、競技する、今されている方だけでなくて、やはり広く広げていくところでは。","respondent":"安藤文化スポーツ振興部長","answer":"あとここにあります体育館での教室さまざまにつきましては、障害者福祉課もそうですけれども、障害者７団体の方々に呼びかけて参加を求めたり、これは本当に昭和５７年からずっとやっていまして、毎回ご案内して。","id":"exchange-029"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは喜ばしいことなのですけれども、これはあくまでスポーツクラブの主催なので区としてもどこまでお話ができるかどうかわからないのですが、午前中開催で６０人がマックスなのではないかなと私は個人的に考えているのですけれども、その辺を含めて区のお考えもお聞かせいただきたいのが１点と、もう一点が、９番目の啓発・研修の中の二番目の区民まつりの４地区が、これは大井第１、荏原第２、大崎第２。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"こちらも当初平成１０年の開催のときには、実を言いますともっと盛大にやっていただいたところでございまして、グラウンド・ゴルフというものにつきましては、健常者の方は当然できますし。今年度につきましては、今のところ予定では５地区ほど予定をしておりまして、できるだけ同じ地区に被らないようにということでは思いはあるのですけれども、同じ地区のところもあるようですが。","id":"exchange-030"},{"speaker":"高橋（伸）委員","kind":"確認","question":"ありがとうございました。その１点と、これは再確認なのですけれども、区民まつりに関しては、あと１カ月先になっておりますけれども、今課長がおっしゃったように大体昨年同様の地区でやるという認識でよろしいのでしょうか。","respondent":"池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"グラウンド・ゴルフ大会につきましては、最終的なものは全て旗の台地区のスポレクのほうで決定するところですけれども、昨年もおととしも体育館が使える間は体育館も使っているということで。今現在、スポーツ協会のほうでブースを出す予定の地区が、八潮と荏原第２、大崎第２、荏原第５、荏原第３の５地区について、今予定だということでこちらのほうで把握しています。","id":"exchange-031"},{"speaker":"つる委員","kind":"質問","question":"裏面の９番、啓発・研修の一番最後、ユニバーサルマナー研修なのですが、これはたしかお聞きした中ではスポーツ推進員対象だと。","respondent":"池田スポーツ推進課長","answer":"ユニバーサルマナーを受ける前と後ですけれども、まず障害者に対する考え方ですが、車椅子で例えば押すときにはこうあるべきだというもの、これが個人の中に頭に植えつけられていたもの、それを実行すれば障害者のためのことなのだなと思っていましたけれども、実はそうではなく。","id":"exchange-032"},{"speaker":"つる委員","kind":"質問・要望","question":"印象に残った言葉というのは、ハードは変えられないがハートは変えられると、私もたしか一般質問で引用して、ある講師の方が、私も３年前、２年前か、お聞きして感動したということで引いた文章だったのですけれども。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今年度につきましては、予算をきちんとつけまして、対象といたしましてはまず新規採用職員１００名程度を対象にユニバーサルマナー研修をやる予定です。","id":"exchange-033"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひあと４年ありますので、しっかりと庁内、それから区民の皆様に対しての研修の拡充を積極的に検討いただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"それで障害の程度に合わせていろいろな参加の仕方があるということは、なるほどおもしろいスポーツなのだなということを知ったので、例えば私、この中でもまだズンバとかアキュラシーというのはよく理解していないのですけれども、そういうのを、もちろん品川で行われるのはブラインドサッカーですけれども。","respondent":"池田スポーツ推進課長","answer":"こういったスポーツについて全てということまではいけませんけれども、新たにできた障害をお持ちの方も取り組めるようなスポーツとかそういったものについては、全て障害者の、今度ユニバーサルスポーツ大会ということで名前を変えしますけれども、年２回。","id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問","question":"文化観光課長にお聞きしたいのですけれども、今ありましたが、先ほど区民主体の芸術文化活動を根本にということでお考えになっているとオリ・パラ準備課長からありましたが、それも当然そうだと思うのですけれども、先日、前期の最後のオリンピック・パラリンピックの委員会で視察をした日本財団のパラサポセンターの方に、このイギリスのロンドン・オリンピックで全国で２０万件の文化プログラム。","respondent":"鈴木文化観光課長","answer":"そのときにどこが中心的な窓口もしくは役割を担うかと言えば、ご意見のとおり文化観光課であると認識しておりますので、今後も全庁的な連携体制をとりながら、しっかりと取り組んでいきたいと考えております。","id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここの運営を任されている団体がこのアールブリュットに関して日本の中でも非常に先見的なものを持っているというところもありますので、今ちょっと計算してみると平成３１年に開設ですから平成３２年が２０２０年ということで、ぜひこの辺の動きも絡めてオリンピック・パラリンピックを見据えた中で、アールブリュット美術館もその中にできるということでありますが。","respondent":"鈴木文化観光課長","answer":"ご指摘ありましたアールブリュット展については、区としても認識しておりまして、昨年度はしながわ水族館で実施をいたしましたが、今年度に関しましては、先ほど申し上げた品川区民芸術祭、この中の一つのプログラムということで位置づけて。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"今いろいろお考えになっているということでしたけれども、私の質問の趣旨については、やはりロンドンのイメージが非常に強いので、いろいろなところの津々浦々でさまざまな文化芸術活動をしているというイメージを考えたときに、そういった知見を持っているところの力をかりるということが必要であると私自身は思っております。","respondent":"中山障害者福祉課長","answer":"昨年度開始したアールブリュット展を今年、来年ということで地域を変えながら品川区全域に広めていき、この平成３１年度を迎えられればと考えています。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"提案","question":"ぜひよろしくお願いいたします。先ほども区民まつりで周知の事業をやっているというお話でしたけれども、この盆踊りというのを活かすというのも一つの──また余り言い過ぎてしまうとあれか、またそういったことも提案していきたいと考えています。これは個別にいきたいと思います。失礼しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"伊藤委員","kind":"確認","question":"文化プログラムの確認なのですけれども、これは例えば品川区だったら品川区のいろいろな団体があって、それを品川区で選んでオリンピック委員会に確認をとって、それで承認を得て実際に行うという仕組みなのでしょう。その文化プログラムの承認の仕組みをまずお伺いしたいのですが。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"その申請ができるところはさまざまな自治体だけでなく団体ができるのだと思うのですけれども、文化プログラムに認定されるに当たりましては、企業色があってはならないですとかいろいろな部分で制約があるのだと考えられているところです。","id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうすると、ある意味商業ベースでもないし、非常に文化の質の高いものを求められているというイメージでいいのかな。それはもちろんすばらしいと思う。だから、それを今の時点で絞り込んでいくというのはちょっと危険ではないかな。むしろ、そういう仕組みにのっとった上で、幅広い観点でプログラムを検討した上で、よりすばらしいプログラムを作っていくべきだと思うのですが、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ですので、区といたしましても、この正規の文化プログラムに認定されるされないにかかわらず、やはり既に文化芸術については率先してやっておりますので、その取り組みを着実に実施し、新たな視点もオリンピック・パラリンピックということで取り入れながら。","id":"exchange-041"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうしたら、文化プログラムという公のものについてはそういう正式な手続きが必要であって、それ以外でもさまざまな振り幅でできるということからすれば、それはそういう部分で、それこそいろいろな物事を取り上げていったほうが、当然私はいいと思うわけですから、それはそういうことを進めていっていただきたいということをお願いをしておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"南委員","kind":"提案","question":"関連してなのですけれども、２０万件あったという過去のロンドンの実態を見て、いろいろな文化プログラムが提案されて実施されたというふうなところの説明を伺って、またこの中で品川区としてきちんと公式に文化プログラムとして提案することは、幾つぐらいを想定しているのか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区としてどういった提案を上げていくかですが、何分にもまだどのように認定、申請をするのかというような手順が全く示されてございませんので、今ある区のイベント。","id":"exchange-043"},{"speaker":"南委員","kind":"提案","question":"私は今の質問でちょっと確認したかったのは、１個に絞らなければいけないのかどうなのかというところも一つあったので、そこも教えていただきたいと思うのです。いろいろな具体的なご提案も今ありましたけれども、取り組むに当たって私はやはり区民参加型とさっきおっしゃっていたそれはそれとして本当に歓迎をしていきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"先ほども申し上げましたが、申請に当たっての考え方等が示されていないのでなかなか難しいとは思いますが、１個に絞らなければならないということはまずはあり得ないとこちらとしては考えてあります。","id":"exchange-044"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど伊藤委員からもありましたように、本当に幅広い観点でまず考えていただきたいというのは同じ意見でありまして、ちょっと確認なのですけれども、先ほど課長の答弁の中で、今既存で行われている文化芸術の部分をそのまま何か、この文化プログラムに引っつけていくようなニュアンスでとってしまったのですけれども、その確認と。","respondent":"鈴木文化観光課長","answer":"２点目の他区との連携ですが、文化に関するプログラム、取り組みについて、当然広域的なものとか連携するものがあるようであれば、それはしっかり取り組みたいと考えております。","id":"exchange-045"},{"speaker":"いながわ委員","kind":"質問・要望","question":"何かそういうイメージが非常に、みんな口を閉ざして、真似られてしまったらどうしようとか、そういうのもあると思うので、そういうのがどういう形で情報収集するかは別なのですが、そこはしっかりうまく聞き取って品川独自のものをつくっていただきたいというのが。それは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"１点だけ。８月５日から今度リオデジャネイロのオリンピックが始まって、何人かの方に行っていただく中で、やはりどうしても報道されるのはスポーツ部門が日本では報道されていくと思うのですよね。ぜひその辺のところを参考にしていただいて活用していただくとともに、この委員会の中でもその辺の報告をしていただきたいと思うのですが、いかがですか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"リオ大会を契機といたしまして、東京都が考えていることがあります。具体的には、東京都の上野の公園とそれから国営昭和記念公園でライブサイト、パブリックビューイングをすると聞いてあります。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ちょっとごめんなさい、意味が違うのだけれども。こっちで開くのではなくて、現地に行く方がその現場をしっかり見てきたくださいと、そっちの。我々、国民の人が見るのではなくて、行く人に対してのことのチェックなので、そこはもう一回。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"大変失礼いたしました。今回リオの視察に行ってまいりますので、当然文化プログラム、イベント関係についてもこちらのほうとしてはしっかり視察していきたいという項目に挙がっておりますので、責任をもってきちんと確認してまいります。","id":"exchange-048"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今も出ました８月５日からの区の職員と議会の委員２人合わせて７人の派遣について、改めて議会運営委員会で議論したときに示された資料が余り詳しいものがないために、あれから２カ月近くたつ中で新たに具体的な、例えば数字だとか価格だとか金額だとか、わかったものがあればぜひ示していただいてはっきりさせていかないと、公の自治体のお金の執行と議員がそこにかかわるという点では、やはり区民の信頼の。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"南委員","kind":"質問","question":"ちょっと待って。ちょっとこの質問をしたいと思っているので、それはやらせていただけるかどうか。委員長が今おっしゃった後のこの日程のところ、これからの予定のところで、その辺がよくわからないので。そちらを聞いてからちょっと判断をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"南委員","kind":"提案","question":"それで、もう一つ大事な税金の使い方という点では、やはりチケット代が幾らなのか、宿泊費が幾らなのか、大枠で１人当たり３００万円という、そういう提案でしかないわけですね。そういう提案でいいのかどうかというのがあるわけです。そういう趣旨は理解していただいて、ぜひこの場で質問をさせていただきたいと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"委員長はそうおっしゃったのですけれども、さっきも申し上げたように、ではこの委員会で委員からそういう申し入れがあったので、次回の議運で取り上げてほしい、議題にしてほしいというふうに委員長のほうで判断していただいて、そういうふうに申し入れをしていただけるならば、私はこの場は質問しないで議運に預けたいと思っていますけれども、そもそも議運の議題だというふうにはならないと思うから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"ぜひ、私は委員長のほうから議運の委員長に、また議長にそういう旨をやはりお伝えいただいて、議題として取り上げてほしいと計らっていただきたいと思います。やはりその趣旨というのは、先ほど来申し上げておりますように、今税金の使い方に対して非常に……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"南委員","kind":"意見","question":"議会で取り上げて……。ちょっと言わせてください。議会で取り上げていることを全てのマスコミが取り上げているわけですよ。それでここがこんな言い足りないとか、ここがこんなにまだ解明されていないとかというふうにもう連日やっているぐらいに関心がある。それと同じような状況にするわけにはいかないと私は思っているのですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"だから、明らかにされていない部分はぜひ明らかにするべきだ。その上で派遣をさせていくと、そういうことが望ましいと思うので、それで取り上げているわけです。その辺の趣旨はちょっと理解していただきたいと思います。その辺についてどう思っているのか、ちょっと委員長の見解を伺いたいと思います。","respondent":"渡辺委員長","answer":"見解は先ほどのように、取り扱いについては限界がありますので、今お話しされたことは伝えることはしっかりとお伝えします。判断はまた違った場面になりますので。そのとおりです。よろしいでしょうか。繰り返しになりますので。見解は一緒です。","id":"exchange-055"},{"speaker":"南委員","kind":"意見","question":"繰り返しと今発言がありましたので、ちょっとマイクをとりましたけれども、同じことを聞いてないですよ。そういう税金のわからないまま派遣をして、そして区民の皆さんから、舛添知事が今受けているようなああいう問題に発展させるわけにはいかないでしょうと思うわけです。その点について、委員長はどういう見解を持っているのかということを……。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"南委員","kind":"質問","question":"区民の皆さんの理解が得られないというふうに私は思うので、では理解が得られるのか、今の段階で。行くということについて解明もない中で、行くということについて理解していただけると思っておられるのか、委員長として。派遣される議員としてもそういうふうに思っているのか。その辺、では教えてくださいということを聞いたわけですから、違いますよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"南委員","kind":"意見","question":"答弁がなかったというふうに理解します。委員長の見解はなかったということでね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"南委員","kind":"確認","question":"最初の問題をしっかりお願いします。確認しますけれども、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/969591?Template=document&Id=6494#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":58532,"voices":181}},{"id":"h28-20160610-10","meetingId":"h28-cm06","date":"2016年6月10日","dateIso":"2016-06-10","committee":"議会運営委員会","time":"午後１時００分～午後２時３３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","topics":[{"id":"topic-01","title":"議会報告会（５月３１日）","agenda":"議会報告会（５月３１日）","exchanges":[{"speaker":"たけうち副委員長","kind":"質問","question":"資料３２にまとめしていますが、これに沿いましてご報告します。２、実施会場につきましては、ここにありますとおり、きゅりあん７階イベントホール。それから、回収させていただいた質問表は３３枚ということでございました。６、その他で、寄せられた質問のうち、質疑応答での未回答分、またアンケートの集計結果については、後日ホームページで掲載するということです。大変にありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"今、報告漏れがあったかもしれませんけれども、報告書もまとめる方向で、これもホームページに出すのが、遅くても今月いっぱい、なるべく早い段階で出すように、今、分科会のほうでやっておりますので、ご覧いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"議会改革検討会中間報告項目の実施","agenda":"議会改革検討会中間報告項目の実施","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ひとつだけ、今後について、一定程度まとまってからというお話が、後半に少しありましたけれども、私も情報発信分科会にいるものですから、自分のことだけで恐縮ですけれども、中間のまとめにおいて、今後、全議員の議案の賛否や、議案や委員会資料の掲載や、本会議録のＰＤＦのことは今回はあれですけれども、早期掲載を調整しながら順次進めていくとありますけれども。","respondent":"原区議会事務局長","answer":"今回、中間報告を５月１７日にいただいて、その後実施できるもの、これは継続して実施できるという前提にしておきませんと、たまたま１回はできるけれども、その後はできないというのでは困りますので、長期的に、安定的に事務運用ができる。","id":"exchange-003"}]},{"id":"topic-03","title":"議員派遣依頼","agenda":"議員派遣依頼","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"委員長のご意見、また、ほかの委員のご意見もいろいろ伺いながら、ここは皆さんの意見も伺いながら進んでいますけれども、今は事務局長ですけれども、区が実施したい理由や同行願いたい理由や、内容や経費についての説明を受けて審議をする、そういう丁寧な進め方をするのがよろしいのではないかと思いますけれども、いかかでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"鈴木（真）委員長","kind":"質問","question":"質疑については、当然、この場でやっていただくのがこの委員会だと思います。詳細につきましては、これだけの資料をいただいて、事務局長から説明いただいたので、行政側の説明ということは委員長としては考えていませんでしたので、それについて皆さんのご意見をお伺いしたいと思います。急な話ですが、各会派のご意見をいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"あくまで友好都市で、親善訪問団というのはわかります。代表ならば、私は議長お一人でいいのではないかと思います。やはり自重するところはして、議会の代表なら一人だけ行っていただくという形で、やはり経費節減をして、こういう友好都市、親善訪問団を派遣して、今後につなげていくという姿勢が求められていると思いますし、そうすべきだと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"沢田委員","kind":"意見","question":"今、話が二つあって、理事者を呼ぶのか呼ばないのかというその話は、そのことに関しては、今、事務局長からも説明がありましたし、詳細に日程も出ているということで、その内容については、今まで２５周年ということで、公式訪問団ということで説明もありましたので、この場で質疑は、ある部分はそれで結構なのではないかと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん、今、事務局長が区から聞いた話を報告いただいた。今、須貝委員から意見がありましたけれども、まず議論の前提として、委員会としてきちんと説明を受けるというのが、進め方として大事ではないかと、私は思うのですけれども、どうでしょうか。そんなに間違った筋ではないと思っているのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木（真）委員長","kind":"質問","question":"委員長としては、先ほどお話をさせていただいたとおりですが、各会派のご意見を伺うということですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"あべ委員","kind":"意見","question":"今回の訪問は、一応窓口は区長部局なので、やりとりは行われていますが、過去の経緯から見ても、また区長が行くのに議会がついていくというよりも、区と区議会でお招きいただいているくらいのニュアンスのほうが近いのではないかと考えています。民主主義国でありますし、議会は区民の代表として一定の敬意を持ってお招きいただいているものと受けとめております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"意見だけです。１８日はサン・ピエル大聖堂への移動、合同礼拝等々、なぜこれが公式事業ということなのか、その理由をやはり区長部局から聞く必要があると、私は思うし、この同行を求める理由、説明を受けることが大事なのではないかと思いますし、それについての質疑をやらなければ、議員派遣についての議論が成り立たないのではないかと、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"意見","question":"先ほどからいろいろご意見もありますけれども、議会としては、この２５年間スイスとの友好を深めていく、深めてきたという事実があるということ。非常に重要な行事だと考えています。先ほど、局長からのご説明も受けまして、また日程についても詳細なものをいただいておりますので、あえてここで担当課長を招いて説明を受ける必要は、我々としてはないと考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問・要望","question":"日程をつくっているのは先方なのかどうかということを１点させていただきたい。それから、費用ですけれども、現地宿泊費は特に入っていないようですけれども、これもご招待ということで、先方持ちという解釈をしていいのでしょうか、それを教えていただきたいと思います。お出でいただいていて、こちらは行かないというのは、公式のお付き合いとしてはかなり失礼なことではないかと思います。","respondent":"原区議会事務局長","answer":"その間、５周年ごとのものとあわせて、青少年のホームステイということでの品川区とジュネーヴ市との相互の行き来があったり、実際も継続しているです。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"やはりこの経済情勢、区民生活が厳しい中で、大切な行事だからどうしてもやると区長のほうでお考えならば、はっきり品川区の広報にきちんと載せて、こういうふうにやりますけれども、皆さんのお金を使わせていただきますけれども、こういう訪問団で、こういう予算でやりますと、きちんと堂々と提示して行くべきではないですか。それを、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"こういうのは触れないほうがいいのでしょうか、わからないけれども。そういうのは、事務局長が受けた話というよりも、実際に携わっている担当者からの説明を、まず理由を聞いて議論の前提にするのかと、少し思っただけですけれども、質問としては、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々としては、ジュネーヴ市との友好関係は継続していくべきだし、押し進めていくべきだと思って、話をします。それはそれで費用をなるべく押さえようという、こちらサイドの話はあったけれども、これは全て決まり事の中に、しっかり皆さんに提示をしてやってきているというのであれば、私はこれで素直に一緒になって友好を行っていくということで、話を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（真）委員長","kind":"意見","question":"今、ご意見をいただいた中で、理事者を呼んで説明を受けるというのは、多数の方が、それは必要はないということだと、委員長としては、そのような判断をします。派遣につきまして、さまざまなご意見がございましたが、この場で意見をまとめるか、持ち帰るか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"本日、こういう話が出たので、１回持ち帰らせていただいて、会派で話したいと思います。それから、ひとつ誤解を招かれると困るのですが、派遣に反対しているのではなくて、どういうのだろうか、これでいいのだろうかということを言っているので、議長が行くことに関しては、私としては何も反対するものではありません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]},{"id":"topic-04","title":"その他に入ります。その他の(3)からやりたいと思います。(3)道路大会の会場変更に伴う参加者の減","agenda":"その他に入ります。その他の(3)からやりたいと思います。(3)道路大会の会場変更に伴う参加者の減","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"(3)の道路大会の会場変更に伴う参加者の件について、今、確認をしてほしいというお話でしたけれども、今回の事態を機に、建設委員会が参加するという申し合わせ確認事項だったか、ルールそのものの議論を、本日ではなくて、次回以降でも、そろそろやるべきではないかと思います。委員会運営については、委員長にお任せいたしますけれども、投げかけたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはそれで、砂防会館に変わるからいい。今の申し合わせ確認事項のことは言っていいけれども、ここは会場のことで減ること自体の報告であって、ご了解いただきたいとか、時間内のときに当日に建設委員会をやってもいいわけですから、これはどうですかとか、それは建設委員長権限なんですよ。そこに入ること自体は、私はおかしいと思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-05","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"沢田委員","kind":"提案","question":"品川区議会自民党・子ども未来としては８点の提案をします。一つ目がオリンピック・パラリンピック開催へ向けた環境整備等に関する要望ということで４項目。二つ目、水辺利活用の推進に関する要望ということで４点です。二点間不定期航路を認可すること。三つ目が羽田空港機能強化についての要望ということで、３点。四つ目、待機児童対策についての要望です。次、高齢者施設整備に関する要望、３点です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"つる委員","kind":"提案","question":"公明党は、基本的には昨年度に提出させていただいた提案件数、提案については、基本的には同じですが、要望内容について若干の修正をしていますので、改めて出します。１点目、待機児童解消に関する要望。次に、高齢者施設に関する要望ということで、要望内容、団塊の世代が７５歳以上になる２０２５年に向けて、都市部で逼迫すると予想される高齢者施設を計画的に整備するための支援を次のとおり要望する。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"待機児童解消に向けた子育て支援の強化に関する要望ということで、公立認可保育園の増設や国庫補助、保育士の処遇改善、公私格差是正などを求めたいということです。次に、国民健康保険の収納率向上のための差し押さえの交付金制度の廃止を求める要望ということで、東京都が行っている成績別交付算定表での差し押さえ件数はいかがなものかということで、やめるように要望したいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"あべ委員","kind":"提案","question":"民進党・無所属クラブからは、一つは子育て家庭の貧困への対応策の強化を求めるものです。あるいは、給付型奨学金の拡大、そしてまた、子どもたちへの民間の支援活動の支援を行うことなども要望しております。その他住民要望に対応すること、そういうことを提案しています。そしてまた、保育園利用家庭以外の在宅子育て家庭への支援も強化することを提案しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"中塚委員","kind":"提案","question":"若干それぞれの提案について、お考えを伺いたいと思うのですけれども、オリンピック・パラリンピックについて、自・未と公明から、観光客の増加に伴って交通インフラの整備促進やアクセス強化に向けた交通情報インフラとあるのですけれども、オリンピック・パラリンピックで観光客が増えて、羽田に必要な準備を整える、これは当然必要なことだと思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"意見","question":"基本的には、りんかい線の羽田線も２０２０年までにはできない。それから、品川新駅の開発も２０２０年にできなくて、２０２５年、リニアが２０２８年ということもあるので、それに向けて準備をしていくということもあります。観光客も今３,０００万人、または４,０００万人に向けてという話もある。オリンピック・パラリンピック後、レガシーにならないような開発をしっかり、どういう形でやっていくのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"つる委員","kind":"質問・要望","question":"当然、それはあくまでもオリンピック・パラリンピックが契機になりますから、それを過ぎた後、表現はともあれ、当然、区民の方、そして品川区を訪れていただく観光客、またさまざまな方を含めて、より快適な交通環境、そして情報の環境を整備していく、このことが区内、区外かかわらず、必要な整備だろうということで、オリンピック・パラリンピックの要望の中に位置づけたということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"たけうち副委員長","kind":"質問・要望","question":"レガシーというお話があったのですが、レガシーは品川区のレガシーもあれば、各区によって残したいレガシーがあると思うのです。東京都としてもあるかもしれないけれども、東京都と国に要望しているのですから、そういう意味では、レガシー云々と言いましても、オリンピック・パラリンピックでやっていただければいいので、そういった財源だとか、インフラ整備というものについて要望しているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"質問","question":"レガシーとは、別にハードだけではないのです、ソフトの部分、考え方も残るものがレガシーなので、先ほどの質問の意味がよくわからなかったのですけれども、そういう意味では、これを契機にしてバリアフリーの整備を品川区で進めていって、区民の意識が高まるということも一つのレガシーでもありますので、そういう意味でのお問い合わせだったのかと、先ほどの質問の趣旨がよくわからなかったのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"今は決定案という段階ですから。ですので、要望するときに、そこだけ確認をしておきたい。もちろんほかに、丁寧な説明とか、不安の払拭とか、やはり対策はどうなっているのか、きちんと示していただく、国の考えをきちんと示してくださいということ、それは別にいいのですけれども、決定が前提としての中身になってしまうと、それは受け入れがたいので、その辺だけお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問・要望","question":"一応、これは各会派からの要望であって、ほかの会派がどんな要望をしているのか、聞きたいという話ではないです。ただ、実際に項目を出すことになれば、その中身についてはまた議論があっていいかと思いますけれども。それからあと１点です、すみません、うちから今回出していないのですけれども、児童相談所の設置に関する要望、これも重視してほしいことであるので、申し添えておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ここで数がどうとかではなくて、例えばほかの区では、この区にとっては大切だと思うことを、１区でぽんと出してくる区もあるわけですので、それはそれでも品川区の主張としてはいいと思うので、そういうものも含めて議長にお考えいただきたい。そこら辺は、議長にお任せするので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"中塚委員","kind":"提案","question":"もちろん議長がまとめるということでいいのですけれども、一つだけ意見ですが、保育園のところで、既存施設の定員拡大というのはちょっとだめだなと思うのと、逆に民進党が出された子育て家庭への貧困対策、これは１会派ではあるけれども、とても大事な提案だと思うし、品川区だけではなくて都心はどこも抱えているテーマだと思うので、多い意見をまとめるというのも一つの視点だけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/457598?Template=document&Id=5184#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":28348,"voices":72}},{"id":"h28-20160622-10","meetingId":"h28-cm06","date":"2016年6月22日","dateIso":"2016-06-22","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","topics":[{"id":"topic-01","title":"平成２８年第２回定例会","agenda":"平成２８年第２回定例会","exchanges":[{"speaker":"鈴木（真）委員長","kind":"提案","question":"ただいま説明のありました都知事選挙の経費を計上する補正予算の追加提案につきましては、定例会２日目の６月２４日の本会議での上程となります。なお、本案に対する採決方法を確認するため、本会議に先立ち、２８日の午後０時３０分から議会運営委員会を開催することになりますので、よろしくお願いいたします。以上で、本件を終了いたします。","respondent":"原区議会事務局長","answer":"昼の休憩中に常任・議運・特別委員会の委員長会を開催する予定です。第２回定例会から第３回定例会までの閉会中の議会運営について確認いただくというものです。日程第２から日程第２４までの２３件につきまして、一括して副区長より説明をいただく予定です。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"質疑というか意見なのですけれども、資料Ｎｏ.６の陳情についてですけれども、先ほどご説明があったように、いわゆるできるという規定なのですね。当面は検討会や分科会がありますので、そこでの議論をまず踏まえていただけたらと思いますので、意見だけ述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"議員派遣依頼","agenda":"議員派遣依頼","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"持ち帰りの結果で若干の質問をしたいと思うのですけれども、まず、持ち帰りの結果ですけれども、前回の議運で区長宛てに招待があった関係から、区長部局の出席と説明と質疑を求めたのですけれども、かなわなかったのは残念だと思います。伺いたいのは、区長部局や議会の人数は、どのような考え方で決まったのか、人数や経費の抑制という視点はなかったのか、そこを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"あべ委員","kind":"意見","question":"私どもの会派としては、２５年間、ジュネーヴ市との関係に鑑み、派遣には賛成ですし、内容としても、特に過大なものではないかと考えておりますが、まだ工夫の余地があれば、今後も経費はできるだけ削減しながらということで賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"前回もお話ししたのですが、今、東京都議会でもリオの議員派遣２７名、大問題になっています。こういうジュネーヴに、友好都市に議員を派遣するということで、意義は交流ということで、私はいいと思うのですが、ただ、あくまで議員の代表、議長が１人行けばいい話ですし、今、国民生活が大変な中、経済が大変な中、果たして派遣するということはどうなのかと、うちの会派では反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"いや、議長は議会の代表として、１人行けばいいのではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"簡単に、すみません。資料ですけれども、今回改めて提出されたということで、担当の課がつくったということですけれども、やはりその点を見ても、出席を求めて説明を受けて質疑を行うというのが、やはり当然の対応なのかと改めて思いました。このバスというのは何人乗りなのか伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"ある意味、局長ですから答えられないというのも一定そうかなと、やはり担当する課や担当する部が出席をして説明を受けるということが大事なのかと改めて思いました。舛添前都知事の強悪な海外視察についても、どうして都民、区民が声を上げたのかというこのことにも真摯に受けとめるべきだと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"リオの派遣に関してなのですけれども、私どもとしては、オリンピックという大きな国費を投入するプロジェクトに、事前の準備として現地を見てくるということは、とても価値があることだと思ってはいます。これまでも思っていますし、今も思っています。これは要望と言えば要望です。何かありましたら、ご意見も伺いたいと思います。","respondent":"原区議会事務局長","answer":"そういう中で、派遣ということで行くわけですので、まず１つは、事前説明会というところで、治安が悪いと言われておりますけれども、そういった中でどういうところに注意しなくてはいけないのか。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/457598?Template=document&Id=5186#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":12431,"voices":58}},{"id":"h28-20160627-6","meetingId":"h28-cm06","date":"2016年6月27日","dateIso":"2016-06-27","committee":"区民委員会","time":"午前１０時００分～午前１１時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、(1)第５７号議案、品川区立体育館条例の一部を改正する条例","agenda":"はじめに、(1)第５７号議案、品川区立体育館条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"今回の変更を考えるきっかけになった具体的な事例というのは何かあるのか。いろいろ伺いますと、現在９割がスポーツ協会や連盟が利用しているということですけれども、今回の変更で取りにくくなることにはならないのか。全面利用が増えると、残りの１割を含めて施設が取りにくくなってしまうのが心配なのですけれども、この点について、どう対応したいと思っているのか、お考えを伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"今回、営利の目的ということにつきましても、基本的には、利用については４カ月前、１カ月前〔同日後刻に「２カ月前」と答弁訂正あり〕ということを変更する予定はございません。ただ、実際にどうしても区民の皆様に見せてあげなければいけないといったものが必ずあると思います。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"私自身も振り返りますと、小学校の高学年だったでしょうか。そうなってくると、今あいているところに入ってくるわけですから、従来の利用団体や練習や試合や大会が困難になるほど、先ほどはないという話もありましたけれども、実際にどういう大会が想定されるのか、また従来の練習や大会との兼ね合いというのはどういうふうに調整をつけていくのか、その点についても伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"従来の部分で、取りにくくなるかどうかです。先ほど、会場の利用の仕方につきましては、区民が４カ月前、区外の方が１カ月前〔同日後刻に「２カ月前」と答弁訂正あり〕ということでご説明をさせていただいたところです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"どういう想定がされるのかと少し伺ったのですけれども、今日の資料にも、物品販売を目的としたもの、スポーツ・レクリエーション以外を目的にしたもの、以下を除くということです。実態に応じてというところになるのであれば、歯どめの基準というのでしょうか。もちろん考え方は条文に示されてはいるのですけれども、実際の実例なども踏まえて、ここをどのように考えているのか、伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"ご相談の際に、今、委員がおっしゃいましたスポンサーの色が濃くなるようなもので、実際にスポーツを純粋に楽しむものではなく、営利が主になってきてしまうものではないかといったものについては、スポーツ協会で実際に話して。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"地域スポーツにさまざまかかわっている方にお話を伺うと、はじめは人数が少なかったり、私が子どものころのように、子どもが増えていったときにチームも増えていったり、今は当時に比べれば減ってきたり、いろいろな苦労をしながら、地域とともに広げてきたと思うのです。どうしても急な変更というものはあり得るだけに、あらかじめどういう対応をするのか、そこについてのご説明も伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"どうしても区役所の体育館ですので、当然、スポーツ専門ではありますけれども、急な事情で使えないこともあります。そういったものに対しては、事前の協議ということで、営利目的で利用される方については、一筆取り交わしをしたいということも考えているところです。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"後半のほうなのですけれども、チケットの売り上げが伴うだけに、そこについての取扱いが具体的にどうなるのかというところをご説明いただきたいと思います。会場については、使用料を全額返すのはそうかなとは思うのですけれども、実際にどのようにするのかなというところをご説明いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"今の関連なのですけれども、予定していて、何かしらの理由で使用できなくなる場合。今、選挙の話が出ましたけれども、可能性としては、選挙以外にほかにあるのですか。","respondent":"安藤文化スポーツ振興部長","answer":"前の経験上ですと、選挙というものが、まず第一に考えられる。不慮の地震で何かが使えなくなったとか、そういうものはあったと思います。そのような事例はほとんどない。主催者側の何かの都合で大会が開けなくなったとか、そういうことはありました。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"この条例改正について、方向性はすごくいいと思います。それで聞きたいのは、営利が認められるということで、集客が１つの注目になると思うのです。現在のアリーナを使うのだと思うのですけれども、何か変える意志があるのか。総合体育館も戸越体育館もそんなに大きくないですけれども、スポーツで使う床面積に集客してもいいのか。その辺の規定がどうなっているのか。集客について教えてください。","respondent":"池田スポーツ推進課長","answer":"現在の主競技場、総合体育館、戸越体育館ですけれども、そこで大きな改造というところについては、現在のところは特に考えてはおりません。実際に観客席についてですけれども、総合体育館については、およそ３００席、戸越体育館は１００席の観客の固定の席があるところです。","id":"exchange-007"},{"speaker":"いながわ委員","kind":"確認","question":"先ほどの関連なのですけれども、一度聞きたかったのは、貸してくださいと契約するではないですか。誓約書というか、何かを明示して、確認書にサインをいただくなど、そういうことをやるかどうかを聞きたかった。それが１点です。先ほど広告の話がいろいろあったと思うのです。そこは、今後しっかり考えていかないといけないのではないかなと思うのですけれども、いかがですか。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"委員の今おっしゃったことですけれども、広告の大きさなり、そういったものについては、これから検討したいと思ってあります。営利目的ができる箇所ですけれども、体育館全てができるというところではございません。こちらも、今言われた中身のことについてははっきり言っていますし、今後、営利ということになりますから、そこら辺はこちらも十分考えて、そういうものを申請の段階で相手に伝えて、説明責任を果たしていきたい。","id":"exchange-008"},{"speaker":"いながわ委員","kind":"確認","question":"今のニュアンスだと、それはやってはだめで、中だけでやってくださいというイメージだったのです。その確認をお願いします。基本は、地域も含めてスポーツを盛り上げていかなければいけないわけであって、歩道のぎりぎりのところに旗を立てたり、何対何の試合をやりますというのは、通常はあってもいいのかなと思うのですけれども、それはだめということですか。先ほど、中だけでという話だった。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"ポスター的な広告、応援するものについては、当然、体育館の利用ということで行いますので、体育館に設置している部分についてはご協力できると思うのですけれども、私の誤解が生じておりまして、営利のためののぼりということであれば。営利の目的にも示したように、スポーツのパフォーマンスを区民の方により見てもらいたいというのが１つの趣旨です。","id":"exchange-009"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひルールづくりをしていただいて、おそらくスポンサー企業は、自分の名前が出なかったらスポンサーをやっている意味も全くないと思うので、その辺は外だろうが、中だろうが、社会通念上、普通、のぼり旗とか、どこかのスポーツドリンクとか、そういうものは別にあってもいいのではないかなと思うのです。それは、しっかりルールづくりをしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、ほかの委員からも出ていたように、細かいことは出てくると思うのです。これを少し伺いたいのですけれども、オリンピック・パラリンピックの担当課としては、まだ条例は決まっていないわけで、これからですけれども、これが可決になったときに、すごくありがたいという思いがあるのか。具体例は出ないかもしれないのですけれども、ぜひ思いを伺いたいのです。その辺についてはいかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"今回の条例を改正することによって、２つの体育館がより区民にとって身近になり、大きな大会やイベントが開かれる可能性をたくさん秘めたことにつながるかと考えています。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"今、夢があるような答弁をいただいたのです。もとに戻るのですけれども、いろいろある中で、金銭的なトラブルがあったら、やはりよくない。ただ貸しているだけでは済まないと思うので、最初に戻るのですけれども、厳密なルールづくりはきっちり、今日の条例はそこまでないですけれども、条例が可決された後に、その辺はきっちりつくっていただきたいと思うのです。改めて、その辺に関してはいかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"今、委員からご意見がございましたように、私どもでは営利的な利用を認めてまいりますので、こういったより細かなルールにつきましては文章化して、きっちりと１０月１日の施行までには必ずや行いますので、よろしくお願いいたします。","id":"exchange-012"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"今の流れに続くのですけれども、大田区の総合体育館でワタナベボクシングジムが年末に公式試合を毎年やっているのです。だから、それはぜひ検討していただきたいのと、ほかの自治体の成功例を研究していただいて、今あった契約のあり方や、万が一の選挙のときの対応なり、当然、ほかの自治体の総合体育館もやっていると思うのです。そういうことを検討すべきだと思うのですが、いかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"いろいろなルールづくりにつきましても、他区の成功例がありますので、そういったことを参考にしながら、私ども、１０月１日に施行するまでにはきちんとできるようにしてまいりますので、よろしくお願いいたします。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問・要望","question":"確認ですが、まず施行日が１０月１日になっている。この１０月１日にしたという根拠をまず教えていただきたい。区民への周知ということで確認なのです。そこら辺の施行の期日と、これから営利が入ってくる予定があるかどうかというところの確認。ここは、年にどれぐらいやっていて、そういうところで営利団体の方は調整をするのだというお話ですけれども、もう少しそこら辺を具体的に教えてください。","respondent":"池田スポーツ推進課長、安藤文化スポーツ振興部長","answer":"これから営利のご利用のお申込みについては、今年度内でのお申込みは、現在入っておらず、なかなか厳しいところではあるかと考えています。私から少し補足をします。先ほどの調整会議というのは、この会議をご説明しないとわからないと思います。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問・要望","question":"ご説明ありがとうございました。そうすると、調整会議は年１回だということで、ごめんなさい、私の理解が違っていたらご指摘いただきたいのです。ごめんなさい。もう一回、確認です。通常、使っていらっしゃる区民の方への影響がないというところで、今回の使用は大変によろしいことだと思うので、なるべく区民の方への影響がないように、両方の使い勝手をよくしていただくための確認なのです。お願いします。","respondent":"池田スポーツ推進課長","answer":"営利団体の方につきましては、別途スポーツ協会に問い合わせをしていただいて、あいている状況を確認した上で、お申込みできるかどうかという形になってまいります。区民の方の利便性については、４カ月前からということで、一番の優先順位という形になってあります。","id":"exchange-015"},{"speaker":"田中委員","kind":"確認","question":"今、部長は区外の方の予約は２カ月前と。１カ月前の間違いですか。先ほど１カ月前と聞いたような気がします。でも、２カ月前と今おっしゃっていたなと思ったので、そこの確認です。トップレベルの方たちが利用できる施設ですかということを聞かせてください。","respondent":"池田スポーツ推進課長","answer":"申しわけございません。今、私の答弁を訂正します。抽選の部分については２カ月前ということです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日もいろいろ議論になったところですので、ぜひ施行前に委員会に報告をしていただきたいと要望しておきます。今回の改正は、特に子どもたちにとって一流のスポーツに触れる機会が増えるということはよいことだと思いますので、賛成いたしますが、歯どめとルール化については、強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"田中委員","kind":"意見","question":"今、中塚委員がおっしゃったように、営利化に対してのルールづくりをしっかりしてほしいことと、今使っている方たちが阻害されないように、そこら辺を徹底していただけるということであれば賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"}]},{"id":"topic-02","title":"第５２号議案、平成２８年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第５２号議案、平成２８年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"詳しく教えてもらいたいのですけれども、上限額というのは、どういうことなのか。上限額の意味がわからないので教えてもらいたい。１０分の１０は国からということで、９,３００万円余が歳入で入って、歳出が９,３００万円余で、この負担金ということで、多分そのまま右から左に行くと思うのです。この負担金というのは、今まで前段階で合計どれぐらいになるのかということを教えていただきたい。","respondent":"提坂戸籍住民課長","answer":"負担金というのは、平成２７年度の実績が出ているのですけれども、１億２７４万１,０００円という金額が負担額ということで出ております。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"上限額が示されたということは、これ以上、区から出ているお金ではなくて、１０分の１０が国なので何も痛まないと思うのです。とは言いながらも、税金ですから、そこはしっかりやっていただきたいというのもある。パーセンテージでもいいです。本来、カードをつくられるべき人数、例えば３０万人、品川区の人口全部だと思うのですけれども、その何％までは発行できているということがわかれば教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１０分の１０が国から出て、品川区がいくら頑張っても、やっているのはここの機構がやっているわけであって、身分証明書がない人が積極的にやったはいいけれども、ずっと待たされているというのはあってはいけない。手元に住基カードが届いているのがまだ２６％というのは、本当に少ないと思うのです。今年の９月でしたか。ちゃんと強く言えるかどうかという話です。","respondent":"提坂戸籍住民課長","answer":"コンビニの交付を９月２０日にスタートを予定しているのですけれども、９月の段階での交付を７０％強を目指しています。７０％です。〔「今、２６％です。頑張ってください。まだ足りないと思いますので、一応予約が入ればということで、頑張ってまいります。よろしくお願いします。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"今のやりとりを聞いていましても、システム障害が起きたり、区の作業が遅れていたり、体制を整え直したりと、ごたごた感を感じるのです。こういった補正は、この間続いておりますけれども、一体どういうことになっているのかというのを、改めて質問したいと思います。ということは、当初予算とは何だったのか。そこも直接補正を組んだ理由、事情ですけれども、そこも伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"当初の予算額のご説明になります。当初、マイナンバーの交付事務が始まる際、国で交付枚数を平成２７年度１,０００万枚、平成２８年度５００万枚ということで想定しまして、国全体の予算額を算出しまして、それに応じて全国の自治体の人口比で金額を出しております。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"正直、わからなかったです。それと、システム障害が起きたという先ほどのやりとりがありましたけれども、具体的にどういう障害だったのか。そこの理由は何か。今の説明の中に入っていたのかもしれませんけれども、よくわからなかったので、そこだけ伺いたいと思います。","respondent":"提坂戸籍住民課長、堀越地域振興部長","answer":"そのお客様に対しては、後日郵送でカードを送らせていただいて、対応させていただいています。軽微なというか、小さなシステム障害というのも、数え切れないほど頻繁に起こったと聞いてあります。そのときには、実際にカードを申請しに窓口に来られている方に対しては、課長からご答弁申し上げたような対応をさせていただきました。その回数が、たしか１月から３月までの間で９回あったということ。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長の答弁でシステムの話が出て、今回は１０分の１０ですから、国からというのはわかるのです。それでも、やはり税金ですよね。これがずっと続いていってしまうといけないと思うのですけれども、その辺についていかがですか。今の時点でいいですから、その辺についてお答えいただきたい。それと、生活安全担当課長にお伺いしたいのです。これは確認でいいのですけれども、教えていただけますか。","respondent":"提坂戸籍住民課長、濱田生活安全担当課長","answer":"個人情報に関するトラブル、事故は、今のところございません。個人情報漏洩のためにいろいろな対策を打っておりまして、平成２６年度にも区の特定個人情報保護評価を行いまして、内閣府にも報告したところです。マイナンバーに関する詐欺についてですが、品川区は現在ゼロ件と聞いております。","id":"exchange-024"},{"speaker":"中塚委員","kind":"意見","question":"反対です。一言理由を述べます。今のやりとりでも、交付できない、アクセスできない、数え切れないぐらいのシステム障害、この状況で個人情報が漏洩したら、一体どうするのかと思います。とてもマイナンバーを進める状況でないと思いますので、今からでも一旦立ちどまって中止すべきだと思いますので、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"いながわ委員","kind":"質問・要望","question":"基本的に賛成なのですけれども、先ほど質問させていただいたとおり、速やかに交付ができるように、しっかりとやっていただきたいと思います。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"田中委員","kind":"意見","question":"中塚委員がおっしゃってくれたのですけれども、数え切れない数のトラブルと、普通に考えて怖いですし、扱っているものが個人情報なので、本当に危機管理という面でとても困ると思います。怖いです。個人番号カードに対して、私たちは不安を持っているので反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"}]},{"id":"topic-03","title":"今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、区民委員会の所管事項にかかる項目","agenda":"今定例会の一般質問にかかる所管質問ですが、今定例会の一般質問中、区民委員会の所管事項にかかる項目","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"塚本議員の一般質問で、町会・自治会条例について伺いたいと思います。この条文で、どうして自主性の担保となるのか。この質問は、今、委員長のお話があったように、ほかの議員も参加することが可能ですので、既に条文は配られていますけれども、前文や第３条の基本理念や、第４条、第５条など、抜粋でよいので、手元に資料があると議論が深まると思いますので、資料要望をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/371005?Template=document&Id=2754#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":23413,"voices":93}},{"id":"h28-20160627-7","meetingId":"h28-cm06","date":"2016年6月27日","dateIso":"2016-06-27","committee":"厚生委員会","time":"午前１０時００分～午前１１時５９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","topics":[{"id":"topic-01","title":"議案審査、(1)の第５２号議案 平成２８年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"議案審査、(1)の第５２号議案 平成２８年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何点かお聞かせいただきたいと思います。２点目に、その下のところに地域で必要とされているグループホームの整備促進を図るためということでありますけれども、その地域で必要とされているグループホームというのは、今後の需要をどういふうに考えられていて、今後どういうふうに増設計画を持っているのかということについて、まずお聞かせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"今後の整備としてどのぐらい必要かです。なかなか難しいところではあるのですが、あと５カ所程度は必要ではないかと考えているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今のお話ですと、いろいろと区のほうに相談はあったけれども、管理組合からなかなか理解が得られなかったとかということですと、この障害の方のグループホームに対する地域の理解だったりとか、マンションの管理組合、またオーナーとか、そういうところの理解がなかなか得られないということが主な理由で進まないということだったのかということの確認を１つと、それから。","respondent":"中山障害者福祉課長","answer":"設立の経過が、当事者の親御さんであったり、関係者の方がそうした場が必要だということで、それぞれの持ち物を提供し、運営をしてきましたが代が替わる中で、あるいは、相続の中で継続が難しくなってきている、そういったことも要因の１つとなっております。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、その５カ所ということは、知的を中心にということですが、いつぐらいまでにという計画があるのかを１点お聞かせいただきいたのと、本当に障害者団体の皆さんからも、グループホームというのはぜひつくってほしいという要望はいつもいつもいただいているので、今回こういう形で区が土地を購入して、積極的につくっていくことになったのは、本当に歓迎するところです。","respondent":"中山障害者福祉課長","answer":"５カ所の設置がいつぐらいまでにというようなご質問ですけれども、いつまでにというのは難しいと考えています。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に、５番のグループホームの状況ということで、事業所が１１カ所で、現在、人数が６７人ということで書いてあるのですけれども、この障害者福祉のところで見ると、２４ページのところで、グループホームの利用者が、平成２７年は１２７人ということで書いてあるのですけれども、この１２７人という数と、６７人の違いというか、なぜ差があるのかということについて教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"特に精神のグループホームですと、精神科の病院のあるところが地域移行ということでグループホームを開設したりもしておりますので、そういったところに入られている方を合わせての支給の決定数ということになっております。","id":"exchange-004"},{"speaker":"たけうち委員","kind":"確認","question":"３点なのですけれども、１つは確認ですが、障害者のグループホームとなっていますけれども、こちらは福栄会ということなので、知的のグループホームでいいかの確認と、それから、そんなに広くはないところなのであれなのだと思うのたけれども、グループホームに併設で、例えば作業所みたいなものを何か検討されたのかどうかということです。","respondent":"中山障害者福祉課長","answer":"西大井四丁目のこの地域への説明ということなのですが、まだ補正予算の段階ですので、説明が終わっているものではありません。この流れの中で、まずは町会長にご相談させていただき、地域の方々への説明会は追って区も同席でする予定です。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。今のご答弁だと、もしかすると、今後、状況に応じては何か併設みたいなこともあったのですけれども、その辺ができるのかどうかちょっとわからないのですが、そこを１つと、それから、地域の方には、ふれあい作業所とか、結構障害者の施設がある地域、町会ですので、ご理解はいただける町会だと思います。ぜひ丁寧な説明をお願いしたいと思います。１点だけお願いします。","respondent":"中山障害者福祉課長","answer":"いわゆる障害福祉サービスの併設は厳しいのではないかと考えております。ただ、福栄会も、せっかくこの地域につくるのであれば、地域の方々と交流できるようなスペースを何とかして設けられないかといったようなことは考えてくださっています。","id":"exchange-006"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"２点の質問と１点の要望なのですけれども、１つが、資料の中の上から３行目です、「民間活用型障害者サービス基盤整備事業を設置し」とあるのですけれども、説明の中でちらちら出てきたとは思うのですが、改めてこれのもう少し意味というか、お伺いしたいと思いますので、ご説明いただければと思います。","respondent":"中山障害者福祉課長","answer":"建物をつくるときの建設費の助成、整備の助成ということで、東京都が８分の７、いずれ４分の３になる予定なのですが、上限がたしか２,４００万円という補助制度があります。その相差を埋めるために８分の１を区が助成するというものです。","id":"exchange-007"}]},{"id":"topic-02","title":"の第５３号議案 平成２８年度品川区介護保険特別会計補正予算（歳出）","agenda":"の第５３号議案 平成２８年度品川区介護保険特別会計補正予算（歳出）","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"それからあとは、第５３号議案のほうに関連してなのですが、この８地区では、今立ち上がってきて、協議体も設置されるという中で、残りのところについては、支え愛・ほっとステーションが開設とあわせて位置づけていくということなのですが、見通しといいますか、なるべく今年４地区新たにできたと思うので、イメージ的には、来年度。","respondent":"松山高齢者地域支援課長","answer":"確かに未設置地区ですけれども、情報は統一しておきたいと考えていますので、地域のワークショップということだけではなくて、区全域で実施するフォーラムにもぜひご参加を募ろうと考えております。","id":"exchange-008"},{"speaker":"たけうち委員","kind":"意見","question":"２点目のほうもわかりましたのですが、まだ未開設の地区でも結構高齢化率は高いところもあったりして、どうしてもいろいろな兼ね合いの中で後になっていると思うのですけれども、やはりいざ立ち上がったときに、またそこからスタートになると、またさらに遅れていくということなので、立ち上がると当時にスムーズに追いついていけるようなという言い方はおかしいですけれども。","respondent":"松山高齢者地域支援課長","answer":"未設置地区につきましては、統括の第１層のコーディネーターが、その地区に入りまして、きちんと情報を把握し、あまりずれがないような形での配慮をしていきたいと考えています。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問","question":"ここの運営スタッフのところ、運動指導士と有償ボランティア３人程度と、これは社会福祉協議会に委託しているので、そこのボランティアセンターの活用かと思われるのですが、実際、どのような方が携わられるのか、そして、どのような方を頼りというか、想定としてこれから多分、モデル実施ですから、いろいろな各地区での展開がある中で、人材確保の点、どのような方が望ましいのか。","respondent":"松山高齢者地域支援課長","answer":"人材の点のご質問です。１点目の健康運動指導士というのは、安全で効果的な運動を実施するための運動プログラムを作成したり、実施計画上の調整を行う役割を担う方で、こちら民間資格になってあります。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"質問・要望","question":"その中で今、８地区に１６人配置と、現状こうで、これはリーダー的な役割を担うという中で、生活支援コーディネーターの同じようなあり方といいますか、どのような方をお願いし、どのような方がふさわしいか、そしてどのようなほかの方に波及していくといいますか、リーダーができて、そして地域の方がどのように関わっていくべきか、その辺の今の想定を教えてください。","respondent":"松山高齢者地域支援課長","answer":"コーディネーターがどのような人かということですけれども、コーディネーターにつきましては、やはり地域をまずは知っている方ということと、地域における助け合い活動、あるいは提供実績があるというところで、地域でのコーディネーター業務を適切に行うことができて、また。","id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問","question":"やはり一番大切なのは、地域に精通している皆さんですと言えて、なおかつ、責任もあるし、あるいは勉強論もあるのだけれどもという、この中間層と言ったらいいのですか、専門職と一般地域のというのか、この中間層をどれだけ充実するかというイメージを持っているのですが、そこにこの仕組みはとても期待できる気がしたので、その辺が今のイメージと一致するのか、地域人材の方。","respondent":"松山高齢者地域支援課長","answer":"イメージとしては、自分たちの地域を自分たちで考えて、どうやったら住みやすいまちにできるか、あるいは、自分たちができることは何なのか、少しずつ行政も一緒になって、どの団体も一緒のレベルで考えていくということが一番大事かと思ってあります。","id":"exchange-012"},{"speaker":"渡辺委員","kind":"質問・要望","question":"言葉もそうです。制度の話も。私たちは、どれだったら参加できるのかという議論がちょうどあったときに、文字どおり、あなたは向いていますとか、ぜひお願いしますと言えるような、ポイントを絞った、こういう方々が手伝っていただきたいのですということをわかりやすく投げかける必要性があるのかということを思いました。その点だけコメントをいただいて終わりたいと思います。","respondent":"松山高齢者地域支援課長","answer":"町会、自治会とか民生委員の方々、もともとベースに地域の支え愛活動があって、その上に成り立っているものですから、地域の方々のご協力なくしてはできないフォーラムやワークショップだと考えておりますので、地域の人が受けとりやすいような、あるいはこんなまちにしたい。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区としてモデルでやるということなのか、それとも国のモデル事業としてやるのかという、そこのところが１点と、それから、これは総合事業の通所型サービスＢというところになるというのが、このプレス発表の資料のところには書かれていたので、私は今回の厚生委員会の資料の中にも総合事業の体系図を載せていただいて、このサービスが住民主体による通所型サービスＢですということがわかる資料。","respondent":"松山高齢者地域支援課長","answer":"１点、国のモデルか、品川区のモデルかということですけれども、国はモデルを示していて、各自治体でそれぞれ独自に基礎自治体が必要なものをきちんとつくるという国のモデルですので、こちらは品川区のモデル、それぞれ各区、考え方なり、地域の事情がありますので。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"初回型ということは、１回だけつくれば、あとはずっとそのまま継続をして、状況が変わったら自己申告みたいな形でまた変わっていくという、そういう誰かがチェックをして見ていくという、そういうふうなところはないのかということが１つと、この初回型の……。それはいいです。それとの関係はどうなのか、そのことについてもお聞かせいただきたいと思います。","respondent":"松山高齢者地域支援課長","answer":"２つ目ですけれども、有償ボランティアの研修ですけれども、もちろん有償ボランティアがすぐに来て、高齢者の方へのこちらのサービス提供を行うものではございません。もちろん研修も予定しています。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、この有償ボランティアの方は、こういうものは初めてのことなので、なかなかイメージがつかない部分があるのですけれども、今までは有資格者がきちんとした形でやっているというのが、つまり、事業者として責任を持ってやっているというのが、今回は初めてボランティアを主体とした住民主体のこういうミニデイをやるというところで。","respondent":"松山高齢者地域支援課長","answer":"全く知識が欠けていても、もう一度、こちらの研修はしていく予定です。次に、２点目、健康運動指導士につきましては、こちらは社会福祉協議会の職員です。それから３点目、最後の質問になりますけれども、この事業の現場の責任者ということでよろしいですか。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回は週１回だけということで、需要が増えれば、今後、回数を増やすということがあるのかということと、それから、これが一番肝心だとも思いますのでお聞かせいただきたいのが、週１回の事業者が行っているデイサービスに今までは通っていたわけですが、そのデイサービスと、今回、住民主体のこういう形のミニデイというのができるわけですけれども。","respondent":"松山高齢者地域支援課長","answer":"ただ、何時間ぐらいというのは、こちらはあくまでもモデル事業ですので、どの程度、本当に研修が必要なのか、どれぐらいの方に対してどういった研修が必要なのかというのは、こちらは実施しながら一緒に考えてまいりたいと考えています。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ということは、本人が事業者のデイサービスに行きたいということであれば、その選択ができるということは保障されるということで、本人が事業者の今までのデイサービスに行きたいのだということで希望すれば、それは保障されるということで大丈夫ですかということを確認させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問","question":"地域の支え愛推進フォーラム・ワークショップについて、お伺いしたいと思います。全ての方がそうなるとは限らないと思いますけれども、そういう流れをしっかりとつくっていこうというのが、今回の目的かと思います。このフォーラムに参加をされる具体的な対象者といいましょうか、区としての見込みというのでしょうか、どのような方が来てくれることを望んでおられるのか教えてください。","respondent":"松山高齢者地域支援課長","answer":"人ごとではなくて、自分だったらどうできるかというところをまず一歩お考えいただくです。２点目のところですけれども、ワークショップ、８地区で開催されます。そちらも担い手の確保が最終的にはあります。","id":"exchange-019"},{"speaker":"浅野委員","kind":"質問","question":"確かに地域の方々がどれだけ参加していただくかで、その地域の力が大分変わってくるのかなと、差が出てきてしまう、そういう危険性といいましょうか、可能性も秘めているのではないかということがちょっと気になったところであります。できれば少人数というのでしょうか、それこそ各地区の協議体がワークショップを開くような形で、２つの部屋をつなげれば結構な人数が入れると思うのです。","respondent":"松山高齢者地域支援課長","answer":"フォーラムにつきましては、区全域を対象にしておりますので、どうしてもワークショップということですと、それぞれ地域の実情を超えた部分がありますので、フォーラムについては大きなところで、なるべく区民の方に大勢参加していただくことを願いまして。","id":"exchange-020"},{"speaker":"浅野委員","kind":"質問・要望","question":"やはり１つ気になるのは、フォーラムに参加された方がスムーズにワークショップ、自分はやりたいのだけれども、どこへ問い合わせたらいいのかわからないとか、そういうことも考えられますので、うまくフォローアップできるような、このような機会また体制もとっていただければと思いますので、これは要望になります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"松永委員","kind":"確認","question":"私からは、確認なのですけれども、大きく分けて２つありまして、１つは、１０時から１４時の間ということですが、例えばお昼ごろに、ちょっと予定があるのでと抜けることはできるのかというのが１点と、昼食代に関してですが、設定料金は幾らにしているのか教えてください。それから、この「等」というのは、ほかにどういったところに費用が発生してしまうのか教えてください。","respondent":"松山高齢者地域支援課長","answer":"昼食代については、現在考えておりますのは６００円程度を考えてあります。","id":"exchange-022"},{"speaker":"安藤副委員長","kind":"質問","question":"支え愛推進フォーラムのほうですけれども、最終的には担い手の確保につなげていきたいという話も先ほどの質疑でありましたが、なかなか担い手といいますか、いわゆるボランティアといいますか、支え愛・ほっとステーションのほうでも増えていかないという現状も事務事業概要などにもありますが、これをどのくらい増やしていきたいという考えがおありなのかということと。","respondent":"松山高齢者地域支援課長","answer":"なので、敷居を比較的低くして、介護にはならないのですけれども、要支援レベルの高齢者への支援の仕方、支援するボランティアは品川区の中でもいらっしゃると思いますので、今後、掘り起こしをしていきたいと考えています。","id":"exchange-023"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"３点目は、ボランティアの問題ですけれども、なかなか敷居が高いというところもありますというお話でしたけれども、やはり率直に言って、なかなか今、経済状況なども大変で、また高齢者の方の暮らし向きも大変で、ボランティアをやりたくても、なかなかそういう余裕がないという方もたくさんいらっしゃるのではないかと思いますので、そういったところにも思いを馳せていただいて。","respondent":"松山高齢者地域支援課長","answer":"事業内容につきましては、予防ミニデイのほうもやはり運動指導士の資格を持っていらっしゃる方もいらっしゃいますので、そういった意味では、効果的な運動を実施したり、プログラムを作成したりというようなことは同じです。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"済みません、ミニデイなのですけれども、有償ボランティアの方の時給といいますか、報酬といいますか、有償の償の部分なのですけれども、そこが幾らなのかを教えていただけたらと思います。","respondent":"松山高齢者地域支援課長","answer":"今のところ、１回という形ですけれども、１回２,０００円を想定しています。","id":"exchange-025"}]},{"id":"topic-03","title":"平成２８年請願第６号 特養ホームと老健施設の増設を求める請願","agenda":"平成２８年請願第６号 特養ホームと老健施設の増設を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これが今、平塚橋ができたことでどれくらいになっているのかということがわかったら教えていただきたいのと、その後、１０２名、来年、上大崎のみやこ荘跡にできる計画ですけれども、それでもまだまだ特養ホームは足りないと思うのです。この半年間で７０名増えたということからしても、やはりまだまだ足りないと思うのてすけれども、そこの認識はいかがでしょうか。","respondent":"大串福祉計画課長","answer":"先ほど言った上大崎、それから北品川の老健、これのほかにもグループホームですとか、あるいは小規模多機能型居宅介護ですとか、そういった形の施設の整備も行っておりますし、それとあわせて、先ほど来、審議がありましたような総合事業の展開ですとか、そういったソフトの関係。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それで、一般質問の中でも述べたのですけれども、ずっとこの先も４０年くらいは高齢者人口が、区の推計でも増え続けるという状況の中で、部長の答弁で、こうだったのではないかと思うのですけれども、たしか４カ所目をつくるにしても、土地の確保がまず第一ですということで、上大崎の後につくるというところでは、区としても方針は持っているということで、土地さえ確保されれば。","respondent":"大串福祉計画課長","answer":"ただ、先般お答えしましたように、特養あるいは施設、こういったもののニーズ、これを必要とする方、こういった方たちの身体状況ですとか、あるいはご家族の思い、こういったものも最大限考慮すべきものと考えていますし、また、介護保険の全体への影響も考えながら。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私の質問に答弁していただきたいのですけれども、私は特養ホームについて伺っているのです。特養ホームが足りないという認識はないのかということと、４カ所目を、当然４カ所目が欲しいと、適地を探しているという、そういうふうな答弁だったわけですから、そういうところでいいのかということの確認をさせていただきたいというところです。２６万円。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だから、介護保険料を特養ホームをつくったことで引き上げるという、そういうことにはならないのではないかということではないのですけれども、特定施設との関係で特養ホームをつくらなかったとしても、特定施設のほうで巨額の介護保険を使うというふうなことになっていく、それが不平等になっているのではないかというふうなところに関していかがでしょうか。","respondent":"大串福祉計画課長","answer":"特定施設に関してですけれども、こちらにつきましても、基本的には開設等々につきましては、区のほうでの考え方を反映させているところですし、そうしたものとあわせながらも、今おっしゃられているような特養あるいは老健の整備と介護保険料の関係といったものについても。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこがないことが、本当にテレビの報道でもいろいろと高齢者の介護を、先日もご主人が１０年以上介護を続けてきた奥さんを介護殺人という形で命を奪ったという、そういうふうな本当に痛ましい報道もされておりますけれども、私はそういう状況をつくらないためにも、やはり特養ホームは４カ所目が当然欲しいということで、はっきりと言われたわけですから、みやこ荘跡ができてから。","respondent":"大串福祉計画課長","answer":"施設の整備につきましても、先ほど来申し上げているとおりですし、そういった施設整備あるいは総合事業の展開、あるいは様々な取り組み、こういったものを含めて、日々検討しています。","id":"exchange-030"},{"speaker":"安藤副委員長","kind":"質問","question":"１つは、一般質問で鈴木（ひ）委員のほうで質問しましたところで、林試の森公園隣の小山台住宅跡地の活用をして特養ホームをつくるべきだということで質問させていただいたのですが、部長から、この跡地の活用については、東京都の公園と隣り合っているので、東京都と連携して進めるという答弁だったのですけれども、この跡地の活用の中に特養ホームの整備というのは入っているのか、そちらの答弁は。","respondent":"大串福祉計画課長","answer":"最初にございました小山台の関係です。こちらにつきましては、災害時の広域避難場所である都立公園に隣接ということで、その活用については東京都とも連携しながら検討を進めているというふうにお答えしたとおりです。それから、人口ビジョンとの関係です。","id":"exchange-031"},{"speaker":"安藤副委員長","kind":"質問","question":"もう１回お伺いしたいのですが、都と相談しながら検討を進めているということですが、その検討の中にぜひ特養ホームも入れるべきだというのが私たちの考えではありますが、入っているのかどうか、特養ホームの整備がその検討の中に入っているかどうか、もう一度お伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"渡辺委員","kind":"意見","question":"結論を出すということで。結論については不採択。というのは、請願項目、この請願自体、今のご説明、質疑もそうですが、既に高齢者施策において、必要性、あるいは認識はもうされている。そして、それは総合的に適切な対応がなされていることもポイントです。そして、この請願項目を踏まえた施策または事業の検討が既にもう進行している案件のため、不採択という考え方です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問","question":"これからもそういう適地、また費用対効果を見ながら、増設できるのであれば増設すると言っているわけですから、既にやっていることです。これからどんどん高齢社会で増えていって、希望する方が全員特養に入れれば一番ベストだけれども、そんなことが財政的にできるかどうか、そこを皆さん方がよくどれだけ、計画計画と言うのだったら、自分たちで計画を出して、それをしっかり載せればいいではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"結論を出す。採択です。やっている、やっているということですけれども、みやこ荘跡の計画がないので、そのみやこ荘跡の計画をしっかりとつくって具体化してほしいということをずっと言っているわけです。しかも、小山台住宅跡、荏原第四中学校跡、そういうふうなところが具体的に出てきているわけですから、ここに具体化してほしい、そういう思いで、これは採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"松永委員","kind":"意見","question":"本日、結論を出すで、不採択でお願いいたします。先ほども理事者より説明がありましたように、品川区は現在も積極的に取り組んでいると思いますので、この請願に関しては不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/349721?Template=document&Id=3448#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":36223,"voices":109}},{"id":"h28-20160627-8","meetingId":"h28-cm06","date":"2016年6月27日","dateIso":"2016-06-27","committee":"建設委員会","time":"午前１０時００分～午前１１時５６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件抜き出しています。","topics":[{"id":"topic-01","title":"第６１号議案、品川区営住宅条例の一部を改正する条例","agenda":"第６１号議案、品川区営住宅条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"法律に基づいたというところでは、私も値上げしてしまうということにはなかなか賛成できないのですけれども、この条例は、値上がってしまうものに対して減免を行うという条例ですので、反対するものではないのですが、区が出された資料のほうで、２の(2)減額措置の内容というところで、５年間にわたって急激な上昇を防ぐ、激変緩和をするということですけれども。","respondent":"今井住宅課長","answer":"こちら、条例の引用にもありますけれども、公営住宅法の第４３条および公営住宅法施行令の第１１条に基づきまして、６分の５、６分の４という形で、このような減額措置が決まっているところで、ここは法律によって定められているものです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"法律で決まっているということですけれども、それをもうちょっと年数を広げるとか、もうちょっと上げる幅を狭めていくとか、そういうことは区独自ではできないということでしょうか。","respondent":"今井住宅課長","answer":"つきましては、年数につきましては、区の判断が入るところではございません。利便性係数につきましても、こちらはエレベーターの設置等を含めまして一定の基準が定められていて、ほとんど区の緩和の余地はございません。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"意見","question":"先ほども言いましたけれども、やはり建替えに応じて値上げがされるということ自体は、なぜかなとずっと思っているところですけれども、減免は必要な措置だというところで、この条例には賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"}]},{"id":"topic-02","title":"第６２号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第６２号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この地区計画の変更ということで、都市計画審議会で可決されて今回この条例が出されていると思うのですけれども、そもそも、資料にも改正理由というのが書かれているのですけれども、この地域がこういうふうに変更されるという大もとをもうちょっと具体的に聞かせていただけないでしょうか。","respondent":"寺嶋木密整備推進課長","answer":"今回の豊町四・五・六、二葉三・四、西大井六丁目につきましては、火災危険度、建物倒壊危険度が高いということで、いわゆる木密地域不燃化１０年プロジェクトの不燃化特区という地区に指定されているエリアです。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"意見","question":"それで、高さ制限がついているということで、この高さというのは、まちの環境を見て決められる、決まった何かがあって変えられるのか、そこがよくわからないのですけれども、お願いします。","respondent":"寺嶋木密整備推進課長、鈴木建築課長","answer":"道路を広げて建て替えることができないので、ここは木造住宅が非常に密集したエリアでもありますので、重点的に建替えを促進したいということで、まず２項道路でセットバックしていただいた上に。今の補足の説明ですが、基本的には、今、木密整備推進課長がご説明したとおりなのですけれども、通常は容積率、今回の黄色で塗られたＢ－１地区、２００％なのですけれども、２項道路に面していますと。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"確認","question":"防災性の向上というところで、建替えを促進していくという目的での高さ制限だということで、よくわかりました。１０ｍ、９ｍですものね。なので、そうしてみると、そんなに高過ぎるものではないというのが確認できたので、こういった地域の皆さんへのこういうものの周知というのは、もうされているのでしょうか、これからなのでしょうか。端的にお願いします。","respondent":"寺嶋木密整備推進課長","answer":"それから昨年、まずこの地区計画を定めるときに素案説明会というのをやるのですけれども、対象エリアが大変広いので、通常、１回、２回という説明会のところ、地区を分割して９回に分けての素案説明会、それから素案説明会の意見。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この地域、不燃化に向けた木密ということで、こういう制限がかかったということだと思うのですが、この考え方というのは、ほかの地域に及んでいく可能性というのはどうなのでしょうか。","respondent":"寺嶋木密整備推進課長","answer":"地域にとって必要なまずそういったものをルール化していくということがありますので、基本的には、ルールはしなくて済めばもちろんしないほうがいいに越したことはないわけで、当然ですけれども、地元の方には一定程度ご負担が何かしらかかってくるという前提があるので。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これは業者からすると、例えば２つに分ければ建売屋が入って、買う方もついてくるけれど、失礼な言い方だけれど、中途半端な数字というか、次が使いにくい面積の土地というのがあるではないですか。１２０m2を超えていれば６０m2ずつできるけれども、分割できないような土地の場合というのは、その辺は当然考慮した上でこの地域の方も了解しているということでよろしいのですよね。","respondent":"寺嶋木密整備推進課長","answer":"要するに、大きなところで建ぺい率で考えれば、４割は空地ですから、建物が固まれば空地も固まるという概念で、そうすると、避難とか消火とかに関して非常に効果的な空地が確保できるという、その辺の防災性の必要性も含めてご説明してきた上で。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最初に全体的にと聞いたのは結局ここにひっかかってくるのだけれども、業者の立場もそうだけれども、所有者のほうを考えたときに非常に心配というか、余計な心配なのかもしれないけれども、処分がしにくいというのは非常につらいのではないかというところもあったので、ただ、今おっしゃったように、どこで切るかというのは当然どこでもあるので了解しますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"この条例は、道をなるべく広く、それから建物を６０m2、今、住宅が密集している地域を、密集を少しでも解消していくということで、６０m2という一つの線で空地をそれだけつくっていこうという狙いなのだということで、今、質疑がありましたけれども、まず、今の質疑であったかもしれないのですが、この地域の現状は、６０m2という敷地の区画というのですか。","respondent":"寺嶋木密整備推進課長","answer":"検討会当時から事業導入に向けてした調査での数値なので、若干変動はあろうかとは思うのですけれども、そのとき、３,５００棟以上の建物がこのエリアにあったというのがデータとして残っていまして、概ねですけれども、８割程度の建物は６０m2を超えていたという。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"そういう前提の中で、今後、建替え等を進めていく中でということで、密集を解消していこうということなのですけれども、建替えの促進策というのですか、条例がある以上、いずれどこかで建て替えればこの規制の中で空地が広がっていくというのは、長いスパンで考えればそういう方向性が出てくるわけですけれども、それはそれとして、すごく長いスパンで考えることになるので。","respondent":"寺嶋木密整備推進課長","answer":"先般の委員会でもご報告させていただいたとおり、本年度から始まった住替え支援、それから不燃構造化支援という形で、今、建て替えていただければこういった助成金が出ますので、ぜひお早目にやっていただきたいということをアナウンスして、よりスピーディーな対応に努める。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"結局、上に建てれば、上に伸びていけば、それだけ空地を広げつつ上に持っていくことができますよね。そうすると、その人たちに対してのアプローチというのをどういうふうにしていくのか。もともと問題としているものがあるわけで、それをするためには、そこだけでも整備しようかというところがあれば、そこも推進できるのではないかと思うのですけれども、いかがでしょうか。","respondent":"寺嶋木密整備推進課長","answer":"今、例えば、実際に行われている中延地区の同潤会のエリアとか、なかなか合意を得るということ自体がすごく大変なことなので、そういったお話がもし出てくるのであれば、きっとそういう検討をなされたとは思うのですけれども、先ほど言ったように、１０年来やってきた事業の中で。","id":"exchange-012"},{"speaker":"西本委員","kind":"意見","question":"１０年間いろいろこの地域の中で考えられた事業がこういう形なのだろうということなので、多分、状況としては、共同化というのはなかなか難しい部分があるのかと思うのですけれども、話があったときには、こういう方法もあるということをお願いしたいと思うのですが、あと、生け垣の件につきましては、公園課のほうでやっているという、なかなか知らない方もいらっしゃると思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-03","title":"第５２号議案、平成２８年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５２号議案、平成２８年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"しながわ環境ミュージカルなのですけれども、これは何で補正に加わってきたのかということと、あと、７０周年記念事業に組み込んだ経緯を聞かせていただきたいと思います。","respondent":"三ツ橋環境課長","answer":"なぜ７０周年なのかという部分に関しましては、区制７０周年記念事業の中でシティプロモーション事業を実際に行いますけれども、その点で、環境啓発という点におきましても、区制７０周年にふさわしいというものが考えられましたので、こちらを計上いたしました。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"意見","question":"大好評だったということで、そうすると、プレス発表にも７０周年記念事業が出ていまして、いろいろなことをやられるのだなとは思ったのですが、しながわ環境ミュージカル自体はいつ頃やると書いてありましたか。","respondent":"三ツ橋環境課長","answer":"こちらの日にちにつきましては、平成２９年１月２２日の日曜日です。プレス発表につきましても、日付等が記載されていなかったかもしれませんが、こちらは１月２２日ということになっております。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"それと、３０、３１ページの、立会川雨水放流管建設関連整備、ここはどういったことなのか、基本計画というのは何なのかを伺いたいと思います。","respondent":"和田河川下水道課長","answer":"当然、上流側の月見橋の家につきましては、工事が終わりましたら、月見橋の家を再建しまして、今、仮設で運営しているものを本設として戻っていっていただく予定になっております。この基本計画策定委託といいますのは、戻ってくる月見橋の家の建築の計画を行うものです。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"月見橋のデイサービスだったと思うのですけれども、そこに総務部分室もあったと思うのですが、それも変わらずといいますか、元のままに戻ってくるという形でしょうか。","respondent":"和田河川下水道課長","answer":"おっしゃるとおり、総務部分室も同様に戻ってまいります。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私たちも何度も総務部分室がどういったものなのかというのを見せていただこうといろいろしてきたのですけれども、なかなか実態がわからなくて、それで、やはり全てをデイサービスとして広げて、こちらに戻ってくるときには使っていただきたいという要望を述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"塚本委員","kind":"質問・要望","question":"幾つかあるのですけれども、まず、最初にしながわ環境ミュージカル、１回目は大変好評で、私も本番には行けませんでしたけれども、ケーブルテレビでよく放映しているのを見て、なかなか力の入った内容だなと思って見ていたのですけれども、２回目ということで、今回、５９５万１,０００円、これは１回目と比べて予算が増えているのか減っているのかというところと、増減したとすれば。","respondent":"三ツ橋環境課長、和田河川下水道課長","answer":"第１回目よりも増額しております。こちらの理由といたしましては、区制７０周年にふさわしいものとなるようバージョンアップをしたためです。つきましては、この状況をまず把握して、これを整理した上で、来年度の桜の時期を目指して、何か対策ができないかということを検討するために、この委託の計上に至ったです。","id":"exchange-019"},{"speaker":"塚本委員","kind":"質問","question":"目黒川のマナーなのですけれども、そういう危険な実態が今ありますということなのですが、これはマナーのレベルの話なのか、それとも、私も詳しくはありませんけれども、船の航行の上で、あれも免許なので、道路交通法に通じるような、船の運航上の守らなければいけない法律というのはあると思うのですけれども、そういうものに抵触する類いの話になるのかという、そこをお伺いしたい。","respondent":"三ツ橋環境課長、和田河川下水道課長","answer":"環境に配慮したことをもっと広く取り組んでいくことを思いまして、そちらが一番バージョンアップの点です。ただ、この規制を待っていては、また来年の桜の時期にご迷惑がかかると思いますので、１つはマナーの向上ということでいろいろできるということでも警視庁からも伺っていますので、警視庁とも情報交換をしながら。","id":"exchange-020"},{"speaker":"塚本委員","kind":"意見","question":"わかりました。マナーということで、今のところ、そういう取り締まりとかという話にはすぐにはならないということだと思うのですけれども、そういう危険な実態があるということであれば、特に事故等が起こることが非常に懸念されますので、ぜひ来年の桜の時期に向けて万全な対策会議等が行われるということなので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今の目黒川に関して、これはぜひお願いします。私も近くで結構見ているのですけれども、スピードを出して危ないなというのを結構見かけますので、ぜひよろしくお願いします。河川費の中で２つあるのですけれども、津波・高潮対策事業、これの中身をもう少し説明していただけますでしょうか。","respondent":"和田河川下水道課長","answer":"この目黒川避難勧告等発令基準運用検討委託というものですけれども、明日の建設委員会で、目黒川の津波発生時の避難勧告基準、これについてのご報告をする予定になっております。","id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その中身については、明日、確認をしますが、それが一点気になりました。そのもう一つ上が、水辺利活用事業追加分、防災桟橋整備、東品川清掃作業所前、これはもう大賛成、自民党からもずっと要望していた件なので、具体的にどのような形になるか、少し具体的なことを教えていただけますか。","respondent":"和田河川下水道課長","answer":"この浮き桟橋については、防災桟橋という位置づけで整備をするものなのですけれども、舟運の活性化ということをご要望いただいているということもありますし、また、１０月からもともと舟運の社会実験をやるということは昨年から決まっていたものですので、これを活用して。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それこそ舟運事業、適宜進めてもらいたいし、私どももずっと要望して、本会議でも質問ありましたけれども、自民党議員中心に議連を立ち上げたりなどもしていますので、ぜひお願いしたいと思います。去年はたしかそんなだったので、その辺、どのぐらいまで対応できるのかというのは、それは専門の方がやるのでしょうから、そういうときに対しても十分対応できるようにお願いしたいということを要望します。","respondent":"和田河川下水道課長","answer":"ここを活用させていただいて、舟運事業で活用するには、例えばトイレだとか待合所が必要だということを舟運事業者からもヒアリングで伺っていますので、あそこを船着き場として活用するための周辺整備ということで、仮設ではありますけれども、待合所とかトイレ。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、聞いて思い出しましたけれども、大田区の海老取川、そこの船着き場を一回使わせてもらったのですけれども、たしかあそこに待合所をつくって、トイレなんかも整備していたので、その辺も十分検討していただきたいと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"目黒川監視カメラ設置工事についてなのですけれども、監視カメラ設置の具体的な場所とか、幾つぐらいつけるのかをお聞きします。","respondent":"和田河川下水道課長","answer":"場所は今はっきりと申し上げられないのですけれども、というのは、この委託の中で、どの場所につければ実効性を持った監視カメラの設置ができるかということも含めて検討していきたいというふうに考えています。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"まだ検討段階ということですね。水上バイクなのですけれども、結構運河から目黒川に入ってくるパターンが多いかと思うのですけれども、将来的に運河周りに監視カメラを設置するというご予定はあるのでしょうか。","respondent":"和田河川下水道課長","answer":"今回の監視カメラの箇所数の１つに、実は先ほど説明しました東品川清掃作業所前のところにつけると、運河を見られるようにというものも計上しています。","id":"exchange-027"},{"speaker":"西本委員","kind":"確認","question":"財源を確認したいのです。今回、２８ページのところは、これは財源更正だけなのでいいのですが、３０ページの受託事業費につきましては、先ほどご説明があった中でも、下水道局のほうからいろいろ言われて、それでいろいろ考えて、変更というような、そういう流れで来たという。その辺の財源とこの事業をするにあたっての理由を聞きたいと思うのですが。","respondent":"和田河川下水道課長","answer":"３０ページ、３１ページに限って申しますと、上の４目受託事業費に係る費用については、全て東京都からの受託事業ですので、区からの持ち出しはございません。それから、６款土木費３項以下につきましては、これは品川区の単費ということになってあります。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"東京都のほうからの受託ですから、いろいろ東京都の考え方によっても大分変わってくる部分なのかなと、それは迅速に対応していく必要があると考えていますし、その一環なのだろうというふうに考えております。河川費については一般財源からのもので出されているのですけれども、補正でやるよりも、当初予算の中に入れることはできなかったのかというところだけお伺いしたいのですけれども。","respondent":"和田河川下水道課長","answer":"最後に津波・高潮対策の検討委託ですけれども、これは明日報告いたします、目黒川の氾濫と津波発生時の津波勧告基準、これが５月に庁内で決定をいたしましたので、その決定を受けて行うものですので、これも本予算には計上できなかったというものです。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"わかりました。当初予算の後に出てきた項目、それはそれで別に補正でやることに問題ないと思うのですが、１点だけ、目黒川の避難勧告、明日、報告がなされると思うのですが、１年間、いろいろと考えられてという先ほどのご説明があったと思うのです。それが、例えば去年の予算の中にあって、今回のものはまた別に何かをするためにここで計上しなくてはということなのか、それだけお願いします。","respondent":"和田河川下水道課長","answer":"ですから、基準を策定して、それを広く周知するということを想定してやってきたところなのですが、被害の状況とその規模というものを委託の中で整理をしたところ、やはりこれは区民の皆様に直接伝達する方法が必要だということが決まりましたのが今年度に入ってからということで。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"要は、１年間いろいろと試行錯誤して、いろいろ検討されていた部分があって明日発表されると思うのですが、今回、補正がかかったこの予算については、また別なことをするという意味なのですか。","respondent":"和田河川下水道課長","answer":"すみません、報告が前後して説明が難しいのですが、目黒川の氾濫と津波発生の避難基準は、こういうときにこういう情報を発令します、こういうときになったら避難勧告を発令します。","id":"exchange-031"},{"speaker":"木村副委員長","kind":"質問","question":"今の伝達方法の検討委託、基準は明日発表ですけれども、それは危険な地域の住民の方々で何か連絡を欲しいということを申請したところにはもちろんですけれども、それ以外にはどのようにして避難をさせるのですか。","respondent":"和田河川下水道課長","answer":"これも委託の中で詳しいことは検証していきますので、今、想定の範囲内で答えしますけれども、あるシステムに登録、電話番号なりメールアドレスなり、その方が一番連絡がとりやすい手段、例えば電話番号を区役所にいただけば。","id":"exchange-032"}]},{"id":"topic-04","title":"の区営住宅入居者募集","agenda":"の区営住宅入居者募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"今、ご説明の中で、私、そもそものところを伺いたいと思うのですけれども、１月と７月に募集をするということですよね。そうすると、前回が１月だったということなのですが、そのときは大体空きはどれくらいあったのかをお聞かせください。","respondent":"今井住宅課長","answer":"１月の募集につきましては、８戸です。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"この募集について本当に待ちわびているという状況なのです。私たちも、７月に募集をかけますということだったのですけれども、それがいつかいつかということで、課長にもたくさん連絡してしまって申し訳なかったのですが、やはり今回１７戸ということで、またここに多くの方が申込みをされると思うのですけれども、大体、前回１月は８戸に対してどれぐらいの募集があったかを伺いたいと思います。","respondent":"今井住宅課長","answer":"申し訳ありません、それぞれの月ごとの応募件数は手元にないのですけれども、事務事業概要にありますとおり、平成２７年度中につきましては、１月が８戸、前年の平成２７年７月が３戸で、募集数１１戸に対しまして、空き室の応募件数は５６６件でございました。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"本当になかなか狭き門といいますか、入りたくても入れない状況ですので、さらに区営住宅が増えるということが一番望ましいと私も思うのですけれども、今回、７月の１７戸についてもたくさんの応募がされるのだろうと思います。ぜひ増設を進めていくことを求めたいと思いますけれども、その点はいかがでしょうか。","respondent":"今井住宅課長","answer":"現在、区営住宅につきましては、これまでも予特・決特でご説明していますとおり、耐震改修が済みましたので、今後は長寿命化の対策の中で、建替えに伴っては従前の戸数を維持しながら運営していく考えです。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、住宅の問題は本当に私たちもたくさん相談を受ける状況ですので、安心して住めるというところでは区営住宅は本当に求められていると思いますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-05","title":"空き家対策に伴う行政代執行","agenda":"空き家対策に伴う行政代執行","exchanges":[{"speaker":"高橋（伸）委員","kind":"意見","question":"二、三台ということで、了解いたしました。今、旗の台広場公園の前のところの文教大学が工事をやっていまして、その辺、工事車両等々、あそこは一方通行路なので、交通の面も配慮していると思うのですけれども、例えば職員の方がつくとか、警備員の方がつくとか、その辺の状況もあわせてお願いします。","respondent":"今井住宅課長","answer":"文教大学付属幼稚園がありますので、そちらのほうの時間帯にはパッカー車の通行等が行かないように、今、検討を進めているところです。","id":"exchange-037"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。ぜひ幼稚園の園児さんとかもいるので、安全には十二分に配慮していただき、代執行を行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"これ、実際、コスト的にはどのぐらいのコストがかかろうとしているのかというところ、それを本人に請求するのかということで、それはどう考えられているのですか。それからご本人、この方は、いろいろな区の働きかけによってどういう対応をしていたのでしょうか。少しでも何かやれるという状況だったのか、全く無視されてしまったような状況だったのか、答えられる範囲で結構ですので。","respondent":"今井住宅課長","answer":"本人への働きかけですけれども、先ほど申しましたように、実は地域からお伺いした内容なのですけれども、旗の台広場公園等で行われます資源の回収、ペットボトルとかの回収には積極的に対応されている所有者の方というふうに聞いておりますが、ご自分の堆積物については。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"コストは６０万円程度ということなのですが、これは本人に請求がいくのかということなのです。それを今後どういうやり方をしていくのかということ。そうなると所管が変わってしまうと思うのですが、協力できる体制をとれるのであれば、協力体制をとって、また繰り返さないようにという対策も同時にとっていく必要があると思うのですが、いかがでしょうか。","respondent":"今井住宅課長","answer":"区として、全庁的に連携をして、対応していく案件だと認識しております。","id":"exchange-040"},{"speaker":"塚本委員","kind":"質問・要望","question":"区内２件目の行政代執行の予定ということですけれども、私道の一部はこの居住者の方の土地というところもあるというところがあって、どこまで撤去がされるのかというのは微妙な感じなのかと思いますが、私も現場を個人的に見に行ったことがあって、基本的には１階のほう、全部住めない状況で、こういう集めてきたものが、ごみというのか資源というのかあれですけれども、埋まっている状況の中で。","respondent":"今井住宅課長","answer":"ですので、そこから測りまして、２項道路の範囲というのはわかりますし、Ｌ字溝が設置されているということも確認しておりますので、ごみは、言ってみれば、私有地からＬ字溝を含めまして、本当の道路、２項道路に広く分散しておりますので、所有地のところにつきまして。","id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"おそらくそういうことになるのかとは思ったのですけれども、山の裾野みたいになっているので、崩れる可能性がありますよね。ぴたっとこういうふうには取り除けないと思うので、その辺は現場対応ということになるのですかね。なるべくならやっていただければありがたいのではないかと思いますけれども。","respondent":"今井住宅課長","answer":"ですので、区といたしましては、このブルーシートや白のシートは撤去しないで、上に上げて、それでごみを撤去して、それでまたシートを被せするような形で、今後、それがまた風によって飛び去らないような対応もしていきたいというふうに思っております。","id":"exchange-042"}]},{"id":"topic-06","title":"中央新幹線北品川非常口及び変電施設新設に係る工事説明会の開催","agenda":"中央新幹線北品川非常口及び変電施設新設に係る工事説明会の開催","exchanges":[{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、そもそもこの非常口と変電施設は何のために必要なのですか。","respondent":"東野まちづくり立体化担当課長","answer":"こちらの非常口につきましては、先ほどもお話しさせていただきました非常口というところで、リニア中央新幹線がこの位置を通るというところで、それに合わせてつくられるものです。変電施設も同じ、リニア新幹線の整備に係るものです。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問","question":"この工事、４ページとか３ページとかを見ても、かなり大規模なものになると思います。品川学園の近くで、そこに通われている親御さんからも心配だという声を頂戴していますので、区としても安全対策のほうをしっかりと、東海旅客鉄道株式会社のほうにも伝えていただければいいかなと思っていますけれども、今のご認識としてはどうお考えでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"それを受けまして、東海旅客鉄道は、６月６日、こちらのチラシを配布したのと同じ日なのですけれども、品川学園へ行きまして、説明をさせていただきましたという報告を受けてあります。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問","question":"工事説明会がされるということなのですけれども、こういう工事がありますということが、今も課長から説明があったように、もっと詳しくされると思うのですけれども、実際にこの工事で地域に影響が、どんなことがあるというふうに考えたらいいのでしょうか。トラックの交通だったり、騒音・振動等々、相当ある感じなのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"地域への影響ということなのですけれども、一番影響があるのが、やはり工事交通車両の通行だと思われます。これに対しましては、ピーク時で１日１６０台ぐらいということで、今、聞いているところです。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひ影響は小さいほうがいいのですけれども、こうした振動だとか騒音というのがあったとき、住民は区に言えばいいのでしょうか。それと、全国的に見ると、リニア新幹線の問題は裁判等にも発展しているところもあります。そもそも国会であまり審議がされずに進んでいるというところもあると思うのですけれども、そうした区民の思いに対しては、区はどのように対応していく予定ですか。","respondent":"東野まちづくり立体化担当課長","answer":"全国的にということで、リニアについての問題ということをどう捉えているかということなのですが、品川区、私どもといたしましては、こちらのリニア新幹線の工事につきましては、国家的なプロジェクトの位置づけということになっていると思いますので。","id":"exchange-046"},{"speaker":"西本委員","kind":"確認","question":"６ページのところに、安全対策で、工事中に交通誘導員２名、通学児童等に配慮しというところがあって、７時半から８時半とあったのですが、これは学校のほう等々に確認をされているのでしょうか。品川学園にしても、ほかの周りは、通勤の時間帯というのはいろいろ変わっている部分があるので、そこの確認をした上での時間を書かれているのかどうか、どうなっているのでしょうか。","respondent":"東野まちづくり立体化担当課長","answer":"委員おっしゃられましたとおり、通学・通勤時間帯、さまざまに変わってきているところもあると思いますけれども、一般的な時間帯、７時半から８時半というところでの設定をしているというふうに聞いてあります。","id":"exchange-047"},{"speaker":"西本委員","kind":"確認","question":"一般的というよりは、品川学園等々が近くにあるわけだから、品川学園の校長先生等々と話をして、この時間帯で大丈夫でしょうかという確認は必要なのではないかと思うのです。やはり早い場合もあるし、学校のほうが、この時間だったら大丈夫ですというふうに確認をとるととらないとでは大きな違いが出てくると思うので、その辺はいかがですか。","respondent":"東野まちづくり立体化担当課長","answer":"先ほどもお話しさせていただきました品川学園のほうには事前にご説明をされているというところで、こちらの時間についても確認をとられているというふうに理解しております。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/232335?Template=document&Id=4172#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":35556,"voices":149}}]);
